=== schematic.lini
// A 3.3 V rail — the smallest honest sheet: a linear regulator, its output
// cap, and the header it feeds. `layout: schematic` splits the children by
// role — 3+-pin parts are **anchors** and ride the scope's track row; labels
// and 1–2-pin parts are **satellites**, seated at the pin their wire touches
// and auto-posed to face back up the chain. The wires stay the router's,
// landing on fixed ports: a pin's stub tip, a label's connection point.
{
  layout: schematic;

  // A power flag is a define with intrinsic text [SPEC 8/16.4]: the symbol is
  // drawn with its connection point at the bottom, so a chain ending in one
  // grows **up** out of the pin it feeds.
  |v5::label| { symbol: power; } [
    "5V"
  ]
}

// ── anchors ──
|component#U1| "AMS1117-3.3" [
  |pin#vin| { side: left; number: 3; }
  |pin#gnd| { side: bottom; number: 1; }
  |pin#vout| { side: right; number: 2; }
]
// `pins: 4` generates p1–p4 as **one column** facing left [SPEC 16.2] — a
// connector is a header, not a bilateral part — so the header already faces
// back at the regulator; `rotate: 180` would turn the whole column the other
// way, and is read at lowering (the rail reverses, every text stays upright).
|J#J1| "JST XH" { pins: 4; }

// ── satellites ──
|C#C1| "22u"
|gnd#G1|

// ── wires ──
U1.vin - |v5|
// a chain **passes through** the cap: it enters on p1 and leaves by p2, so the
// output rail, the decoupling cap and its ground are one series statement,
// hanging off the wire that leaves `vout`
U1.vout - C1 - G1
// a net name is the wire's own label, placed along the route — a sheet writes
// it just **beside** the trace and never cuts one open [SPEC 16.4/16.5]
U1.vout - J1.p3 "3V3"
// the capsule form — a label declared where it is wired
U1.gnd - |gnd|
// a label wire — the one-ended statement mints the net tag it points at, and
// the op's end marker **shapes** it: bare `-` leaves it `plain`, so the tag is
// a **run** — the wire travels its length and the name rides over the trace,
// the sheet's own convention. A marker makes it a drawn tag instead, which is
// how a global label terminates its net.
J1.p1 -> "NSTDBY"
// `-<` points the other way, `-<>` draws both ends, `-*` rounds it — the same
// statement, four outlines. A plain run takes `side:` to pick which side of
// the trace its name sits on, and `width:` to lengthen the run under it.
J1.p2 -< "SLEEP"
// a plain run, one-ended: the wire runs its own length and the name rides
// over it — no tag drawn, no trace cut. `side:` picks which side of the trace
// the name sits on and `width:` lengthens the run beneath it; both are left at
// their defaults here, which on stacked pins is what keeps a name unambiguous.
J1.p4 - "SENSE"
=== schematic_parts.lini
// The schematic part family, at one glance — every discrete, every `symbol:`
// variant, every net-tag shape. Nothing is wired: a schematic scope places
// anchors on its own **track grid**, so `cell: c r` (ordinal, empty tracks
// collapsing) lays the catalogue out row by row. The smart label is a part's
// **value**; its id is drawn verbatim as the reference designator, and an
// anonymous part mints a display-only one from its type — R1, C1, D1…
{
  layout: schematic; gap: 40;
  // A row header is an ordinary box on the track grid — a `|caption|` would
  // pin itself out of the flow and take no cell [SPEC 5].
  |head::block| { font-size: 13; color: --muted; padding: 0 8; }
}

// The potentiometer is a three-terminal `|R|`: its wiper `w` stands on the
// body's own centre x, the two ends on its centre y [SPEC 16.3].
|head| "Passives" { cell: 1 1; }
|R#R1| "10k" { cell: 2 1; }
|R#R2| "10k" { cell: 3 1; symbol: pot; }
|R#R3| "10k" { cell: 4 1; symbol: ntc; }
|C#C1| "100n" { cell: 5 1; }
|C#C2| "47u" { cell: 6 1; symbol: polarized; }
|L#L1| "4u7" { cell: 7 1; }
|FB#FB1| "600R" { cell: 8 1; }
|F#F1| "1A" { cell: 9 1; }
|Y#Y1| "16M" { cell: 10 1; }

|head| "Diodes" { cell: 1 2; }
|D#D1| "1N4148" { cell: 2 2; }
|D#D2| "5V1" { cell: 3 2; symbol: zener; }
|D#D3| "SS34" { cell: 4 2; symbol: schottky; }
|D#D4| "SMAJ24" { cell: 5 2; symbol: tvs; }
|LED#D5| "green" { cell: 6 2; }

// One ring for every three-terminal body: the FETs wear the BJT's.
|head| "Transistors" { cell: 1 3; }
|Q#Q1| "BC847" { cell: 2 3; }
|Q#Q2| "BC857" { cell: 3 3; symbol: pnp; }
|Q#Q3| "2N7002" { cell: 4 3; symbol: nfet; }
|Q#Q4| "DMP2" { cell: 5 3; symbol: pfet; }
|opamp#U1| "TLV9061" { cell: 6 3; }
// A flip is a pose too [SPEC 16.1]: `mirror: x-axis` swaps the collector and
// emitter rows, the way a sheet stands a high-side transistor.
|Q#Q5| "BC847" { cell: 7 3; mirror: x-axis; }

|head| "Sources & switches" { cell: 1 4; }
|V#V1| "5V" { cell: 2 4; }
|V#V2| "230V" { cell: 3 4; symbol: ac; }
|I#I1| "20m" { cell: 4 4; }
|I#I2| "20m" { cell: 5 4; symbol: ac; }
|BT#BT1| "3V" { cell: 6 4; }
|BT#BT2| "12V" { cell: 7 4; symbol: battery; }
|SW#SW1| "ON" { cell: 8 4; }
|SW#SW2| "RST" { cell: 9 4; symbol: push; }

// A `|TP|` carries one pin — legal, and what a probe pad is [SPEC 16.2].
|head| "Electromechanical" { cell: 1 5; }
|M#M1| "5V fan" { cell: 2 5; }
|BZ#BZ1| "85dB" { cell: 3 5; }
|TP#TP1| "VBUS" { cell: 4 5; }

// A `|label|` is its own terminal — the net tag. `symbol:` swaps in a drawing
// from the schematic set; `shape:` picks the outline the text rides in.
|head| "Net tags" { cell: 1 6; }
|label| "NRST" { cell: 2 6; }
|label| "TX" { cell: 3 6; shape: right; }
|label| "RX" { cell: 4 6; shape: left; }
|label| "SDA" { cell: 5 6; shape: both; }
|label| "CLK" { cell: 6 6; shape: round; }
|label| "VBUS" { cell: 7 6; symbol: power; }
|label| "RF" { cell: 8 6; symbol: antenna; }

|head| "Grounds" { cell: 1 7; }
|gnd| { cell: 2 7; }
|label| { cell: 3 7; symbol: earth; }
|label| { cell: 4 7; symbol: chassis; }
|nc| { cell: 5 7; }
=== schematic_blocks.lini
// Two blocks rebuilt from a real KiCad project, wire for wire — a boost
// converter and a stepper driver — the forms a working sheet is actually
// made of: a bridge standing in its first pin's corridor with its return
// tapped into the line it feeds, a feedback divider tapped by naming the
// shared pin, net-name runs the traffic continues straight through, three
// pins tied into one net beside their part, sense shunts sharing a pin with
// the name that leaves the block, and the no-connect cross [SPEC 16].
{
  // `density:` is px per millimetre — screen resolution alone, so the paper
  // stays true-scale in print [SPEC 15.1]; 7 is what these two blocks need of
  // an A4, the parts being drawn in sheet px [SPEC 16.6].
  density: 4.7;

  // The rails both blocks ride: power flags are one-line defines with
  // intrinsic text [SPEC 8/16.4], so a chain ending in one grows up out of
  // the pin it feeds.
  |vsys::label| { symbol: power; } [
    "VSYS"
  ]
  |vm::label| { symbol: power; } [
    "VM"
  ]

  |region::group| { layout: schematic; padding: 60 20; }
}

|page| {
  sheet: a3 landscape; layout: grid; padding: 0; columns: 800, 1000; gap: 10;
} [

  |region#boost| "5.5v Boost" { cell: 1 1; } [
    |component#U6| "TPS61023DRLR" [
      |pin#VIN| { side: left; number: 3; }
      // A `|space|` is one empty slot on the rail of the pin before it, and
      // `span: N` makes it N [SPEC 16.2]: the switch node stands clear of the
      // input above and the enable below, the way the datasheet groups them,
      // so the inductor's readouts and the enable's name each keep a row.
      |space|
      |pin#SW| { side: left; number: 5; }
      |space| { span: 2; }
      |pin#EN| { side: left; number: 4; }
      |pin#GND| { side: bottom; number: 1; }
      |pin#VOUT| { side: right; number: 6; }
      // …and FB stands five slots under VOUT: the room the feedback divider
      // needs to straddle FB's row, its upper resistor above and the tapped
      // one below, so the tap comes home dead straight [SPEC 16.1].
      |space| { span: 5; }
      |pin#FB| { side: right; number: 2; }
    ]
    |C#C11| "10u"
    |L#L2| "1uH"
    // Chains off one pin take their lanes in their parts' declaration order
    // [SPEC 16.1]: the divider is declared ahead of the output bank, so it
    // stands nearest the chip and FB taps it under no cap's lead.
    |R#R15| "240k"
    |R#R16| "30k"
    |C#C12| "10u"
    |C#C13| "10u"
    |C#C14| "10u"

    // The input node: the flag and the bulk cap split off one trunk at a
    // T-junction — a pin's up-chain and down-chain share one column
    // [SPEC 16.1].
    U6.VIN - |vsys|
    U6.VIN - C11 - |gnd|
    // The boost inductor is a **bridge** — two placed ends on one part
    // [SPEC 16.1]: it stands in SW's own corridor, and the router merges
    // its far wire into the VIN net at a junction, the way a sheet taps
    // the line it feeds.
    U6.SW - L2 - U6.VIN
    U6.EN - "EN_BSTD"
    U6.GND - |gnd|
    // The output bank marches the VOUT rail, each cap forking down at a
    // junction dot [SPEC 16.5].
    U6.VOUT - |vm|
    U6.VOUT - C12 - |gnd|
    U6.VOUT - C13 - |gnd|
    U6.VOUT - C14 - |gnd|
    // The feedback divider: naming `R16.p1` in **both** statements makes
    // the midpoint a junction — explicit pins reserve first, whatever the
    // statement order [SPEC 16.5] — so FB taps between the resistors, not
    // at the rail; a bridge tapped mid-way straddles the tapping pin's row
    // [SPEC 16.1], which puts R16 on the output bank's row.
    U6.VOUT - R15 - R16.p1 - |gnd|
    U6.FB - R16.p1
  ]

  |region#stepper| "Stepper Driver" { cell: 2 1; } [
    |component#U8| "TMC2300-LA-T" [
      |pin#VS| { side: left; number: 18; }
      |pin#VCP| { side: left; number: 2; }
      |pin#STEP| { side: left; number: 4; }
      |pin#DIR| { side: left; number: 3; }
      |pin#AD0| "MS1_AD0" { side: left; number: 5; }
      |pin#AD1| "MS2_AD1" { side: left; number: 6; }
      |pin#OA1| { side: left; number: 19; }
      |pin#OA2| { side: left; number: 1; }
      |pin#OB1| { side: left; number: 17; }
      |pin#OB2| { side: left; number: 15; }
      |pin#MODE| { side: left; number: 9; }
      |pin#GND| { side: bottom; number: 21; }
      |pin#NSTDBY| "VIO/NSTDBY" { side: right; number: 11; }
      |pin#EN| { side: right; number: 7; }
      |pin#STEPPER| { side: right; number: 8; }
      |pin#PDN| "PDN_UART" { side: right; number: 10; }
      |pin#DIAG| { side: right; number: 12; }
      |pin#V18| "1.8VOUT" { side: right; number: 13; }
      |pin#BRA| { side: right; number: 20; }
      |pin#BRB| { side: right; number: 16; }
    ]
    |C#C23| "10u"
    |C#C24| "100n"
    |C#C25| "100n"
    |C#C26| "100n"
    |R#R20| "470m"
    |R#R21| "470m"

    U8.VS - |vm|
    U8.VS - C23 - |gnd|
    U8.VS - C24 - |gnd|
    // `|nc|` ships as a built-in define [SPEC 16.4]: the cross that says a
    // pin is open on purpose.
    U8.VCP - |nc|
    U8.STEP - "STEPD"
    U8.DIR - "DIRD"
    U8.AD0 - "AD0"
    U8.AD1 - "AD1"
    U8.OA1 - "COIL_A1"
    U8.OA2 - "COIL_A2"
    U8.OB1 - "COIL_B1"
    U8.OB2 - "COIL_B2"
    U8.MODE - |gnd|
    U8.GND - |gnd|
    // The enable trio is one net: pin-to-pin ties on one side draw the
    // canonical U hugging the part (ROUTING.md Fixed ports), dotted where
    // they meet.
    U8.NSTDBY - U8.EN
    U8.EN - U8.STEPPER
    // A plain name is a **run**, not a stop [SPEC 16.4]: it lies flat on
    // the shared rail — bodiless, it never yields the corridor — and the
    // tie's traffic merges along the very trace it names.
    U8.NSTDBY - "NSTDBY"
    U8.STEPPER - C25 - |gnd|
    U8.PDN - "COMM"
    U8.DIAG - |nc|
    U8.V18 - "1V8"
    U8.V18 - C26 - |gnd|
    // Each sense pin carries the name that leaves the block and its shunt:
    // the wire runs the length of the run and continues straight through
    // to the resistor — a through point, not a second lead [SPEC 16.4].
    U8.BRA - "RS_A"
    U8.BRA - R20 - |gnd|
    U8.BRB - "RS_B"
    U8.BRB - R21 - |gnd|
  ]

  |title-block| {
    title: "Boost and stepper blocks"; drawing-number: "LN-0058"; revision: "A"; sheet-number: "1/1"; date: "2026-08-31"; author: "AM";
  }
]
=== schematic_hero.lini
// A whole sheet, the way one is really drawn: an ISO page, a captioned
// `|region|` per block tiling the page's grid, and inside each of them
// `layout: schematic` — the ICs on the scope's track row, every passive seated
// at the pin it serves, and the router drawing the wires **between parts**.
// That is the point of the file: a pin that runs straight to a net label says
// nothing. Rails ride **power flags** wherever they are wanted, and only the
// six signals that genuinely leave a block are written out as net names
// [SPEC 16].
{
  // `density:` is screen resolution alone — px per millimetre — so the paper
  // stays true-scale in print [SPEC 15.1] and the number says how much circuit
  // an A3 holds: the parts are drawn in sheet px [SPEC 16.6], so 10 fits these
  // seven blocks on the sheet edge to edge.
  density: 5.5;

  // A power flag is a one-line define with intrinsic text [SPEC 8/16.4]: the
  // symbol's connection point sits at its bottom, so a chain ending in one
  // grows **up** out of the pin it feeds. Three rails and a chassis stud are
  // the sheet's global labels — the reason a rail wants no tag on every pin it
  // reaches; `|gnd|` ships as a built-in define beside them.
  |v24::label| { symbol: power; } [
    "24V"
  ]
  |v5::label| { symbol: power; } [
    "5V"
  ]
  |v3::label| { symbol: power; } [
    "3V3"
  ]
  |chassis::label| { symbol: chassis; }

  // The captioned block: a `|group|` that is its own schematic scope, so one
  // node both frames the block and seats what is inside it [SPEC 16.6]. It
  // states no `gap:` — the sheet's own coarse pitch is the lattice every part
  // centre lands on [SPEC 16.1], and a block that overrode it would draw on a
  // grid of its own.
  // …and its caption sits **inside** the frame it names, as a sheet titles
  // a block [SPEC 16.6] — a diagram's would stand above the corner, in the
  // gutter a tiled page has no room for.
  |region::group| { layout: schematic; }
}

// The page is an ordinary container inside its frame [SPEC 15.8], so the blocks
// take a grid: fixed tracks, each sized to the widest and tallest block the
// lattice draws in it, stretched to tile the sheet edge to edge. The
// bottom-right cell is left empty for the title block, which takes no cell at
// all — a `|title-block|` is pulled out of the flow and pinned flush inside the
// frame's corner [SPEC 15.8]. `padding:` clears the frame, which is inset
// 10 mm from the trimmed edge, so no block draws over it.
|page| {
  sheet: a3 landscape; layout: grid; columns: 680, 790, 610; rows: 460, 440, 500; padding: 0; gap: 24; align: stretch; justify: stretch;
} [

  |region#entry| "24 V entry" { cell: 1 1; } [
    // The high-side switch faces its feed: the pfet glyph presents the
    // channel pins on its right, and a half turn re-sides them at the fuse
    // — read at lowering, every text upright [SPEC 16.1] — so the 24 V path
    // runs straight through instead of orbiting the body.
    |Q#Q1| "AOD4185" { symbol: pfet; cell: 2 1; rotate: 180; }
    // `pins: N` gives a connector one column of pins, facing left; the header
    // sits at the sheet's edge, so it is flipped to face its circuit —
    // `mirror: y-axis` re-sides the column with pin 1 still on top, where
    // `rotate: 180` would put it at the bottom [SPEC 16.1/16.2].
    |J#J1| "JST XH" { pins: 2; cell: 1 1; mirror: y-axis; }
    |F#F1| "2A"
    |D#D1| "SMAJ24A" { symbol: tvs; }
    |R#R1| "100k"
    |C#C1| "470u" { symbol: polarized; }

    // Reverse-polarity protection. `cell:` places an anchor on the scope's own
    // track grid, so the terminal block leads and the FET follows [SPEC 16.1];
    // the fuse between them is a **two-ended** chain, its satellite dropped on
    // the line joining the two pins. The feed rides the block's **top** screw
    // and the two returns the ones below it, so the returns drop straight to
    // their studs instead of crossing back over the line they came in beside.
    J1.p1 - F1 - Q1.s
    J1.p2 - |gnd|
    // Everything the fused rail carries hangs under the one straight bus: the
    // indicator sits **after** the fuse, so a lit LED says the fuse is good.
    // Cathode first — polarity in a wire is a pin path [SPEC 16.3].
    Q1.s - D1.k - |gnd|
    Q1.g - R1 - |gnd|
    Q1.d - C1 - |gnd|
    Q1.d - |v24|
  ]

  |region#buck| "5 V buck" { cell: 2 1; } [
    |component#U1| "LM2596S-5.0" [
      |pin#VIN| { side: left; number: 1; }
      |pin#ONOFF| "ON/OFF" { side: left; number: 5; }
      |pin#GND| { side: bottom; number: 3; }
      |pin#OUT| { side: right; number: 2; }
      |pin#FB| { side: right; number: 4; }
    ]
    |C#C2| "100n"
    |R#R3| "10k"
    |L#L1| "100u"
    |D#D3| "SS54" { symbol: schottky; }
    |C#C3| "220u" { symbol: polarized; }
    |R#R4| "4k7"
    |LED#D4| "blue"

    U1.VIN - |v24|
    U1.VIN - C2 - |gnd|
    U1.ONOFF - R3 - |gnd|
    U1.GND - |gnd|
    // A chain passes **through** a two-pin part [SPEC 16.5], so the switch node,
    // the inductor and the rail flag are one statement — and the catch diode
    // forking off the same pin dots the junction.
    U1.OUT - L1 - |v5|
    U1.OUT - D3.k - |gnd|
    // The feedback tap: a wire from the far end of the inductor back into the
    // regulator, its net name carried as the link's own label [SPEC 16.5]. On
    // the fixed-output part FB *is* the rail, so the bulk cap and the
    // indicator hang there — one pin, one column, and the switch node keeps
    // its own.
    L1.p2 - U1.FB "5V"
    U1.FB - C3 - |gnd|
    U1.FB - R4 - D4 - |gnd|
  ]

  |region#ldo| "3.3 V rail" { cell: 3 1; } [
    |component#U2| "AP2112K-3.3" [
      |pin#VIN| { side: left; number: 1; }
      |pin#EN| { side: left; number: 3; }
      |pin#GND| { side: bottom; number: 2; }
      |pin#VOUT| { side: right; number: 5; }
    ]
    |C#C4| "1u"
    |R#R5| "100k"
    |C#C5| "1u"
    |R#R6| "1k"
    |LED#D5| "green"

    U2.VIN - |v5|
    U2.VIN - C4 - |gnd|
    // Two placed ends — the enable pull-up is dropped on the line between the
