#[derive(Clone, Copy, Debug, PartialEq, Default)]
pub struct Pose {
    pub rot: u32,              // 0, 90, 180, 270 (clockwise)
    pub mirror: Option<char>, // 'x' (about the x-axis) or 'y'
}

impl Pose {
    pub fn is_zero(&self) -> bool {
        self.rot == 0 && self.mirror.is_none()
    }
    pub fn classes(&self) -> Vec<String> {
        let mut v = Vec::new();
        if self.rot != 0 {
            v.push(format!("lini-pose-{}", self.rot));
        }
        if let Some(m) = self.mirror {
            v.push(format!("lini-mirror-{}", m));
        }
        v
    }
    pub fn vertical(&self) -> bool {
        self.rot == 90 || self.rot == 270
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Dir {
    L,
    R,
    U,
    D,
}

impl Dir {
    pub fn opposite(self) -> Dir {
        match self {
            Dir::L => Dir::R,
            Dir::R => Dir::L,
            Dir::U => Dir::D,
            Dir::D => Dir::U,
        }
    }
    pub fn horizontal(self) -> bool {
        matches!(self, Dir::L | Dir::R)
    }
    fn of_side(s: &str) -> Option<Dir> {
        Some(match s {
            "left" => Dir::L,
            "right" => Dir::R,
            "top" => Dir::U,
            "bottom" => Dir::D,
            _ => return None,
        })
    }
    fn of_vec(dx: f64, dy: f64) -> Dir {
        if dx.abs() >= dy.abs() {
            if dx < 0.0 {
                Dir::L
            } else {
                Dir::R
            }
        } else if dy < 0.0 {
            Dir::U
        } else {
            Dir::D
        }
    }
}

fn num(v: f64) -> String {
    let r = (v * 10000.0).round() / 10000.0;
    let r = if r == 0.0 { 0.0 } else { r };
    render_number(r)
}

// a point of the symbol's frame (w x h) under the pose: mirror first, then
// the clockwise turn
fn map_pt(x: f64, y: f64, w: f64, h: f64, p: Pose) -> (f64, f64) {
    let (mut x, mut y) = (x, y);
    match p.mirror {
        Some('x') => y = h - y,
        Some('y') => x = w - x,
        _ => {}
    }
    match p.rot {
        90 => (h - y, x),
        180 => (w - x, h - y),
        270 => (y, w - x),
        _ => (x, y),
    }
}

pub fn map_vec(dx: f64, dy: f64, p: Pose) -> (f64, f64) {
    let (mut dx, mut dy) = (dx, dy);
    match p.mirror {
        Some('x') => dy = -dy,
        Some('y') => dx = -dx,
        _ => {}
    }
    match p.rot {
        90 => (-dy, dx),
        180 => (-dx, -dy),
        270 => (dy, -dx),
        _ => (dx, dy),
    }
