            hoisted = true;
            match super::tree::mindmap_dir(self, kids) {
                Some((d, sp)) => super::tree::read_dir(self, Some(d), sp)?,
                None => "bilateral".to_string(),
            }
        };
        if !is("page") {
            tree_decls = Some((explicit, dir.clone(), mindmaps));
        } else {
            self.page_tree = Some((explicit, dir.clone(), mindmaps));
        }
        // `side:` reads the tree's own direction (a hoisted one aside)
        let sem = if !explicit {
            "bilateral".to_string()
        } else if hoisted {
            "column".to_string()
        } else {
            dir.clone()
        };
        let mode = super::tree::TreeMode { mindmap: !explicit, dir, level: 0, side: None, hue: None, hoisted, sem };
        if let Some(f) = self.stack.last_mut() {
            f.tree = Some(mode);
            f.plan_breaks = true;
        }
    }
    let is_page = is("page");
    let mut o = self.dispatch_family(n, o, chain)?;
    if let Some((_, e)) = self.stack.last().and_then(|f| f.sch.as_ref()).and_then(|p| p.error.as_ref()) {
        return Err(e.clone());
    }
    if is_page {
        return Ok(o);
    }
    // the family's own decls, then the tree's, then the drawing pass
    if self.in_drawing() {
        super::drawing::plane_chrome(&mut o, chain);
    }
    if let Some((explicit, dir, mindmaps)) = tree_decls {
        super::tree::container_decls(&mut o.decls, explicit, &dir, mindmaps);
    }
    if self.in_plan() {
        super::drawing::plan_decls(self, &mut o, chain);
    }
    if self.in_drawing() {
        super::drawing::chrome_after(self, &mut o, chain);
    }
    if (is("drawing") || is("stack")) && self.in_labels == 0 {
        let px = super::sheet::px_per(unit.as_deref(), self.density, !is("drawing"));
        o.decls.retain(|d| d.name != "px-per-unit");
        o.decls.push(Decl::val("px-per-unit", &px));
    }
    Ok(o)
}

fn dispatch_family(&mut self, n: &Node, mut o: ONode, chain: &[String]) -> R<ONode> {
    let is = |t: &str| chain.iter().any(|c| c == t);
    if is("page") {
        return super::page::page(self, n, o, chain);
    }
    if self.tree_check {
        return self.plain(n, o, chain);
    }
    // a schematic scope plans its wiring before its children lower; a
    // container inside a schematic wires the same way
    let (explicit_sch, keeps_wiring) = self.sch_kind(n, chain);
    let parent_sch = match self.stack.len() {
        0 | 1 => self.root_sch.is_some(),
        k => self.stack[k - 2].sch.is_some(),
    };
    // the content wired: the define bodies, then the children
    let (content, from_bodies) = self.content(n, chain);
    let inherited_sch = !explicit_sch && !content.is_empty() && parent_sch && keeps_wiring;
    if inherited_sch || explicit_sch {
        // every wire's operators before any endpoint resolves
        self.sch_ops(&content)?;
    }
    if inherited_sch {
        let plan = self.sch_plan(&content, false, from_bodies)?;
        if let Some(f) = self.stack.last_mut() {
            f.sch = Some(plan);
        }
    }
    if explicit_sch {
        if let Some(f) = self.stack.last_mut() {
            f.sch_explicit = true;
        }
        if !is("schematic") {
            // a scope of its own: the schematic spacing unless the type sets it
            let has = |name: &str| -> bool {
                n.style.iter().any(|d| d.name == name)
                    || chain.iter().any(|t| {
                        self.define(t).map_or(false, |d| d.decls.iter().any(|d| d.name == name))
                            || (t != "block"
                                && crate::types::find(t).map_or(false, |td| Decl::list(td.defaults).iter().any(|d| d.name == name)))
                    })
            };
            let mut pre = Vec::new();
            if !has("gap") {
                pre.push(Decl::val("gap", "100"));
            }
            if !has("clearance") {
                pre.push(Decl::val("clearance", "10"));
            }
            pre.extend(o.decls.drain(..));
            o.decls = pre;
        }
        let plan = self.sch_plan(&content, true, from_bodies)?;
        if let Some(f) = self.stack.last_mut() {
            f.sch = Some(plan);
        }
    }
    if super::schematic::is_part(chain)
        || ["component", "pin", "space", "label", "junction"].iter().any(|t| is(t))
    {
        self.mark("junction");
    }
    if super::schematic::is_part(chain) {
        return super::schematic::part(self, n, o, chain);
    }
    if super::schematic::is_component(chain) {
        return super::schematic::component(self, n, o, chain);
    }
    if super::schematic::is_label(chain) {
        return super::schematic::label(self, n, o, chain);
    }
    if is("table") {
        return super::table::lower(self, n, o, chain);
    }
    self.plain(n, o, chain)
}

// under a drawing or a stack, the nearest unit context (a page is one too)
pub fn in_plan(&self) -> bool {
    let k = self.stack.len();
    for f in self.stack[..k.saturating_sub(1)].iter().rev() {
        if f.chain.iter().any(|c| c == "drawing" || c == "stack") {
            return true;
        }
        if f.breaks || f.plan_breaks || f.chain.iter().any(|c| c == "page") {
            return false;
        }
    }
    matches!(self.root_layout.as_str(), "drawing" | "floorplan")
}

// inside a drawing (or a drawing scene): the nearest context decides
pub fn in_drawing(&self) -> bool {
    let k = self.stack.len();
    for f in self.stack[..k.saturating_sub(1)].iter().rev() {
        if f.chain.iter().any(|c| c == "drawing") {
            return true;
        }
        // a layout container lays its children out itself
        if f.breaks || f.chain.iter().any(|c| c == "stack") {
            return false;
        }
    }
    matches!(self.root_layout.as_str(), "drawing" | "floorplan")
}

// a node's statements: its define bodies (base first), then its
// children; and how many came from the bodies
pub fn content(&self, n: &Node, chain: &[String]) -> (Vec<Stmt>, usize) {
    let mut v: Vec<Stmt> = Vec::new();
    for t in chain.iter().rev() {
        if let Some(b) = self.define(t).and_then(|d| d.body.as_ref()) {
            v.extend(b.iter().cloned());
        }
    }
    let k = v.len();
    v.extend(n.children.iter().flatten().cloned());
    (v, k)
}

// define bodies, base first, lowered for this instance
pub fn bodies(&mut self, chain: &[String]) -> R<Vec<Item>> {
    let mut out = Vec::new();
    if self.tree_check {
        return Ok(out);
    }
    for t in chain.iter().rev() {
        if let Some(d) = self.define(t) {
            if let Some(body) = d.body.clone() {
                // a body's links never invent endpoints
                self.in_body += 1;
                let r = self.stmts(&body, &mut out);
                self.in_body -= 1;
                r?;
            }
        }
    }
    Ok(out)
}

pub fn is_group(chain: &[String]) -> bool {
    chain.iter().any(|c| c == "group") && !chain.iter().any(|c| c == "table")
}

pub fn caption(&mut self, label: &str) -> Item {
    let mut c = self.typed("caption");
    c.children.push(Self::text_item(label));
    Item::Node(c)
}

// the common lowering: label, define bodies, children
pub fn plain(&mut self, n: &Node, mut o: ONode, chain: &[String]) -> R<ONode> {
    let label = n.label.as_ref().map(|l| l.trim().to_string()).filter(|l| !l.is_empty());
    let bodies = self.bodies(chain)?;
    let mut kids = Vec::new();
    if let Some(ch) = &n.children {
        self.stmts(ch, &mut kids)?;
    }
    let prim = o.prim.clone();
    let mut children = Vec::new();
    if Self::is_group(chain) {
        children.extend(bodies);
        if let Some(l) = &label {
            let c = if self.stack.last().map_or(false, |f| f.sch_explicit) {
                let mut c = self.typed("sheet-caption");
                c.children.push(Self::text_item(l));
                Item::Node(c)
            } else {
                self.caption(l)
            };
            children.push(c);
        }
    } else if chain.iter().any(|c| c == "drawing") {
        // a view's caption sits under it
        children.extend(bodies);
        if let Some(l) = &label {
            let mut f = self.typed("footnote");
            f.children.push(Self::text_item(l));
            children.push(Item::Node(f));
        } else if o.decls.iter().any(|d| d.name == "of") {
            let mut f = self.typed("footnote");
            f.decls.push(Decl::val("of-title", "view"));
            children.push(Item::Node(f));
        }
    } else {
        match prim.as_str() {
            "line" | "poly" | "path" | "image" => {
                o.label = label.clone();
                children.extend(bodies);
            }
            "icon" => {
                if let Some(l) = &label {
                    if o.decls.iter().any(|d| d.name == "symbol") && !self.tree_check {
                        return Err(err("an icon's symbol is its label or 'symbol:', not both", n.span));
                    }
                    o.decls.push(Decl::new("symbol", l));
                }
                children.extend(bodies);
            }
            _ => {
                if let Some(l) = &label {
                    o.text_label = Some((l.clone(), bodies.len()));
                }
                children.extend(bodies);
            }
        }
    }
    children.extend(kids);
    o.children = children;
    Ok(o)
}

// ----------------------------------------------------------------- links
pub fn link(&mut self, l: &Link) -> R<Pending> {
    let mut groups = Vec::new();
    for g in &l.groups {
        let mut v = Vec::new();
        for ep in g {
            match ep {
                Endpoint::Path { text, parts, .. } => {
                    v.push(Ep::Path { text: text.clone(), name: parts[0].clone(), bare: parts.len() == 1 });

    }
    o.children = children;
    Ok(o)
}

// ------------------------------------------------------------------ wiring
#[derive(Clone, Debug, PartialEq)]
enum Kind {
    // a device: its pins' directions (after a written pose)
    // `cell:` seats a device on the scope's track grid: an anchor
    Device { pins: Vec<(String, f64, f64)>, two_pin_part: bool, fixed_pose: bool, part: bool, cell: bool },
    Label { sym: Option<String> },
    Other,
}

#[derive(Clone, Debug)]
struct Elem {
    kind: Kind,
}

// one end of a wire
#[derive(Clone, Debug, PartialEq)]
enum Term {
    Pin(String, String),
    Label(String),
    Other(String),
}

impl Term {
    fn text(&self) -> String {
        match self {
            Term::Pin(d, p) => format!("{}.{}", d, p),
            Term::Label(l) | Term::Other(l) => l.clone(),
        }
    }
}

// a planned link statement
#[derive(Clone, Debug, Default)]
pub struct Planned {
    pub hops: Vec<(String, String, String)>,
    terms: Vec<(Term, Term)>,
    // each hop's ends as written (not a pass-through exit or a bare name)
    written: Vec<(bool, bool)>,
    // run names merged onto a hop: (hop, text)
    pub extra: Vec<(usize, String)>,
    pub before: Vec<Node>,
    pub after: Vec<Node>,
    // a text end waiting for its id: (terminal, text, flag shape)
    text_end: Option<(Term, String, Option<&'static str>, String)>,
}

#[derive(Default, Debug)]
pub struct Plan {
    pub poses: HashMap<String, Pose>,
    pub links: Vec<Planned>, // by link statement order in the scope
    // the first wiring error, raised when its statement lowers
    pub error: Option<(usize, Diag)>,
}

fn gnd_like(s: &Option<String>) -> bool {
    matches!(s.as_deref(), Some("gnd") | Some("earth") | Some("chassis"))
}
fn power_like(s: &Option<String>) -> bool {
    matches!(s.as_deref(), Some("power") | Some("antenna"))
}

impl<'a> Cx<'a> {
    // reference designators count per container
    pub fn sch_counter(&mut self, prefix: &str) -> usize {
        let k = self.stack.len();
        let parent = if k >= 2 { self.stack[k - 2].cid } else { 0 };
        let key = (parent, prefix.to_string());
        let e = self.sch_counters.entry(key).or_insert(0);
        *e += 1;
        *e
    }

    pub fn sch_pose(&self, id: &str) -> Option<Pose> {
        let plan = match self.stack.iter().rev().skip(1).find_map(|f| f.sch.as_ref()) {
            Some(p) => p,
            None => self.root_sch.as_ref()?,
        };
        plan.poses.get(id).cloned()
    }

    fn elem_of(&self, n: &Node) -> Option<(String, Elem)> {
        let id = n.id.clone()?;
        let ty = n.ty.clone().unwrap_or_else(|| "box".into());
        let (_, chain) = self.chain(&ty)?;
        let kind = if is_part(&chain) {
            let pt = part_type(&chain).unwrap();
            let g = part_geo(self, n, &chain, &pt).ok()?;
            let pose = written_pose(self, n, &chain).unwrap_or_default();
            let pins: Vec<(String, f64, f64)> = g
                .pins
                .iter()
                .map(|(p, x, y)| {
                    let (a, b) = map_vec(*x, *y, pose);
                    (p.to_string(), a, b)
                })
                .collect();
            let two = g.pins.len() == 2;
            let fixed = prop(self, &n.style, &chain, "rotate").is_some();
            let cell = prop_decl(self, &n.style, &chain, "cell").is_some();
            Kind::Device { pins, two_pin_part: two, fixed_pose: fixed, part: true, cell }
        } else if is_component(&chain) {
            let pose = written_pose(self, n, &chain).unwrap_or_default();
            let mut pins = Vec::new();
            let mut list: Vec<(String, Option<String>)> = Vec::new();
            if chain.iter().any(|c| c == "J") {
                if let Some(k) = prop(self, &n.style, &chain, "pins").and_then(|s| s.parse::<f64>().ok()) {
                    for i in 1..=(k.max(0.0) as usize) {
                        list.push((format!("p{}", i), Some("left".into())));
                    }
                }
            }
            for s in n.children.as_deref().unwrap_or(&[]) {
                if let Some(c) = node_is(self, s, "pin") {
                    if let Some(pid) = &c.id {
                        let side = prop(self, &c.style, &chain_of(self, c), "side").filter(|s| Dir::of_side(s).is_some());
                        list.push((pid.clone(), side));
                    }
                }
            }
            let autos = list.iter().filter(|(_, s)| s.is_none()).count();
            let half = (autos + 1) / 2;
            let mut k = 0;
            for (pid, side) in &list {
                let s = match side {
                    Some(s) => s.clone(),
                    None => {
                        k += 1;
                        if k <= half {
                            "left".into()
                        } else {
                            "right".into()
                        }
                    }
                };
                let (dx, dy) = match s.as_str() {
                    "left" => (-1.0, 0.0),
                    "right" => (1.0, 0.0),
                    "top" => (0.0, -1.0),
                    _ => (0.0, 1.0),
                };
                let (a, b) = map_vec(dx, dy, pose);
                pins.push((pid.clone(), a, b));
            }
            let fixed = n.style.iter().any(|d| d.name == "rotate");
            let two = pins.len() == 2;
            let cell = n.style.iter().any(|d| d.name == "cell");
            Kind::Device { pins, two_pin_part: two, fixed_pose: fixed, part: false, cell }
        } else if is_label(&chain) {
            Kind::Label { sym: symbol_of(self, n, &chain) }
        } else {
            Kind::Other
        };
        Some((id, Elem { kind }))
    }

    // every wire's operators in a scope (its own links: a container inside
    // checks its own as it lowers)
    pub fn sch_ops(&self, stmts: &[Stmt]) -> R<()> {
        for s in stmts {
            if let Stmt::Link(l) = s {
                wire_ops(l)?;
            }
        }
        Ok(())
    }

    // (a schematic scope of its own, a container that keeps its parent's wiring)
    pub fn sch_kind(&self, n: &Node, chain: &[String]) -> (bool, bool) {
        let is = |t: &str| chain.iter().any(|c| c == t);
        let own_layout = own(&n.style, "layout");
        let layout = own_layout.clone().or_else(|| {
            chain.iter().find_map(|t| {
                self.define(t).and_then(|d| d.decls.iter().rev().find(|d| d.name == "layout").and_then(|d| d.first().map(|s| s.to_string())))
            })
        });
        let explicit = is("schematic") || layout.as_deref() == Some("schematic");
        let keeps = !["drawing", "sequence", "chart", "pie", "topic"].iter().any(|t| is(t))
            && !matches!(own_layout.as_deref(), Some("drawing") | Some("floorplan") | Some("sequence") | Some("chart") | Some("pie") | Some("tree"));
        (explicit, keeps)
    }

    // plan a schematic scope: the wires of its link statements and the poses
    // (the first `lenient` statements come from define bodies: their unknown
    // names pass as written)
    pub fn sch_plan(&mut self, stmts: &[Stmt], placed: bool, lenient: usize) -> R<Plan> {
        let mut elems: HashMap<String, Elem> = HashMap::new();
        for s in stmts {
            if let Stmt::Node(n) = s {
                if let Some((id, e)) = self.elem_of(n) {
                    elems.insert(id, e);
                }
            }
        }
        let mut plan = Plan::default();
        // pins named anywhere in the scope are not handed to bare references
        let mut used: HashMap<String, Vec<String>> = HashMap::new();
        for s in stmts {
            if let Stmt::Link(l) = s {
                for g in &l.groups {
                    for ep in g {
                        if let Endpoint::Path { parts, .. } = ep {
                            if parts.len() > 1 {
                                if let Some(Elem { kind: Kind::Device { two_pin_part: true, .. } }) = elems.get(&parts[0]) {
                                    used.entry(parts[0].clone()).or_default().push(parts[1].clone());
                                }
                            }
                        }
                    }
                }
            }
        }
        let mut caps = 0usize;
        let mut syms: HashMap<String, Option<String>> = HashMap::new();
        for (id, e) in &elems {
            if let Kind::Label { sym } = &e.kind {
                syms.insert(id.clone(), sym.clone());
            }
        }
        for (si, s) in stmts.iter().enumerate() {
            let l = match s {
                Stmt::Link(l) => l,
                _ => continue,
            };
            let mut planned = Planned::default();
            let lax = si < lenient;
            if let Err(e) = self.sch_link(l, &elems, &mut used, &mut caps, &mut planned, &mut syms, lax) {
                plan.error = Some((plan.links.len(), e));
                break;
            }
            plan.links.push(planned);
        }
        // plain runs on a wired terminal ride its first wire; the other text
        // ends become net labels, numbered in order
        let mut labels = 0usize;
        for i in 0..plan.links.len() {
            let te = match plan.links[i].text_end.clone() {
                Some(t) => t,
                None => continue,
            };
            let (term, text, shape, op) = te;
            if shape.is_none() {
                let mut hit = None;
                'find: for (j, pl) in plan.links.iter().enumerate() {
                    for (k, (a, b)) in pl.terms.iter().enumerate() {
                        let (xa, xb) = pl.written.get(k).cloned().unwrap_or((true, true));
                        if (*a == term && xa) || (*b == term && xb) {
                            hit = Some((j, k));
                            break 'find;
                        }
                    }
                }
                if let Some((j, k)) = hit {
                    plan.links[j].extra.push((k, text.clone()));
                    continue;
                }
            }
            labels += 1;
            let id = format!("lini-label-{}", labels);
            let mut style = Vec::new();
            if let Some(s) = shape {
                style.push(Decl::val("shape", s));
            }
            let span = Span::default();
            let nn = Node {
                ty: Some("label".into()),
                id: Some(id.clone()),
                label: Some(text.clone()),
                classes: vec![],
                style,
                children: None,
                span,
                head_span: span,
                ty_span: span,
            };
            syms.insert(id.clone(), None);
            let pl = &mut plan.links[i];
            pl.after.push(nn);
            pl.hops.push((term.text(), id.clone(), op));
            pl.terms.push((term.clone(), Term::Label(id)));
            pl.written.push((false, false));
        }
        // flags never turn
        let flags: Vec<String> = plan
            .links
            .iter()
            .flat_map(|p| p.after.iter())
            .filter(|n| n.style.iter().any(|d| d.name == "shape"))
            .filter_map(|n| n.id.clone())
            .collect();
        let chains: Vec<Vec<(Term, Term)>> = plan.links.iter().map(|p| p.terms.clone()).collect();
        let mut poses: HashMap<String, Pose> = HashMap::new();
        if placed {
            solve(&elems, &chains, &syms, &mut poses);
        }
        for f in flags {
            poses.remove(&f);
        }
        plan.poses = poses;
        Ok(plan)
    }

    fn sch_link(
        &mut self,
        l: &Link,
        elems: &HashMap<String, Elem>,
        used: &mut HashMap<String, Vec<String>>,
        caps: &mut usize,
        planned: &mut Planned,
        syms: &mut HashMap<String, Option<String>>,
        lax: bool,
    ) -> R<()> {
        let one_ended = l.groups.len() == 1;
        let (ops, text_shape) = wire_ops(l)?;
        // the chain's elements: (entry, exit)
        let n = l.groups.len();
        let mut xs: Vec<(bool, bool)> = Vec::new();
        let mut seq: Vec<(Term, Term)> = Vec::new();
        for (gi, g) in l.groups.iter().enumerate() {
            let ep = match g.first() {
                Some(e) => e,
                None => continue,
            };
            let middle = gi > 0 && gi + 1 < n;
            match ep {
                Endpoint::Path { parts, text, span } => {
                    let name = &parts[0];
                    let pin_named = parts.len() > 1;
                    match elems.get(name).map(|e| &e.kind) {
                        Some(Kind::Device { pins, two_pin_part, .. }) => {
                            if pin_named {
                                let p = parts[1].clone();
                                if middle && *two_pin_part {
                                    let other =
                                        pins.iter().find(|(q, _, _)| *q != p).map(|x| x.0.clone()).unwrap_or_default();
                                    let u = used.entry(name.clone()).or_default();
                                    u.push(p.clone());
                                    u.push(other.clone());
                                    seq.push((Term::Pin(name.clone(), p), Term::Pin(name.clone(), other)));
                                    xs.push((true, false));
                                } else {
                                    used.entry(name.clone()).or_default().push(p.clone());
                                    let t = Term::Pin(name.clone(), p);
                                    seq.push((t.clone(), t));
                                    xs.push((true, true));
                                }
                            } else if *two_pin_part {
                                let u = used.entry(name.clone()).or_default();
                                let free: Vec<String> =
                                    pins.iter().map(|x| x.0.clone()).filter(|p| !u.contains(p)).collect();
                                if middle && free.is_empty() {
                                    return Err(err(
                                        &format!("both pins of '{}' are wired — name one ('{}.{}')", name, name, pins[0].0),
                                        *span,
                                    ));
                                }
                                if middle {
                                    let a = free.first().cloned().unwrap_or_else(|| pins[0].0.clone());
                                    let b = pins.iter().map(|x| x.0.clone()).find(|p| *p != a).unwrap_or_default();
                                    u.push(a.clone());
                                    u.push(b.clone());
                                    seq.push((Term::Pin(name.clone(), a), Term::Pin(name.clone(), b)));
                                    xs.push((false, false));
                                } else {
                                    let a = match free.first() {
                                        Some(a) => a.clone(),
                                        None => {
                                            return Err(err(
                                                &format!(
                                                    "both pins of '{}' are wired — name one ('{}.{}')",
                                                    name, name, pins[0].0
                                                ),
                                                *span,
                                            ))
                                        }
                                    };
                                    u.push(a.clone());
                                    let t = Term::Pin(name.clone(), a);
                                    seq.push((t.clone(), t));
                                    xs.push((false, false));
                                }
                            } else if pins.len() == 1 {
                                // a one-pin device names its pin
                                let t = Term::Pin(name.clone(), pins[0].0.clone());
                                seq.push((t.clone(), t));
                                xs.push((false, false));
                            } else {
                                let t = Term::Other(text.clone());
                                seq.push((t.clone(), t));
                                xs.push((true, true));
                            }
                        }
                        Some(Kind::Label { .. }) if !pin_named => {
                            let t = Term::Label(name.clone());
                            seq.push((t.clone(), t));
                            xs.push((true, true));
                        }
                        Some(_) => {
                            let t = Term::Other(text.clone());
                            seq.push((t.clone(), t));
                            xs.push((true, true));
                        }
                        None => {
                            if !pin_named && !lax {
                                return Err(err(
                                    &format!(
                                        "'{}' is unknown — a schematic never invents a box; did you mean '- \"{}\"' (a net label)?",
                                        name, name
                                    ),
                                    *span,
                                ));
                            }
                            let t = Term::Other(text.clone());
                            seq.push((t.clone(), t));
                            xs.push((true, true));
                        }
                    }
                }
                Endpoint::Capsule { node, tail } => {
                    let id = match &node.id {
                        Some(id) => id.clone(),
                        None => {
                            *caps += 1;
                            format!("lini-cap-{}", caps)
                        }
                    };
                    let mut nn = node.clone();
                    nn.id = Some(id.clone());
                    let ty = nn.ty.clone().unwrap_or_else(|| "box".into());
                    let chain = self.chain(&ty).map(|c| c.1).unwrap_or_default();
                    let t = if is_label(&chain) {
                        syms.insert(id.clone(), symbol_of(self, &nn, &chain));
                        Term::Label(id.clone())
                    } else {
                        Term::Other(format!("{}{}", id, tail))
                    };
                    if gi == 0 {
                        planned.before.push(nn);
                    } else {
                        planned.after.push(nn);
                    }
                    seq.push((t.clone(), t));
                    xs.push((true, true));
                }
                Endpoint::Text(_) => {}
            }
        }
        for (k, w) in seq.windows(2).enumerate() {
            let a = &w[0].1;
            let b = &w[1].0;
            let op = ops.get(k).cloned().unwrap_or_else(|| "-".to_string());
            planned.hops.push((a.text(), b.text(), op));
            planned.terms.push((a.clone(), b.clone()));
            planned.written.push((xs[k].1, xs[k + 1].0));
        }
        // a one-ended wire to text: a net label (or a run, merged later)
        if one_ended {
            if let (Some(text), Some(first)) = (&l.label, seq.first()) {
                let op = ops.first().cloned().unwrap_or_else(|| "-".to_string());
                planned.text_end = Some((first.1.clone(), text.clone(), text_shape, op));
            }
        }
        Ok(())
    }
}

