pub fn render(ctx: &Ctx, out: &mut Out) -> Result<String, Diag> {
    let geos = &ctx.link_geo;
    if geos.is_empty() {
        return Ok("  <g class=\"lini-links\"/>\n".to_string());
    }
    let rules = rule_set(ctx);
    let mut s = String::from("  <g class=\"lini-links\">\n");
    let mut any_link = false;
    let mut any_label = false;
    let mut any_mask = false;
    let mut any_marker = false;
    let mut any_open = false;
    let mut dashed = false;
    let mut dotted = false;
    let mut class_marker: Vec<String> = Vec::new();
    for (gi, g) in geos.iter().enumerate() {
        let l = &ctx.links[g.li];
        if g.stray {
            stray_svg(ctx, g, &mut s, out);
            continue;
        }
        any_link = true;
        let st = &g.style;
        let mut cls = vec!["lini-link".to_string()];
        match st.line.as_str() {
            "dashed" => {
                cls.push("lini-link-dashed".into());
                dashed = true;
            }
            "dotted" => {
                cls.push("lini-link-dotted".into());
                dotted = true;
            }
            _ => {}
        }
        for c in &l.classes {
            cls.push(format!("lini-style-{}", c));
            if !out.used_classes.contains(c) {
                out.used_classes.push(c.clone());
            }
        }
        // inline style: own stroke decls
        let mut inline: Vec<(String, String)> = Vec::new();
        let mut tmpvars = Vec::new();
        for k in ["stroke", "stroke-width", "opacity"] {
            if let Some(v) = get(&st.own, k) {
                match k {
                    "stroke" => {
                        if let Some(t) = single_term(v) {
                            inline.push((k.into(), color_css(t, &mut tmpvars, v.span)?));
                        }
                    }
                    _ => {
                        if let Some(x) = value_num(&ctx.sheet.env, v) {
                            inline.push((k.into(), f4(x)));
                        }
                    }
                }
            }
        }
        if matches!(st.line.as_str(), "dashed" | "dotted") && (get(&st.own, "stroke-width").is_some() || get(&st.own, "stroke-style").is_some()) {
            if let (Some(dv), Some(rv)) = (dasharray(&st.line, st.sw), dasharray(&st.line, rules.sw)) {
                if dv != rv {
                    inline.push(("stroke-dasharray".into(), dv));
                }
            }
        }
        for v in tmpvars {
            use_var(&mut out.vars, &v);
        }
        let mut head = format!("    <g class=\"{}\"", cls.join(" "));
        if !inline.is_empty() {
            head.push_str(&format!(" style=\"{}\"", xml_escape(&css_join(&inline))));
        }
        head.push_str(&format!(
            " data-from=\"{}\" data-to=\"{}\">\n",
            xml_escape(&path_of(ctx, l.from)),
            xml_escape(&path_of(ctx, l.to))
        ));
        s.push_str(&head);
        // geometry
        let pts = &g.pts;
        let n = pts.len();
        let (first, second, penult, last) = if let Some(c) = &g.curve {
            (pts[0], c[0], c[3], pts[n - 1])
        } else {
            (pts[0], pts[1], pts[n - 2], pts[n - 1])
        };
        let ends = ends_and_markers(g, first, second, penult, last);
        any_marker |= ends.any;
        any_open |= ends.open;
        let d = if let Some(c) = &g.curve {
            format!(
                "M {} {} L {} {} C {} {} {} {} {} {} L {} {}",
                f4(ends.s.0),
                f4(ends.s.1),
                f4(c[0].0),
                f4(c[0].1),
                f4(c[1].0),
                f4(c[1].1),
                f4(c[2].0),
                f4(c[2].1),
                f4(c[3].0),
                f4(c[3].1),
                f4(ends.e.0),
                f4(ends.e.1)
            )
        } else {
            let mut wp = pts.clone();
            wp[0] = ends.s;
            wp[n - 1] = ends.e;
            if st.line == "wavy" && n == 2 {
                wave_d(wp[0], wp[1])
            } else {
                ortho_d(&wp, &g.radii)
            }
        };
        let mask_attr = if !g.cuts.is_empty() {
            any_mask = true;
            let mb = mask_box(g);
            let mut inner = format!(
                "<rect class=\"lini-cut-bg\" x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\"/>",
                f4(mb.x0),
                f4(mb.y0),
                f4(mb.w()),
                f4(mb.h())
            );
            for &(ggi, k) in &g.cuts {
                let (cx, cy, cw, ch) = geos[ggi].labels[k].cut_exact();
                inner.push_str(&format!(
                    "<rect class=\"lini-cut\" x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\"/>",
                    f4(cx),
                    f4(cy),
                    f4(cw),
                    f4(ch)
                ));
            }
            if std::env::var("LINI_DBG_MASK").is_ok() {
                let (mut x0, mut y0, mut x1, mut y1) = (f64::INFINITY, f64::INFINITY, f64::NEG_INFINITY, f64::NEG_INFINITY);
                for &(x, y) in &g.pts {
                    x0 = x0.min(x);
                    y0 = y0.min(y);
                    x1 = x1.max(x);
                    y1 = y1.max(y);
                }
                let mut v = format!("MASK {:?} {:?} {:?} {:?} {:?} {}", x0, y0, x1, y1, g.style.sw, st.line == "wavy");
                if std::env::var("LINI_DBG_PTS").is_ok() {
                    eprintln!("PTS {:?}", g.pts);
                }
                for &(ggi, k) in &g.cuts {
                    let lb = &geos[ggi].labels[k];
                    v.push_str(&format!(" | {:?} {:?} {:?} {:?} {:?} {:?}", lb.x, lb.y, lb.tw, lb.fs, lb.upem, lb.units));

                    SheetLine::Decls(ds) => {
                        let mut run: Vec<String> = Vec::new();
                        for d in ds {
                            if d.is_draw() {
                                if !run.is_empty() {
                                    self.line(2, &run.join(" "));
                                    run.clear();
                                }
                                self.draw(2, d);
                            } else {
                                run.push(d.text());
                            }
                        }
                        if !run.is_empty() {
                            self.line(2, &run.join(" "));
                        }
                    }
                    SheetLine::Line(s) => self.line(2, s),
                    SheetLine::Rule(sel, ds) => {
                        if ds.is_empty() {
                            self.line(2, &format!("{} {{}}", sel));
                        } else {
                            self.composite(2, sel.clone(), ds, Kids::None);
                        }
                    }
                }
            }
            self.line(0, "}");
            sheet_printed = true;
        }
        // a node a link declared stands with the links
        let last_non_link = items.iter().rposition(|e| !matches!(e, Item::Link(_)));
        let first_link = items.iter().position(|e| matches!(e, Item::Link(_)) || matches!(e, Item::Node(n) if n.gen));
        let link_break = match (last_non_link, first_link) {
            (Some(n), Some(l)) if l > n => Some(l),
            _ => None,
        };
        for (i, e) in items.iter().enumerate() {
            if (i == 0 && sheet_printed) || Some(i) == link_break {
                self.lines.push(String::new());
            }
            self.item(e, 0);
        }
    }

    fn draw(&mut self, indent: usize, d: &Decl) {
        let prefix = format!("{}: ", d.name);
        let col = indent + prefix.len();
        let pieces: Vec<&String> = d.groups.iter().flatten().collect();
        if pieces.is_empty() {
            self.line(indent, &format!("{} ;", prefix.trim_end()));
            return;
        }
        let mut cur = format!("{}{}{}", pad(indent), prefix, pieces[0]);
        for p in pieces.iter().skip(1) {
            if is_move(p) || cur.len() + 1 + p.len() + 1 > WIDTH {
                self.lines.push(cur);
                cur = format!("{}{}", pad(col), p);
            } else {
                cur.push(' ');
                cur.push_str(p);
            }
        }
        cur.push(';');
        self.lines.push(cur);
    }

    fn decls(&mut self, ds: &[Decl], indent: usize) {
        let mut run: Vec<String> = Vec::new();
        for d in ds {
            if d.is_draw() {
                if !run.is_empty() {
                    self.line(indent, &run.join(" "));
                    run.clear();
                }
                self.draw(indent, d);
            } else {
                run.push(d.text());
            }
        }
        if !run.is_empty() {
            self.line(indent, &run.join(" "));
        }
    }

    fn style_inline(ds: &[Decl]) -> Option<String> {
        if ds.iter().any(|d| d.is_draw() && d.groups.iter().flatten().filter(|t| is_move(t)).count() >= 2) {
            return None;
        }
        let parts: Vec<String> = ds.iter().map(|d| d.text()).collect();
        Some(format!("{{ {} }}", parts.join(" ")))
    }

    fn composite(&mut self, indent: usize, prefix: String, style: &[Decl], kids: Kids) {
        let mut cur = prefix;
        if !style.is_empty() {
            let inline = Self::style_inline(style).map(|s| format!("{} {}", cur, s));
            match inline {
                Some(l) if indent + l.len() <= WIDTH => cur = l,
                _ => {
                    self.line(indent, &format!("{} {{", cur));
                    self.decls(style, indent + 2);
                    cur = "}".to_string();
                }
            }
        }
        match kids {
            Kids::None => self.line(indent, &cur),
            Kids::Items(b, cols) => self.children(indent, cur, b, cols),
        }
    }

    fn children(&mut self, indent: usize, cur: String, b: &[Item], cols: Option<i64>) {
        let texts: Option<Vec<&OText>> = b
            .iter()
            .map(|e| match e {
                Item::Text(t) => Some(t),
                _ => None,
            })
            .collect();
        if let Some(texts) = texts {
            if let Some(n) = cols {
                self.line(indent, &format!("{} [", cur));
                self.rows(&texts, n, indent + 2);
                self.line(indent, "]");
                return;
            } else if texts.iter().all(|t| t.classes.is_empty() && t.decls.is_empty()) {
                let items: Vec<String> = texts.iter().map(|t| render_string(&t.text)).collect();
                let l = format!("{} [ {} ]", cur, items.join(" "));
                if indent + l.len() <= WIDTH {
                    self.line(indent, &l);
                    return;
                }
            }
        }
        self.line(indent, &format!("{} [", cur));
        for e in b {
            self.item(e, indent + 2);
        }
        self.line(indent, "]");
    }

    // would `prefix { style } [ "a" "b" ]` print on one line?
    fn fits_inline(&self, indent: usize, prefix: &str, style: &[Decl], kids: &[Item]) -> bool {
        let mut cur = prefix.to_string();
        if !style.is_empty() {
            match Self::style_inline(style).map(|s| format!("{} {}", cur, s)) {
                Some(l) if indent + l.len() <= WIDTH => cur = l,
                _ => cur = "}".to_string(),
            }
        }
        let items: Vec<String> = kids
            .iter()
            .map(|e| match e {
                Item::Text(t) => render_string(&t.text),
                _ => String::new(),
            })
            .collect();
        let l = format!("{} [ {} ]", cur, items.join(" "));
        indent + l.len() <= WIDTH
    }

    fn rows(&mut self, texts: &[&OText], n: i64, indent: usize) {
        let n = if n < 1 { 1 } else { n.min(1_000_000) as usize };
        let rendered: Vec<String> = texts.iter().map(|t| render_string(&t.text)).collect();
        let idx: Vec<usize> = (0..texts.len()).collect();
        let rows: Vec<&[usize]> = idx.chunks(n).collect();
        let lifted = |r: &[usize]| r.iter().any(|&i| !texts[i].classes.is_empty() || !texts[i].decls.is_empty());
        let mut widths = vec![0usize; n.min(texts.len().max(1))];
        for r in &rows {
            if lifted(r) {
                continue;
            }
            for (c, &i) in r.iter().enumerate() {
                widths[c] = widths[c].max(rendered[i].len());
            }
        }
        for r in &rows {
            if lifted(r) {
                let mut cur = String::new();
                for (c, &i) in r.iter().enumerate() {
                    let t = texts[i];
                    if c > 0 {
                        cur.push(' ');
                    }
                    cur.push_str(&rendered[i]);
                    if !t.classes.is_empty() {
                        cur.push(' ');
                        cur.push_str(&classes_text(&t.classes));
                    }
                    if !t.decls.is_empty() {
                        match Self::style_inline(&t.decls) {
                            Some(s) if indent + cur.len() + 1 + s.len() <= WIDTH => {
                                cur.push(' ');
                                cur.push_str(&s);
                            }
                            _ => {
                                self.line(indent, &format!("{} {{", cur));
                                self.decls(&t.decls, indent + 2);
                                cur = "}".to_string();
                            }
                        }
                    }
                }
                self.line(indent, &cur);
                continue;
            }
            let mut s = String::new();
            let last = r.len() - 1;
            for (c, &i) in r.iter().enumerate() {
                s.push_str(&rendered[i]);
                if c < last {
                    s.push_str(&pad(widths[c] - rendered[i].len() + 1));
                }
            }
            self.line(indent, &s);
        }
    }

    fn item(&mut self, s: &Item, indent: usize) {
        match s {
            Item::Node(n) => {
                let mut prefix = String::from("|");
                prefix.push_str(&n.prim);
                if let Some(id) = &n.id {
                    prefix.push('#');
                    prefix.push_str(id);
                }
                prefix.push('|');
                if let Some(l) = &n.label {
                    prefix.push(' ');
                    prefix.push_str(&render_string(l));
                }
                if !n.classes.is_empty() {
                    prefix.push(' ');
                    prefix.push_str(&classes_text(&n.classes));
                }
                let cols = n.decl("columns").map(tracks);
                match &n.text_label {
                    Some((l, at)) => {
                        // bare text keeps the label first; a block of
                        // children has it after the define bodies
                        let mut first = vec![Item::text(l)];
                        first.extend(n.children.iter().cloned());
                        let all_text = first.iter().all(|e| matches!(e, Item::Text(_)));
                        let plain = first.iter().all(|e| matches!(e, Item::Text(t) if t.classes.is_empty() && t.decls.is_empty()));
                        let fits = |me: &Self| -> bool {
                            let _ = me;
                            true
                        };
                        let _ = fits;
                        let use_first = all_text && (cols.is_some() || (plain && self.fits_inline(indent, &prefix, &n.decls, &first)));
                        let list = if use_first {
                            first
                        } else {
                            let mut v = n.children.clone();
                            let k = (*at).min(v.len());
                            v.insert(k, Item::text(l));
                            v
                        };
                        self.composite(indent, prefix, &n.decls, Kids::Items(&list, cols));
                    }
                    None => {
                        let kids = if n.children.is_empty() { Kids::None } else { Kids::Items(&n.children, cols) };
                        self.composite(indent, prefix, &n.decls, kids);
                    }
                }
            }
            Item::Text(t) => {
                let mut prefix = render_string(&t.text);
                if !t.classes.is_empty() {
                    prefix.push(' ');
                    prefix.push_str(&classes_text(&t.classes));
                }
                self.composite(indent, prefix, &t.decls, Kids::None);
            }
            Item::Link(l) => {
                let mut prefix = l.head.clone();
                if !l.classes.is_empty() {
                    prefix.push(' ');
                    prefix.push_str(&classes_text(&l.classes));
                }
                let kids = if l.labels.is_empty() { Kids::None } else { Kids::Items(&l.labels, None) };
                self.composite(indent, prefix, &l.decls, kids);
            }
        }
    }
}

enum Kids<'a> {
    None,
    Items(&'a [Item], Option<i64>),
}

}

// sequence fragments: their messages resolve in the diagram around them
fn is_fragment(n: &ONode) -> bool {
    n.classes.iter().any(|c| matches!(c.as_str(), "lini-loop" | "lini-alt" | "lini-opt" | "lini-else"))
}

impl<'a> Cx<'a> {
    // replace the link placeholders, declaring unresolved bare endpoints
    pub fn resolve(&mut self, items: Vec<Item>) -> Vec<Item> {
        let mut items = items;
        self.resolve_list(&mut items);
        items
    }

    // containers resolve inside out: a link sees the endpoints its
    // anonymous descendants declared
    fn resolve_list(&mut self, items: &mut Vec<Item>) {
        for it in items.iter_mut() {
            if let Item::Node(n) = it {
                if n.prim == PENDING_PRIM {
                    continue;
                }
                let mut kids = std::mem::take(&mut n.children);
                if is_fragment(n) {
                    self.resolve_nested(&mut kids);
                } else {
                    self.resolve_list(&mut kids);
                }
                n.children = kids;
            }
        }
        self.resolve_own(items);
    }

    // the scopes inside a fragment (its own messages wait for the diagram)
    fn resolve_nested(&mut self, kids: &mut Vec<Item>) {
        for it in kids.iter_mut() {
            if let Item::Node(n) = it {
                if n.prim == PENDING_PRIM {
                    continue;
                }
                let mut inner = std::mem::take(&mut n.children);
                if is_fragment(n) {
                    self.resolve_nested(&mut inner);
                } else {
                    self.resolve_list(&mut inner);
                }
                n.children = inner;
            }
        }
    }

    fn resolve_own(&mut self, items: &mut Vec<Item>) {
        // the container's own links first
        let mut i = 0;
        while i < items.len() {
            let pending = match &items[i] {
                Item::Node(n) if n.prim == PENDING_PRIM => n.id.as_ref().and_then(|s| s.parse::<usize>().ok()),
                _ => None,
            };
            if let Some(idx) = pending {
                let p = self.pendings[idx].clone();
                let mut out = Vec::new();
                self.emit_link(p, items, &[], &mut out, None);
                let k = out.len();
                items.splice(i..i + 1, out);
                i += k;
                continue;
            }
            i += 1;
        }
        // then the fragments: a sequence fragment's messages belong to the
        // diagram around it, and so do the endpoints they declare (they see
        // what the diagram sees: inside an id'd fragment, nothing)
        let mut i = 0;
        while i < items.len() {
            if !matches!(&items[i], Item::Node(n) if is_fragment(n)) {
                i += 1;
                continue;
            }
            let scope = items.clone();
            let mut kids = match &mut items[i] {
                Item::Node(n) => std::mem::take(&mut n.children),
                _ => unreachable!(),
            };
            let mut hoist: Vec<(usize, Item)> = Vec::new();
            self.resolve_fragment(&mut kids, &scope, &mut hoist);
            if let Item::Node(n) = &mut items[i] {
                n.children = kids;
            }
            // the declared endpoints follow the fragment, in the order of the
            // messages that declared them
            hoist.sort_by_key(|(k, _)| *k);
            let decl: Vec<Item> = hoist.into_iter().map(|(_, it)| it).collect();
            let n = decl.len();
            items.splice(i + 1..i + 1, decl);
            i += 1 + n;
        }
    }

    // a fragment's own messages first, then its nested fragments'; each
    // declaration keyed by the message that made it
    fn resolve_fragment(&mut self, kids: &mut Vec<Item>, outer: &[Item], hoist: &mut Vec<(usize, Item)>) {
        let mut i = 0;
        while i < kids.len() {
            let pending = match &kids[i] {
                Item::Node(n) if n.prim == PENDING_PRIM => n.id.as_ref().and_then(|s| s.parse::<usize>().ok()),
                _ => None,
            };
            match pending {
                Some(idx) => {
                    let p = self.pendings[idx].clone();
                    let mut out = Vec::new();
                    let seen: Vec<Item> = hoist.iter().map(|(_, it)| it.clone()).collect();
                    let mut made = Vec::new();
                    self.emit_link(p, outer, &seen, &mut out, Some(&mut made));
                    hoist.extend(made.into_iter().map(|it| (idx, it)));
                    let k = out.len();
                    kids.splice(i..i + 1, out);
                    i += k;
                }
                None => i += 1,
            }
        }
        for it in kids.iter_mut() {
            if let Item::Node(n) = it {
                if is_fragment(n) {
                    let mut inner = std::mem::take(&mut n.children);
                    self.resolve_fragment(&mut inner, outer, hoist);
                    n.children = inner;
                }
            }
        }
    }

    pub fn auto_box(&mut self, name: &str) -> ONode {
        let mut b = self.typed("box");
        b.id = Some(name.to_string());
        b.children.push(Self::text_item(name));
        b.gen = true;
        b
    }

    fn emit_link(
        &mut self,
        p: Pending,
        scope: &[Item],
        also: &[Item],
        out: &mut Vec<Item>,
        hoist: Option<&mut Vec<Item>>,
    ) {
        let mut before = Vec::new();
        let mut after = Vec::new();
        let mut made: Vec<String> = Vec::new();
        let mut first = true;
        for g in &p.groups {
            for ep in g {
                let decl = match ep {
                    Ep::Path { name, bare, .. } => {
                        let known = made.contains(name)
                            || visible(scope, name, &self.pendings)
                            || visible(also, name, &self.pendings);
                        if *bare && !known && !p.in_drawing {
                            made.push(name.clone());
                            Some(self.auto_box(name))
                        } else {
                            None
                        }
                    }
                    Ep::Capsule { node, .. } => {
                        let mut n = node.clone();
                        n.gen = true;
                        Some(n)
                    }
                };
                if let Some(d) = decl {
                    if first {
                        before.push(Item::Node(d));
                    } else {
                        after.push(Item::Node(d));
                    }
                }
                first = false;
            }
        }
        let mut hoist = hoist;
        match hoist.as_mut() {
            Some(h) => h.extend(before),
            None => out.extend(before),
        }
        let gtext = |g: &Vec<Ep>| g.iter().map(|e| e.text().to_string()).collect::<Vec<_>>().join(" & ");
        let link_op = p.ops.first().map_or(false, |o| !(o.starts_with('(') || o == "||"));
        if p.groups.len() < 2 || !link_op {
            // one-ended, or a dimension / flush chain: one statement
            let mut head = gtext(&p.groups[0]);
            for (k, op) in p.ops.iter().enumerate() {
                head.push(' ');
                head.push_str(op);
                if let Some(g) = p.groups.get(k + 1) {
                    head.push(' ');
                    head.push_str(&gtext(g));
                }
            }
            out.push(Item::Link(OLink { head, classes: p.classes.clone(), decls: p.decls.clone(), labels: p.labels.clone() }));
        } else {
            for k in 0..p.groups.len() - 1 {
                let op = p.ops.get(k).cloned().unwrap_or_default();
                let head = format!("{} {} {}", gtext(&p.groups[k]), op, gtext(&p.groups[k + 1]));
                out.push(Item::Link(OLink {
                    head,
                    classes: p.classes.clone(),
                    decls: p.decls.clone(),
                    labels: p.labels.clone(),
                }));
            }
        }
        out.extend(p.trail.iter().cloned());
        // hoisted declarations keep the order they were made in
        match hoist {
            Some(h) => h.extend(after),
            None => out.extend(after),
        }
    }
}

