// Circuit schematics on the compile path.
//
// The lowering is `lini desugar`'s own (src/desugar/schematic.rs): a document
// with schematic content is lowered once, and every schematic scope (a root
// `layout: schematic`, a `|schematic|`, a node or define laying out as one)
// is built from its lowered subtree — components as blocks of pin rows and
// columns with stubs and numbers, parts as drawn symbols with pin stations,
// net labels and symbols, and the wires as link statements between pins.
//
//   build.rs   the lowered items onto scene nodes and pending links
//   place.rs   the `layout: schematic` scope: anchors on the track grid,
//              satellites seated at the pins their wires touch, the flow
//              fallback for whatever has no placed end
//   wire.rs    the wires: routes between fixed ports, junction dots, net
//              names along the trace
//   draw.rs    the wires' SVG and stylesheet rules

mod build;
mod draw;
mod place;
mod wire;

use crate::ast::{Doc, Endpoint, NodeStmt, SheetItem, Stmt, Term, Value};
use crate::compile::Ctx;
use crate::desugar::{Item, Lowered, ONode};
use crate::diag::{Diag, Span};
use crate::scene::{Builder, SheetModel};
use std::cell::RefCell;

pub use draw::{extend_bbox, render_links};
pub use place::measure;
pub use wire::route;

// the default rule text of the classes the lowering introduces
pub static CLASS_DEFAULTS: &[(&str, &str)] = &[
    ("sch-line", "fill: none; stroke: --component-stroke; stroke-width: 1.5;"),
    ("sch-solid", "fill: --component-stroke; stroke: none;"),
    ("sch-tag-line", "fill: none; stroke: --label-ink; stroke-width: 1.5;"),
    ("pin-stub", "fill: none; stroke: --component-stroke; stroke-width: 1.5;"),
    ("pin-number", "color: --pin-number; font-size: 10;"),
    ("ref", "font-size: 12; font-weight: semibold;"),
    ("part-value", "font-size: 12;"),
    ("tag-outline", "stroke: --label-ink; stroke-width: 1.5; padding: 2 6;"),
    ("tag-round", "radius: 99;"),
    ("tag-flag-left", "padding: 2 6 2 14;"),
    ("tag-flag-right", "padding: 2 14 2 6;"),
    ("tag-flag-both", "padding: 2 14;"),
    ("net-run", "width: 40; padding: 0 4;"),
    ("net-run-turned", "height: 40; padding: 4 0;"),
    ("sheet-caption", "translate: 10 10; font-scale: 16 15; font-weight: semibold;"),
];

pub fn is_internal_class(name: &str) -> bool {
    CLASS_DEFAULTS.iter().any(|(n, _)| *n == name) || name.starts_with("pose-") || name.starts_with("mirror-")
}

// the part types (a drawn symbol with pin stations)
pub const PART_TYPES: &[&str] =
    &["R", "C", "L", "D", "LED", "Q", "Y", "F", "FB", "SW", "BT", "V", "I", "M", "BZ", "TP", "opamp"];

// every type of the schematic family
pub const FAMILY: &[&str] = &[
    "schematic", "component", "pin", "space", "label", "junction", "gnd", "nc", "opamp", "J", "R", "C", "L", "D", "LED",
    "Q", "Y", "F", "FB", "SW", "BT", "V", "I", "M", "BZ", "TP",
];

pub struct State {
    pub low: Lowered,
    // every lowered node with an origin, in document order: (origin, path)
    pub index: Vec<(Span, Vec<usize>)>,
    pub taken: Vec<bool>,
    pub root_scope: bool,
    pub src: String,
}

thread_local! {
    pub static STATE: RefCell<Option<State>> = const { RefCell::new(None) };
}

pub fn active() -> bool {
    STATE.with(|s| s.borrow().is_some())
}

fn index_items(items: &[Item], path: &mut Vec<usize>, out: &mut Vec<(Span, Vec<usize>)>) {
    for (k, it) in items.iter().enumerate() {
        if let Item::Node(o) = it {
            path.push(k);
            if let Some(sp) = o.origin {
                out.push((sp, path.clone()));
            }
            index_items(&o.children, path, out);
            path.pop();
        }
    }
}

fn node_at<'a>(items: &'a [Item], path: &[usize]) -> Option<&'a ONode> {
    let mut cur = items;
    let mut node = None;
    for &k in path {
        match cur.get(k) {
            Some(Item::Node(o)) => {
                node = Some(o);
                cur = &o.children;
            }
            _ => return None,
        }
    }
    node
}

// the first lowered node not yet built from this source span
pub fn take_onode(span: Span) -> Option<ONode> {
    STATE.with(|s| {
        let mut b = s.borrow_mut();
        let st = b.as_mut()?;
        let k = (0..st.index.len()).find(|&k| !st.taken[k] && st.index[k].0 == span)?;
        st.taken[k] = true;
        let path = st.index[k].1.clone();
        // its descendants are built with it
        for j in 0..st.index.len() {
            if st.index[j].1.len() > path.len() && st.index[j].1.starts_with(&path) {
                st.taken[j] = true;
            }
        }
        node_at(&st.low.items, &path).cloned()
    })
}

fn chain_has(chain: &[String], names: &[&str]) -> bool {
    chain.iter().any(|c| names.contains(&c.as_str()))
}

fn value_ident(v: &Value) -> Option<&str> {
    match v.groups.first().and_then(|g| g.first()) {
        Some(Term::Ident(s, _)) => Some(s.as_str()),
        _ => None,
    }
}

fn decls_layout_schematic(ds: &[crate::ast::Decl]) -> bool {
    ds.iter().any(|d| d.name == "layout" && value_ident(&d.value) == Some("schematic"))
}

fn stmts_need(sheet: &SheetModel, stmts: &[Stmt]) -> bool {
    for s in stmts {
        match s {
            Stmt::Node(n) => {
                if node_needs(sheet, n) {
                    return true;
                }
            }
            Stmt::Link(l) => {
                for g in &l.groups {
                    for ep in g {
                        if let Endpoint::Node(n) = ep {
                            if node_needs(sheet, n) {
                                return true;
                            }
                        }
                    }
                }
            }
            Stmt::Text(_) => {}
        }
    }
    false
}

fn node_needs(sheet: &SheetModel, n: &NodeStmt) -> bool {
    let ty = n.type_name.clone().unwrap_or_else(|| "box".to_string());
    if let Some((_, chain)) = crate::scene::type_chain(sheet, &ty) {
        if chain_has(&chain, FAMILY) {
            return true;
        }
    }
    if n.style.as_deref().map_or(false, decls_layout_schematic) {
        return true;
    }
    n.children.as_deref().map_or(false, |c| stmts_need(sheet, c))
}

// does the document need the schematic path?
pub fn detect(doc: &Doc, sheet: &SheetModel) -> bool {
    if let Some(sh) = &doc.sheet {
        for it in &sh.items {
            match it {
                SheetItem::Decl(d) if d.name == "layout" && value_ident(&d.value) == Some("schematic") => return true,
                SheetItem::Define(d) => {
                    if decls_layout_schematic(&d.decls) {
                        return true;
                    }
                    if crate::types::find(&d.base).map_or(false, |_| FAMILY.contains(&d.base.as_str())) {
                        return true;
                    }
                    if d.body.as_deref().map_or(false, |b| stmts_need(sheet, b)) {
                        return true;
                    }
                }
                SheetItem::Rule(r) if decls_layout_schematic(&r.decls) => return true,
                _ => {}
            }
        }
    }
    stmts_need(sheet, &doc.stmts)
}

// Lower the document when it has schematic content; a lowering error is the
// compile's error. The root scope takes the schematic's spacing and wash.
pub fn prepare(src: &str, doc: &Doc, sheet: &mut SheetModel) -> Result<(), Diag> {
    STATE.with(|s| *s.borrow_mut() = None);
    draw::reset();
    if !detect(doc, sheet) {
        return Ok(());
    }
    let low = crate::desugar::lower(src)?;
    let root_scope = sheet.root.iter().rev().find(|d| d.name == "layout").and_then(|d| value_ident(&d.value)) == Some("schematic");
    if root_scope {
        if let Some(crate::desugar::SheetLine::Decls(ds)) = low.sheet.first() {
            for d in ds {
                if matches!(d.name.as_str(), "gap" | "clearance" | "fill") && !sheet.root.iter().any(|x| x.name == d.name) {
                    sheet.root.extend(build::convert_decls(std::slice::from_ref(d), Span::default()));
                }
            }
        }
    }
    let mut index = Vec::new();
    index_items(&low.items, &mut Vec::new(), &mut index);
    let taken = vec![false; index.len()];
    STATE.with(|s| *s.borrow_mut() = Some(State { low, index, taken, root_scope, src: src.to_string() }));
    Ok(())
}

pub fn root_scope() -> bool {
    STATE.with(|s| s.borrow().as_ref().map_or(false, |st| st.root_scope))
}

// The root scene of a `layout: schematic` document, from the lowered items.
pub fn build_root(b: &mut Builder) -> Result<(), Diag> {
    let items = STATE.with(|s| s.borrow().as_ref().map(|st| st.low.items.clone())).unwrap_or_default();
    build::build_items(b, &items, 0, Span::default())
}

// A node that is a schematic scope builds its content from its lowered self.
pub fn claims(b: &mut Builder, ns: &NodeStmt, i: usize) -> Result<bool, Diag> {
    if !active() {
        return Ok(false);
    }
    let chain = b.nodes[i].chain.clone();
    let explicit = chain.iter().any(|c| c == "schematic")
        || ns.style.as_deref().map_or(false, decls_layout_schematic)
        || chain.iter().any(|t| b.sheet.define(t).map_or(false, |d| decls_layout_schematic(&d.decls)));
    if !explicit {
        return Ok(false);
    }
    let o = match take_onode(ns.span) {
        Some(o) => o,
        None => return Ok(false),
    };
    b.nodes[i].inline = build::convert_decls(&o.decls, ns.span);
    build::build_children(b, &o, i)?;
    Ok(true)
}

// ---------------------------------------------------------------- helpers

pub fn in_family(ctx: &Ctx, i: usize) -> bool {
    chain_has(&ctx.nodes[i].chain, FAMILY)
}

pub fn is_scope(ctx: &Ctx, i: usize) -> bool {
    ctx.comp[i].layout == "schematic"
}

// The lowered items onto scene nodes: a node's `.lini-*` classes are its
// type chain (its primitive's class last, as the original writes them), its
// other classes the user's; decls parse as written; a link statement waits in
// the builder like any other, its spans those of the statement it lowers.

use crate::ast::{Decl, Endpoint, Expr, LinkStmt, Stmt, Term, Value};
use crate::desugar::{Item, LDecl, OLink, ONode};
use crate::diag::{Diag, Span};
use crate::scene::{Builder, Node};
use crate::types::Prim;

fn prim_of(p: &str) -> Prim {
    match crate::types::find(p) {
        Some(t) => t.prim,
        None => Prim::Block,
    }
}

// (chain, user classes)
pub fn split_classes(classes: &[String], prim: &str) -> (Vec<String>, Vec<String>) {
    let mut chain = Vec::new();
    let mut user = Vec::new();
    let mut has_prim = false;
    for c in classes {
        match c.strip_prefix("lini-") {
            Some(t) if t == prim => has_prim = true,
            Some(t) => chain.push(t.to_string()),
            None => user.push(c.clone()),
        }
    }
    if has_prim || chain.is_empty() {
        chain.push(prim.to_string());
    }
    (chain, user)
}

fn set_expr_span(e: &mut Expr, sp: Span) {
    match e {
        Expr::Num(_, s) | Expr::Percent(_, s) | Expr::Ident(_, s) | Expr::Str(_, s) | Expr::Var(_, s) | Expr::Hash(_, s) => *s = sp,
        Expr::Call(_, args, s) => {
            *s = sp;
            for a in args {
                set_expr_span(a, sp);
            }
        }
        Expr::Unary(_, a, s) => {
            *s = sp;
            set_expr_span(a, sp);
        }
        Expr::Bin(_, a, b, s) => {
            *s = sp;
            set_expr_span(a, sp);
            set_expr_span(b, sp);
        }
        Expr::Ternary(a, b, c, s) => {
            *s = sp;
            set_expr_span(a, sp);
            set_expr_span(b, sp);
            set_expr_span(c, sp);
        }
        Expr::Tuple(xs, s) => {
            *s = sp;
            for x in xs {
                set_expr_span(x, sp);
            }
        }
        Expr::Block(bs, x, s) => {
            *s = sp;
            for (_, b) in bs {
                set_expr_span(b, sp);
            }
            set_expr_span(x, sp);
        }
    }
}

fn set_term_span(t: &mut Term, sp: Span) {
    match t {
        Term::Num(_, _, s) | Term::Percent(_, _, s) | Term::Ident(_, s) | Term::Str(_, s) | Term::Hash(_, s) | Term::Var(_, s) => {
            *s = sp
        }
        Term::Call(_, args, s) => {
            *s = sp;
            for a in args {
                set_expr_span(a, sp);
            }
        }
        Term::Group(e, s) => {
            *s = sp;
            set_expr_span(e, sp);
        }
        Term::Tagged(inner, _, s) => {
            *s = sp;
            set_term_span(inner, sp);
        }
    }
}

pub fn set_value_span(v: &mut Value, sp: Span) {
    v.span = sp;
    for g in v.groups.iter_mut() {
        for t in g.iter_mut() {
            set_term_span(t, sp);
        }
    }
}

pub fn set_decl_span(d: &mut Decl, sp: Span) {
    d.span = sp;
    d.name_span = sp;
    set_value_span(&mut d.value, sp);
}

// the lowered decls as the compile reads them
pub fn convert_decls(ds: &[LDecl], fallback: Span) -> Vec<Decl> {
    let mut out = Vec::new();
    for d in ds {
        let full = format!("{{{}}}", d.text());
        let lexed = match crate::lexer::lex(&full) {
            Ok(l) => l,
            Err(_) => continue,
        };
        let mut p = crate::parser::Parser::new(&lexed.tokens, &full);
        if let Ok((decls, _)) = p.parse_style_block() {
            for mut x in decls {
                let sp = if d.span == Span::default() { fallback } else { Span::new(d.span.start, d.span.start + d.name.len()) };
                set_decl_span(&mut x, sp);
                out.push(x);
            }
        }
    }
    out
}

fn dup_check(b: &Builder, scope: usize, id: &str, span: Span) -> Result<(), Diag> {
    if let Some(&prev) = b.ids.get(&(scope, id.to_string())) {
        let (pl, pc) = crate::diag::line_col(b.src, b.nodes[prev].span.start);
        return Err(Diag::error("duplicate-id", &format!("duplicate id '{}' (previously at {}:{})", id, pl, pc), span));
    }
    Ok(())
}

pub fn build_onode(b: &mut Builder, o: &ONode, parent: usize, fallback: Span) -> Result<usize, Diag> {
    let prim = prim_of(&o.prim);
    let (chain, user) = split_classes(&o.classes, &o.prim);
    let span = o.origin.unwrap_or(fallback);
    b.check_classes(&user, span)?;
    let mut n = Node::new(prim, chain, span);
    n.id = o.id.clone();
    n.classes = user;
    n.inline = convert_decls(&o.decls, span);
    n.label = o.label.clone();
    if prim == Prim::Line {
        n.text = o.label.clone();
    }
    let scope = b.child_scope(parent);
    if let Some(id) = &o.id {
        dup_check(b, scope, id, span)?;
    }
    let i = b.add(n, Some(parent));
    if let Some(id) = &o.id {
        b.ids.insert((scope, id.clone()), i);
    }
    build_children(b, o, i)?;
    Ok(i)
}

pub fn build_children(b: &mut Builder, o: &ONode, i: usize) -> Result<(), Diag> {
    let span = b.nodes[i].span;
    let kids = crate::desugar::print_children(o);
    build_items(b, &kids, i, span)
}

pub fn build_items(b: &mut Builder, items: &[Item], parent: usize, fallback: Span) -> Result<(), Diag> {
    for it in items {
        match it {
            Item::Node(o) => {
                build_onode(b, o, parent, fallback)?;
            }
            Item::Text(t) => {
                b.check_classes(&t.classes, fallback)?;
                if !t.text.is_empty() {
                    let decls = convert_decls(&t.decls, fallback);
                    let style = if decls.is_empty() { None } else { Some(decls) };
                    b.text_node(&t.text, &t.classes, style.as_ref(), fallback, parent);
                }
            }
            Item::Link(l) => {
                if let Some(ls) = link_stmt(b.src, l, fallback) {
                    let idx = b.stmt_counter;
                    b.stmt_counter += 1;
                    b.pending_links.push((parent, ls, idx));
                }
            }
        }
    }
    Ok(())
}

// an endpoint's span: where its text stands in the statement it lowers
fn find_in(src: &str, stmt: Span, text: &str) -> Option<Span> {
    let s = src.get(stmt.start..stmt.end)?;
    let b = s.as_bytes();
    let mut from = 0;
    while let Some(p) = s[from..].find(text) {
        let at = from + p;
        let end = at + text.len();
        let before_ok = at == 0 || !(b[at - 1].is_ascii_alphanumeric() || b[at - 1] == b'_' || b[at - 1] == b'-' || b[at - 1] == b'.');
        let after_ok = end >= b.len() || !(b[end].is_ascii_alphanumeric() || b[end] == b'_' || b[end] == b'-' || b[end] == b'.');
        if before_ok && after_ok {
            return Some(Span::new(stmt.start + at, stmt.start + end));
        }
        from = at + 1;
    }
    None
}

fn fix_stmt_spans(s: &mut Stmt, sp: Span) {
    match s {
        Stmt::Text(t) => {
            t.span = sp;
            if let Some(st) = t.style.as_mut() {
                for d in st.iter_mut() {
                    set_decl_span(d, sp);
                }
            }
        }
        Stmt::Node(n) => {
            n.span = sp;
            n.head_span = sp;
        }
        Stmt::Link(l) => l.span = sp,
    }
}

pub fn link_stmt(src: &str, l: &OLink, fallback: Span) -> Option<LinkStmt> {
    let text = crate::desugar::link_text(l);
    let (doc, _) = crate::parser::parse(&text).ok()?;
    let mut ls = match doc.stmts.into_iter().next() {
        Some(Stmt::Link(ls)) => ls,
        _ => return None,
    };
    let sp = l.origin.unwrap_or(fallback);
    ls.span = sp;
    for op in ls.ops.iter_mut() {
        op.1 = sp;
    }
    if let Some(lb) = ls.label.as_mut() {
        lb.1 = sp;
    }
    if let Some(st) = ls.style.as_mut() {
        for d in st.iter_mut() {
            set_decl_span(d, sp);
        }
    }
    if let Some(lbs) = ls.labels.as_mut() {
        for s in lbs.iter_mut() {
            fix_stmt_spans(s, sp);
        }
    }
    for g in ls.groups.iter_mut() {
        for ep in g.iter_mut() {
            match ep {
                Endpoint::Path(p) => {
                    let mut t = p.parts.join(".");
                    if let Some(a) = &p.anchor {
                        t.push(':');
                        t.push_str(a);
                    }
                    p.span = find_in(src, sp, &t).or_else(|| find_in(src, sp, &p.parts.join("."))).unwrap_or(sp);
                }
                Endpoint::Node(n) => {
                    n.span = sp;
                    n.head_span = sp;
                }
                Endpoint::Text(_, s) => *s = sp,
            }
        }
    }
    Some(ls)
}

