// Clockwise tangent of a side.
pub fn tangent(s: Side) -> (f64, f64) {
    match s {
        Side::Top => (1.0, 0.0),
        Side::Right => (0.0, 1.0),
        Side::Bottom => (-1.0, 0.0),
        Side::Left => (0.0, -1.0),
    }
}

