#!/usr/bin/env python3
# incremental versions of schematic.lini: print hull and boxes for each
import sys
sys.path.insert(0, '/tmp/sch/scripts')
from summ import run
from boxes import parse
import re

HEAD = '''{
  layout: schematic;
  |v5::label| { symbol: power; } [
    "5V"
  ]
}
|component#U1| "AMS1117-3.3" [
  |pin#vin| { side: left; number: 3; }
  |pin#gnd| { side: bottom; number: 1; }
  |pin#vout| { side: right; number: 2; }
]
|J#J1| "JST XH" { pins: 4; }
|C#C1| "22u"
|gnd#G1|
'''
steps = [
    'U1.vout - J1.p3 "3V3"',
    'U1.vout - C1 - G1',
    'U1.vin - |v5|',
    'U1.gnd - |gnd|',
    'J1.p1 -> "NSTDBY"',
    'J1.p2 -< "SLEEP"',
    'J1.p4 - "SENSE"',
]
which = [int(x) for x in sys.argv[1].split(',')] if len(sys.argv) > 1 else None
lines = []
for k, s in enumerate(steps):
    if which is None or k in which:
        lines.append(s)
src = HEAD + '\n'.join(lines) + '\n'
o, e, c = run(src)
if e: print(e.strip())
vb = [float(v) for v in re.search(r'viewBox="([^"]+)"', o).group(1).split()]
