input.content:
// The wiring of a schematic scope: every wire's two ends as terms — a pin's
// stub tip, a part's pin station, a label's connection point — each with
// the device (the scope's child) it belongs to, its offset from that
// device's origin and the way a wire leaves it.

use super::place::{has, is_component, is_label, is_part};
use crate::compile::Ctx;
use crate::diag::Span;

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Dir {
    L,
    R,
    U,
    D,
}

impl Dir {
    pub fn opposite(self) -> Dir {
        match self {
            Dir::L => Dir::R,
            Dir::R => Dir::L,
            Dir::U => Dir::D,
            Dir::D => Dir::U,
        }
    }
    pub fn horizontal(self) -> bool {
        matches!(self, Dir::L | Dir::R)
    }
    pub fn vec(self) -> (f64, f64) {
        match self {
            Dir::L => (-1.0, 0.0),
            Dir::R => (1.0, 0.0),
            Dir::U => (0.0, -1.0),
            Dir::D => (0.0, 1.0),
        }
    }
    pub fn of_vec(dx: f64, dy: f64) -> Dir {
        if dx.abs() >= dy.abs() {
            if dx < 0.0 {
                Dir::L
            } else {
                Dir::R
            }
        } else if dy < 0.0 {
            Dir::U
        } else {
            Dir::D
        }
    }
    pub fn of_side(s: &str) -> Option<Dir> {
        Some(match s {
            "left" => Dir::L,
            "right" => Dir::R,
            "top" => Dir::U,
            "bottom" => Dir::D,
            _ => return None,
        })
    }
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Kind {
    // a component's pin (its stub tip)
    Pin,
    // a part's pin station
    Station,
    // a symbol label (ground, supply, …)
    Symbol,
    // a net-name run: the wire travels its length
    Run,
    // a drawn tag
    Flag,
    // anything else (a device named whole)
    Other,
}

#[derive(Clone, Debug)]
pub struct Term {
    pub node: usize,
    pub dev: usize,
    pub kind: Kind,
    // the connection point from the device's origin
    pub off: (f64, f64),
    // the way a wire leaves the point
    pub dir: Dir,
    // a run's other end (the wire enters there and travels its length)
    pub through: Option<(f64, f64)>,
}

#[derive(Clone, Debug)]
pub struct Wire {
    pub li: usize,
    pub a: Term,
    pub b: Term,
    pub span: Span,
}

// a node's group origin from an ancestor's origin
pub fn origin_in(ctx: &Ctx, node: usize, anc: usize) -> (f64, f64) {
    let mut x = 0.0;
    let mut y = 0.0;
    let mut cur = node;
    while cur != anc {
        let n = &ctx.nodes[cur];
        let c = &ctx.comp[cur];
        x += n.x + c.translate.0 + n.geo_off.0;
        y += n.y + c.translate.1 + n.geo_off.1;
        match n.parent {
            Some(p) => cur = p,
            None => break,
        }
    }
    (x, y)
}

// the scope's child that holds a node
pub fn device_of(ctx: &Ctx, scope: usize, node: usize) -> Option<usize> {
    let mut cur = node;
    loop {
        let p = ctx.nodes[cur].parent?;
        if p == scope {
            return Some(cur);
        }
        cur = p;
    }
}

pub fn pose_of(ctx: &Ctx, i: usize) -> (u32, Option<char>) {
    let mut rot = 0;
    let mut mirror = None;
    for c in &ctx.nodes[i].chain {
        if let Some(r) = c.strip_prefix("pose-") {
            rot = r.parse().unwrap_or(0);
        }
        if let Some(m) = c.strip_prefix("mirror-") {
            mirror = m.chars().next();
        }
    }
    (rot, mirror)
}

// a vector under a pose: mirror first, then the clockwise turn
pub fn map_vec(dx: f64, dy: f64, rot: u32, mirror: Option<char>) -> (f64, f64) {
    let (mut dx, mut dy) = (dx, dy);
    match mirror {
        Some('x') => dy = -dy,
        Some('y') => dx = -dx,
        _ => {}
    }
    match rot {
        90 => (-dy, dx),
        180 => (-dx, -dy),
        270 => (dy, -dx),
        _ => (dx, dy),
    }
}

// a point of a w x h frame under a pose
pub fn map_pt(x: f64, y: f64, w: f64, h: f64, rot: u32, mirror: Option<char>) -> (f64, f64) {
    let (mut x, mut y) = (x, y);
    match mirror {
        Some('x') => y = h - y,
        Some('y') => x = w - x,
        _ => {}
    }
    match rot {
        90 => (h - y, x),
        180 => (w - x, h - y),
        270 => (y, w - x),
        _ => (x, y),
    }
}

fn symbol_attach(sym: &str) -> Option<(f64, f64, f64, f64)> {
    // (w, h, x, y) of the drawing at pose 0
    Some(match sym {
        "gnd" => (16.0, 15.0, 8.0, 0.0),
        "earth" => (16.0, 14.0, 8.0, 0.0),
        "chassis" => (16.0, 12.0, 8.0, 0.0),
        "power" => (16.0, 20.0, 8.0, 20.0),
        "antenna" => (20.0, 20.0, 10.0, 20.0),
        "nc" => (12.0, 10.0, 0.0, 5.0),
        _ => return None,
    })
}

fn prop_ident(ctx: &Ctx, i: usize, k: &str) -> Option<String> {
    crate::render::prop_str(ctx, i, k)
}

// a label's connection point (label-local) and the way its wire leaves
fn label_term(ctx: &Ctx, l: usize) -> Option<(Kind, (f64, f64), Dir, Option<(f64, f64)>)> {
    let (rot, mirror) = pose_of(ctx, l);
    let n = &ctx.nodes[l];
    let w = n.w;
    if has(ctx, l, "net-run") || has(ctx, l, "net-run-turned") {
        // pose 0: the wire comes in from the right and runs to the left end
        let (fx, fy) = map_vec(-1.0, 0.0, rot, mirror);
        let len = if has(ctx, l, "net-run-turned") { n.h } else { w };
        let far = (fx * len / 2.0, fy * len / 2.0);
        let near = (-far.0, -far.1);
        let dir = Dir::of_vec(-fx, -fy);
        return Some((Kind::Run, far, dir, Some(near)));
    }
    if has(ctx, l, "tag-flag-right") {
        return Some((Kind::Flag, (-w / 2.0, 0.0), Dir::L, None));
    }
    if has(ctx, l, "tag-flag-left") {
        return Some((Kind::Flag, (w / 2.0, 0.0), Dir::R, None));
    }
    if has(ctx, l, "tag-flag-both") || has(ctx, l, "tag-outline") {
        return Some((Kind::Flag, (-w / 2.0, 0.0), Dir::L, None));
    }
    let sym = prop_ident(ctx, l, "symbol")?;
    let (fw, fh, ax, ay) = symbol_attach(&sym)?;
    // the drawing node
    let path = n.children.iter().cloned().find(|&c| has(ctx, c, "sch-tag-line"))?;
    let (pw, ph) = if rot == 90 || rot == 270 { (fh, fw) } else { (fw, fh) };
    let (px, py) = map_pt(ax, ay, fw, fh, rot, mirror);
    let o = origin_in(ctx, path, l);
    // the drawing's frame sits at its group origin
    let _ = (pw, ph);
    let pt = (o.0 + px, o.1 + py);
    // the wire leaves away from the drawing
    let (cx, cy) = (o.0 + pw / 2.0, o.1 + ph / 2.0);
    let dir = Dir::of_vec(pt.0 - cx, pt.1 - cy);
    Some((Kind::Symbol, pt, dir, None))
}

// a link end as a term
pub fn term(ctx: &Ctx, scope: usize, node: usize) -> Option<Term> {
    let dev = device_of(ctx, scope, node)?;
    if has(ctx, node, "pin") {
        // the stub's far end
        let stub = ctx.nodes[node].children.iter().cloned().find(|&c| has(ctx, c, "pin-stub"))?;
        let side = ctx.comp[stub].pin.clone().unwrap_or_default();
        let dir = Dir::of_side(side.split_whitespace().next().unwrap_or("left")).unwrap_or(Dir::L);
        let o = origin_in(ctx, stub, dev);
        let pts = match &ctx.nodes[stub].geo {
            Some(crate::scene::Geo::Points(p)) => p.clone(),
            _ => vec![(0.0, 0.0), (20.0, 0.0)],
        };
        let mut best = (o.0 + pts[0].0, o.1 + pts[0].1);
        let score = |p: (f64, f64)| -> f64 {
            let v = dir.vec();
            p.0 * v.0 + p.1 * v.1
        };
        for p in &pts {
            let q = (o.0 + p.0, o.1 + p.1);
            if score(q) > score(best) {
                best = q;
            }
        }
        return Some(Term { node, dev, kind: Kind::Pin, off: best, dir, through: None });
    }
    if node != dev && is_part(ctx, dev) && ctx.nodes[node].id.is_some() {
        let o = origin_in(ctx, node, dev);
        let dir = Dir::of_vec(o.0, o.1);
        return Some(Term { node, dev, kind: Kind::Station, off: o, dir, through: None });
    }
    if node == dev && is_label(ctx, node) {
        let (kind, off, dir, through) = label_term(ctx, node)?;
        return Some(Term { node, dev, kind, off, dir, through });
    }
    let _ = is_component;
    Some(Term { node, dev, kind: Kind::Other, off: (0.0, 0.0), dir: Dir::R, through: None })
}

// the wires of a scope, in statement order
pub fn wires(ctx: &Ctx, scope: usize) -> Vec<Wire> {
    let mut out = Vec::new();
    for (li, l) in ctx.links.iter().enumerate() {
        if l.container != scope {
            continue;
        }
        let (a, b) = match (term(ctx, scope, l.from), term(ctx, scope, l.to)) {
            (Some(a), Some(b)) => (a, b),
            _ => continue,
        };
        out.push(Wire { li, a, b, span: l.span });
    }
    out
}

// Satellites seated at the pins their wires touch. A chain leaves an anchor
// pin along the pin's facing: an element posed along that ray stands in the
// pin's row, clear of the anchor by a pin pitch; an element posed across it
// turns the chain into a lane — a lattice column off the pin, clear of the
// anchor by a pitch past the lattice cells the element covers (a part keeps
// half the scope's gap besides) — and stacks along it. Each next element
// clears the one before by a pitch. Every placed point sits on the lattice.

use super::net::{Dir, Kind, Term, Wire};
use super::place::{ceil_lattice, is_part, PITCH};
use crate::compile::Ctx;

// a satellite's placement, anchor-local
#[derive(Clone, Debug)]
pub struct Seat {
    pub node: usize,
    pub x: f64,
    pub y: f64,
    // the lattice cells it reserves (x0, y0, x1, y1), anchor-local
    pub res: [f64; 4],
}

pub struct Cluster {
    pub anchor: usize,
    pub seats: Vec<Seat>,
}

// the extent of a node's own box (stroke included) around its origin
pub fn body(ctx: &Ctx, i: usize) -> [f64; 4] {
    let n = &ctx.nodes[i];
    let (ow, oh) = crate::layout::outer(ctx, i);
    let (cx, cy) = (-n.geo_off.0, -n.geo_off.1);
    [cx - ow / 2.0, cy - oh / 2.0, cx + ow / 2.0, cy + oh / 2.0]
}

// lattice cells covering [lo, hi] around a lattice line `at`: the cell edges
// sit halfway between lattice lines
pub fn cells(at: f64, lo: f64, hi: f64) -> (f64, f64) {
    let near = at - lo;
    let far = hi - at;
    let k = |d: f64| -> f64 {
        if d <= PITCH / 2.0 + 1e-9 {
            PITCH / 2.0
        } else {
            PITCH / 2.0 + PITCH * ((d - PITCH / 2.0) / PITCH - 1e-9).ceil()
        }
    };
    (at - k(near), at + k(far))
}

fn along(d: Dir, p: (f64, f64)) -> f64 {
    match d {
        Dir::L => -p.0,
        Dir::R => p.0,
        Dir::U => -p.1,
        Dir::D => p.1,
    }
}

// the first lattice coordinate at or past `v` going `d` (signed axis)
fn snap_out(d: Dir, v: f64) -> f64 {
    match d {
        Dir::R | Dir::D => ceil_lattice(v),
        Dir::L | Dir::U => -ceil_lattice(-v),
    }
}

// the node's box extent along `d` past its origin (far) and behind it (near)
fn span_along(b: &[f64; 4], d: Dir) -> (f64, f64) {
    match d {
        Dir::R => (-b[0], b[2]),
        Dir::L => (b[2], -b[0]),
        Dir::D => (-b[1], b[3]),
        Dir::U => (b[3], -b[1]),
    }
}

// the travel through an element entered at `t`: where it leaves and which way
pub fn travel(wires: &[Wire], t: &Term) -> (Dir, Option<Term>) {
    match t.kind {
        Kind::Station => {
            // the part's other station, from any wire touching it
            for w in wires {
                for o in [&w.a, &w.b] {
                    if o.dev == t.dev && o.node != t.node && o.kind == Kind::Station {
                        let d = Dir::of_vec(o.off.0 - t.off.0, o.off.1 - t.off.1);
                        return (d, Some(o.clone()));
                    }
                }
            }
            (t.dir.opposite(), None)
        }
        _ => (t.dir.opposite(), None),
    }
}

// the other station of a part (from its geometry), entered at `t`
pub fn other_station(ctx: &Ctx, t: &Term) -> Option<(usize, (f64, f64))> {
    if t.kind != Kind::Station {
        return None;
    }
    for &c in &ctx.nodes[t.dev].children {
        if c != t.node && ctx.nodes[c].id.is_some() && ctx.comp[c].pin.as_deref() == Some("center") {
            let o = super::net::origin_in(ctx, c, t.dev);
            return Some((c, o));
        }
    }
    None
}

pub struct Seater<'a> {
    pub ctx: &'a Ctx,
    pub wires: &'a [Wire],
    pub gap: f64,
    pub placed: Vec<Option<(usize, f64, f64)>>, // per node: (cluster anchor, x, y)
    pub seats: Vec<Seat>,
    // lanes in use per (anchor pin node): (lane coordinate, cross direction)
    pub lanes: Vec<(usize, f64, Dir)>,
}

impl<'a> Seater<'a> {
    fn gap_margin(&self) -> f64 {
        PITCH / 2.0 + PITCH * (self.gap / (2.0 * PITCH)).floor()
    }

    // seat `t`'s device so that its point `t.off` lands on `p`, travelling `d`
    fn seat(&mut self, anchor: usize, t: &Term, x: f64, y: f64, res: [f64; 4]) {
        self.placed[t.dev] = Some((anchor, x, y));
        self.seats.push(Seat { node: t.dev, x, y, res });
    }

    pub fn reserve(&self, dev: usize, x: f64, y: f64, lane_axis: Option<(bool, f64)>) -> [f64; 4] {
        let b = body(self.ctx, dev);
        let (x0, x1) = cells(x, x + b[0], x + b[2]);
        let (y0, y1) = cells(y, y + b[1], y + b[3]);
        let mut r = [x0, y0, x1, y1];
        if let Some((horizontal_lane, at)) = lane_axis {
            if is_part(self.ctx, dev) {
                let m = self.gap_margin();
                if horizontal_lane {
                    r[1] = r[1].min(at - m);
                    r[3] = r[3].max(at + m);
                } else {
                    r[0] = r[0].min(at - m);
                    r[2] = r[2].max(at + m);
                }
            }
        }
        r
    }

    // a chain leaving an anchor pin `p` (anchor-local point, facing `f`, the
    // anchor's extent `ext` along `f`) into `q`
    pub fn chain(&mut self, anchor: usize, p: (f64, f64), f: Dir, ext: f64, q: &Term, wi: usize) {
        if self.placed[q.dev].is_some() {
            return;
        }
        let (d1, _) = travel(self.wires, q);
        let ctx = self.ctx;
        let b = body(ctx, q.dev);
        if d1 == f {
            // straight: the element stands in the pin's row
            let (near, _) = span_along(&b, f);
            // origin coordinate along f
            let a = snap_out(f, sgn(f) * (ext + PITCH) + sgn(f) * near);
            let (x, y) = if f.horizontal() { (a, p.1 - q.off.1) } else { (p.0 - q.off.0, a) };
            let res = self.reserve(q.dev, x, y, None);
            self.seat(anchor, q, x, y, res);
        } else if d1 != f.opposite() {
            // turned: a lane off the pin
            // the lattice line of the entry point across f
            let entry_rel = q.off;
            // the element's near extent toward the anchor, from the entry line
            let (bl, br) = if f.horizontal() { (b[0] - entry_rel.0, b[2] - entry_rel.0) } else { (b[1] - entry_rel.1, b[3] - entry_rel.1) };
            let near = match f {
                Dir::R | Dir::D => -bl,
                _ => br,
            };
            let far = match f {
                Dir::R | Dir::D => br,
                _ => -bl,
            };
            let _ = far;
            let mut r = cell_half(near);
            if is_part(ctx, q.dev) {
                r = r.max(self.gap_margin());
            }
            let mut lane = snap_out(f, sgn(f) * (ext + PITCH + r));
            // lanes already taken off this pin
            let taken: Vec<(f64, Dir)> = self.lanes.iter().filter(|l| l.0 == wi_pin(self.wires, wi)).map(|l| (l.1, l.2)).collect();
            if let Some(&(last, ld)) = taken.last() {
                if ld != d1 && taken.iter().filter(|t| t.0 == last).count() == 1 {
                    lane = last;
                } else {
                    let step = ceil_lattice(self.gap).max(PITCH);
                    let next = last + sgn(f) * step;
                    lane = if sgn(f) > 0.0 { lane.max(next) } else { lane.min(next) };
                }
            }
            self.lanes.push((wi_pin(self.wires, wi), lane, d1));
            // along the lane: clear of the pin's row by a pitch
            let row = if f.horizontal() { p.1 } else { p.0 };
            let (near_d, _) = span_along(&shift(&b, -q.off.0, -q.off.1), d1);
            let pos = snap_out(d1, row + sgn(d1) * (PITCH + near_d));
            // place the entry point at (lane, pos)
            let (ex, ey) = if f.horizontal() { (lane, pos) } else { (pos, lane) };
            let (x, y) = if matches!(q.kind, Kind::Station) {
                // a part's centre sits on the lattice: the entry offset along
                // the travel is its own
                let c = if f.horizontal() { (lane - q.off.0, snap_out(d1, row + sgn(d1) * (PITCH + span_along(&b, d1).0))) } else { (snap_out(d1, row + sgn(d1) * (PITCH + span_along(&b, d1).0)), lane - q.off.1) };
                c
            } else {
                (ex - q.off.0, ey - q.off.1)
            };
            let res = self.reserve(q.dev, x, y, Some((!f.horizontal(), lane)));
            self.seat(anchor, q, x, y, res);
        }
    }
}

fn wi_pin(wires: &[Wire], wi: usize) -> usize {
    wires[wi].a.node
}

fn sgn(d: Dir) -> f64 {
    match d {
        Dir::R | Dir::D => 1.0,
        _ => -1.0,
    }
}

fn shift(b: &[f64; 4], dx: f64, dy: f64) -> [f64; 4] {
    [b[0] + dx, b[1] + dy, b[2] + dx, b[3] + dy]
}

// the half-width of the lattice cells an extent `d` past a lattice line covers
pub fn cell_half(d: f64) -> f64 {
    if d <= PITCH / 2.0 + 1e-9 {
        PITCH / 2.0
    } else {
        PITCH / 2.0 + PITCH * ((d - PITCH / 2.0) / PITCH - 1e-9).ceil()
    }
}

// Satellites seated at the pins their wires touch. A chain leaves an anchor
// pin along the pin's facing: an element posed along that ray stands in the
// pin's row, clear of the anchor by a pin pitch; an element posed across it
// turns the chain into a lane — a lattice column off the pin, clear of the
// anchor by a pitch past the lattice cells the element covers (a part keeps
// half the scope's gap besides) — and stacks along it. Each next element
// clears the one before by a pitch. Every seated point sits on the lattice:
// a part's or a tag's centre, a symbol's connection point.

use super::net::{origin_in, Dir, Kind, Term, Wire};
use super::place::{ceil_lattice, is_part, PITCH};
use crate::compile::Ctx;

// a satellite's placement, anchor-local
#[derive(Clone, Debug)]
pub struct Seat {
    pub node: usize,
    pub x: f64,
    pub y: f64,
    // the lattice cells it reserves (x0, y0, x1, y1), anchor-local
    pub res: [f64; 4],
}

#[derive(Clone, Debug)]
pub struct Lane {
    pub pin: usize,
    pub at: f64,
    pub dir: Dir,
}

// the extent of a node's own box (stroke included) around its origin
pub fn body(ctx: &Ctx, i: usize) -> [f64; 4] {
    let n = &ctx.nodes[i];
    let (ow, oh) = crate::layout::outer(ctx, i);
    let (cx, cy) = (-n.geo_off.0, -n.geo_off.1);
    [cx - ow / 2.0, cy - oh / 2.0, cx + ow / 2.0, cy + oh / 2.0]
}

// the half-extent of the lattice cells covering a reach `d` past a lattice
// line (cell edges sit halfway between lattice lines)
pub fn cell_half(d: f64) -> f64 {
    if d <= PITCH / 2.0 + 1e-9 {
        PITCH / 2.0
    } else {
        PITCH / 2.0 + PITCH * ((d - PITCH / 2.0) / PITCH - 1e-9).ceil()
    }
}

pub fn sgn(d: Dir) -> f64 {
    match d {
        Dir::R | Dir::D => 1.0,
        _ => -1.0,
    }
}

// the coordinate of a point along d's axis
pub fn coord(d: Dir, p: (f64, f64)) -> f64 {
    if d.horizontal() {
        p.0
    } else {
        p.1
    }
}

// the first lattice coordinate at or past `v` going `d`
pub fn snap_out(d: Dir, v: f64) -> f64 {
    if sgn(d) > 0.0 {
        ceil_lattice(v)
    } else {
        -ceil_lattice(-v)
    }
}

// a box's reach behind and ahead of a point along `d`
fn reach(b: &[f64; 4], p: (f64, f64), d: Dir) -> (f64, f64) {
    match d {
        Dir::R => (p.0 - b[0], b[2] - p.0),
        Dir::L => (b[2] - p.0, p.0 - b[0]),
        Dir::D => (p.1 - b[1], b[3] - p.1),
        Dir::U => (b[3] - p.1, p.1 - b[1]),
    }
}

// the station a part leaves by, entered at `t`
pub fn exit_of(ctx: &Ctx, wires: &[Wire], t: &Term) -> Option<Term> {
    if t.kind != Kind::Station {
        return None;
    }
    // stations are the part's id'd centre-pinned children
    let mut found = None;
    for &c in &ctx.nodes[t.dev].children {
        if c != t.node && ctx.nodes[c].id.is_some() && ctx.comp[c].pin.as_deref() == Some("center") {
            let o = origin_in(ctx, c, t.dev);
            found = Some(Term { node: c, dev: t.dev, kind: Kind::Station, off: o, dir: Dir::of_vec(o.0, o.1), through: None });
            break;
        }
    }
    let _ = wires;
    found
}

// the way a wire travels on entering `t`'s element
pub fn travel(ctx: &Ctx, wires: &[Wire], t: &Term) -> Dir {
    match t.kind {
        Kind::Station => match exit_of(ctx, wires, t) {
            Some(o) => Dir::of_vec(o.off.0 - t.off.0, o.off.1 - t.off.1),
            None => t.dir.opposite(),
        },
        _ => t.dir.opposite(),
    }
}

// the point of an element that sits on the lattice: a part's or a tag's
// centre, a symbol's connection point
fn lattice_point(t: &Term) -> (f64, f64) {
    match t.kind {
        Kind::Symbol => t.off,
        _ => (0.0, 0.0),
    }
}

pub struct Seater<'a> {
    pub ctx: &'a Ctx,
    pub wires: &'a [Wire],
    pub gap: f64,
    // per device: its origin, anchor-local
    pub placed: std::collections::HashMap<usize, (f64, f64)>,
    pub seats: Vec<Seat>,
    pub lanes: Vec<Lane>,
}

impl<'a> Seater<'a> {
    pub fn new(ctx: &'a Ctx, wires: &'a [Wire], gap: f64) -> Self {
        Seater { ctx, wires, gap, placed: Default::default(), seats: vec![], lanes: vec![] }
    }

    pub fn gap_margin(&self) -> f64 {
        PITCH / 2.0 + PITCH * (self.gap / (2.0 * PITCH)).floor()
    }

    // the lattice cells an element at (x, y) reserves; a part in a lane keeps
    // the gap margin across the lane
    pub fn reserve(&self, dev: usize, x: f64, y: f64, lp: (f64, f64), lane: Option<Dir>) -> [f64; 4] {
        let b = body(self.ctx, dev);
        let (px, py) = (x + lp.0, y + lp.1);
        let (x0, x1) = (px - cell_half(px - (x + b[0])), px + cell_half(x + b[2] - px));
        let (y0, y1) = (py - cell_half(py - (y + b[1])), py + cell_half(y + b[3] - py));
        let mut r = [x0, y0, x1, y1];
        if let Some(f) = lane {
            if is_part(self.ctx, dev) {
                let m = self.gap_margin();
                if f.horizontal() {
                    r[0] = r[0].min(px - m);
                    r[2] = r[2].max(px + m);
                } else {
                    r[1] = r[1].min(py - m);
                    r[3] = r[3].max(py + m);
                }
            }
        }
        r
    }

    fn put(&mut self, dev: usize, x: f64, y: f64, res: [f64; 4]) {
        self.placed.insert(dev, (x, y));
        self.seats.push(Seat { node: dev, x, y, res });
    }

    // A chain leaves the anchor's pin `pin` (point `p`, facing `f`, the
    // anchor's extent `ext` along `f`) into the element entered at `q`.
    pub fn from_pin(&mut self, pin: usize, p: (f64, f64), f: Dir, ext: f64, q: &Term) {
        if self.placed.contains_key(&q.dev) {
            return;
        }
        let ctx = self.ctx;
        let d1 = travel(ctx, self.wires, q);
        let b = body(ctx, q.dev);
        let lp = lattice_point(q);
        if d1 == f {
            // straight: in the pin's row
            let (behind, _) = reach(&b, lp, f);
            let a = snap_out(f, sgn(f) * ext + sgn(f) * (PITCH + behind));
            let (x, y) = if f.horizontal() { (a - lp.0, p.1 - q.off.1) } else { (p.0 - q.off.0, a - lp.1) };
            let res = self.reserve(q.dev, x, y, lp, None);
            self.put(q.dev, x, y, res);
            self.onward(q, d1);
            return;
        }
        if d1 == f.opposite() {
            return;
        }
        // turned: a lane off the pin, the entry point on it
        let (near, _) = reach(&b, q.off, f);
        let mut r = cell_half(near);
        if is_part(ctx, q.dev) {
            r = r.max(self.gap_margin());
        }
        let mut lane = snap_out(f, sgn(f) * (ext + PITCH + r));
        let mine: Vec<Lane> = self.lanes.iter().filter(|l| l.pin == pin).cloned().collect();
        if let Some(last) = mine.last() {
            let shared = mine.iter().filter(|l| l.at == last.at).count();
            if last.dir == d1.opposite() && shared == 1 {
                lane = last.at;
            } else {
                let next = last.at + sgn(f) * ceil_lattice(self.gap).max(PITCH);
                lane = if sgn(f) > 0.0 { lane.max(next) } else { lane.min(next) };
            }
        }
        self.lanes.push(Lane { pin, at: lane, dir: d1 });
        // along the lane, clear of the pin's row by a pitch
        let row = coord(d1, p);
        let (behind, _) = reach(&b, lp, d1);
        let a = snap_out(d1, row + sgn(d1) * (PITCH + behind));
        let (x, y) = if f.horizontal() { (lane - q.off.0, a - lp.1) } else { (a - lp.0, lane - q.off.1) };
        let res = self.reserve(q.dev, x, y, lp, Some(f));
        self.put(q.dev, x, y, res);
        self.onward(q, d1);
    }

    // the chain goes on past the element entered at `q`, travelling `d`
    fn onward(&mut self, q: &Term, d: Dir) {
        let ctx = self.ctx;
        let exit = match q.kind {
            Kind::Station => match exit_of(ctx, self.wires, q) {
                Some(e) => e,
                None => return,
            },
            _ => q.clone(),
        };
        let (sx, sy) = self.placed[&q.dev];
        let sb = body(ctx, q.dev);
        let sbox = [sx + sb[0], sy + sb[1], sx + sb[2], sy + sb[3]];
        let ep = (sx + exit.off.0, sy + exit.off.1);
        // the wires at the exit, in order
        let nexts: Vec<Term> = self
            .wires
            .iter()
            .filter_map(|w| {
                if w.a.node == exit.node && w.b.dev != q.dev {
                    Some(w.b.clone())
                } else if w.b.node == exit.node && w.a.dev != q.dev {
                    Some(w.a.clone())
                } else {
                    None
                }
            })
            .collect();
        for t in nexts {
            if self.placed.contains_key(&t.dev) || !is_satellite(ctx, t.dev) {
                continue;
            }
            let d2 = travel(ctx, self.wires, &t);
            let b = body(ctx, t.dev);
            let lp = lattice_point(&t);
            let far = match d {
                Dir::R => sbox[2],
                Dir::L => -sbox[0],
                Dir::D => sbox[3],
                Dir::U => -sbox[1],
            };
            if d2 == d {
                let (behind, _) = reach(&b, lp, d);
                let a = snap_out(d, sgn(d) * (far + PITCH + behind));
                let (x, y) = if d.horizontal() { (a - lp.0, ep.1 - t.off.1) } else { (ep.0 - t.off.0, a - lp.1) };
                let res = self.reserve(t.dev, x, y, lp, Some(d.opposite()).filter(|_| false));
                self.put(t.dev, x, y, res);
                self.onward(&t, d2);
            }
        }
    }
}

pub fn is_satellite(ctx: &Ctx, i: usize) -> bool {
    super::place::role(ctx, i) == super::place::Role::Satellite
}

