// The wires of every schematic scope, routed after layout between fixed
// ports: a pin's stub tip (left along the pin's facing), a part's station, a
// label's connection point (a run's far end: the wire travels its length).
// Routes run on the scope's lattice lines clear of every body's lattice
// cells; a wire of a net already drawn joins it where it can, and the points
// where three ways of one net meet get a junction dot.

use super::net::{origin_in, Dir, Kind, Term};
use crate::compile::Ctx;
use std::cell::RefCell;

#[derive(Clone, Debug)]
pub struct Routed {
    pub li: usize,
    pub pts: Vec<(f64, f64)>,
    // the net name along the trace: (text, x, y, rotation)
    pub label: Option<(String, f64, f64, f64)>,
    pub scope: usize,
}

#[derive(Default)]
pub struct Wiring {
    pub wires: Vec<Routed>,
    pub junctions: Vec<(f64, f64)>,
    // a scope a wire is drawn in is not the root: wires wear the class
    pub nested: bool,
}

thread_local! {
    pub static WIRING: RefCell<Wiring> = RefCell::new(Wiring::default());
}

pub fn reset() {
    WIRING.with(|w| *w.borrow_mut() = Wiring::default());
}

pub const CLEAR: f64 = 10.0;

fn abs_point(ctx: &Ctx, t: &Term) -> (f64, f64) {
    let o = origin_in(ctx, t.dev, 0);
    (o.0 + t.off.0, o.1 + t.off.1)
}

fn same(a: f64, b: f64) -> bool {
    (a - b).abs() < 1e-9
}

// a direct route: straight, or one corner
fn direct(a: (f64, f64), da: Dir, b: (f64, f64), db: Dir) -> Option<Vec<(f64, f64)>> {
    let ahead = |p: (f64, f64), d: Dir, q: (f64, f64)| -> bool {
        match d {
            Dir::R => q.0 > p.0 - 1e-9,
            Dir::L => q.0 < p.0 + 1e-9,
            Dir::D => q.1 > p.1 - 1e-9,
            Dir::U => q.1 < p.1 + 1e-9,
        }
    };
    if da == db.opposite() {
        let aligned = if da.horizontal() { same(a.1, b.1) } else { same(a.0, b.0) };
        if aligned && ahead(a, da, b) {
            return Some(vec![a, b]);
        }
        if ahead(a, da, b) {
            // a staircase: the jog halfway
            if da.horizontal() {
                let m = (a.0 + b.0) / 2.0;
                return Some(vec![a, (m, a.1), (m, b.1), b]);
            } else {
                let m = (a.1 + b.1) / 2.0;
                return Some(vec![a, (a.0, m), (b.0, m), b]);
            }
        }
        return None;
    }
    if da.horizontal() != db.horizontal() {
        let c = if da.horizontal() { (b.0, a.1) } else { (a.0, b.1) };
        if ahead(a, da, c) && ahead(b, db, c) {
            return Some(vec![a, c, b]);
        }
    }
    None
}

pub fn route(ctx: &mut Ctx) {
    reset();
    if !super::active() {
        return;
    }
    let mut all = Wiring::default();
    let root_sch = ctx.comp[0].layout == "schematic";
    for s in 0..ctx.nodes.len() {
        if ctx.comp[s].layout != "schematic" {
            continue;
        }
        if s != 0 || !root_sch {
            // nested scopes draw wires with the schematic class
        }
        let wires = super::net::wires(ctx, s);
        if !wires.is_empty() && s != 0 {
            all.nested = true;
        }
        for w in &wires {
            let mut a = abs_point(ctx, &w.a);
            let mut b = abs_point(ctx, &w.b);
            let (mut da, mut db) = (w.a.dir, w.b.dir);
            // a run is travelled to its far end
            if w.a.kind == Kind::Run {
                da = w.a.dir;
            }
            if w.b.kind == Kind::Run {
                db = w.b.dir;
            }
            let pts = match direct(a, da, b, db) {
                Some(p) => p,
                None => {
                    std::mem::swap(&mut a, &mut b);
                    std::mem::swap(&mut da, &mut db);
                    match direct(a, da, b, db) {
                        Some(mut p) => {
                            p.reverse();
                            p
                        }
                        None => vec![b, a],
                    }
                }
            };
            all.wires.push(Routed { li: w.li, pts, label: None, scope: s });
        }
    }
    // net names along the trace
    for r in all.wires.iter_mut() {
        let l = &ctx.links[r.li];
        if let Some(t) = link_text(ctx, r.li) {
            let along = ctx.links[r.li]
                .style
                .iter()
                .rev()
                .find(|d| d.name == "along")
                .and_then(|d| crate::style::value_num(&ctx.sheet.env, &d.value))
                .unwrap_or(0.5);
            r.label = Some(place_label(&r.pts, along, t));
        }
        let _ = l;
    }
    all.junctions = junctions(ctx, &all.wires);
    WIRING.with(|w| *w.borrow_mut() = all);
}

fn link_text(ctx: &Ctx, li: usize) -> Option<String> {
    let l = &ctx.links[li];
    if let Some(t) = &l.label {
        return Some(t.clone());
    }
    for s in &l.labels {
        if let crate::ast::Stmt::Text(t) = s {
            return Some(t.text.clone());
        }
    }
    None
}

// a net name rides beside the trace at `along` of its length: above a level
// run, to the left of an upright one (turned to read up it)
fn place_label(pts: &[(f64, f64)], along: f64, text: String) -> (String, f64, f64, f64) {
    let mut total = 0.0;
    for k in 1..pts.len() {
        total += (pts[k].0 - pts[k - 1].0).abs() + (pts[k].1 - pts[k - 1].1).abs();
    }
    let mut s = total * along;
    for k in 1..pts.len() {
        let (p, q) = (pts[k - 1], pts[k]);
        let len = (q.0 - p.0).abs() + (q.1 - p.1).abs();
        if s <= len + 1e-9 || k == pts.len() - 1 {
            let f = if len > 0.0 { s / len } else { 0.0 };
            let x = p.0 + (q.0 - p.0) * f;
            let y = p.1 + (q.1 - p.1) * f;
            if same(p.1, q.1) {
                return (text, x, y - 9.5, 0.0);
            }
            return (text, x - 9.5, y, 270.0);
        }
        s -= len;
    }
    (text, pts[0].0, pts[0].1 - 9.5, 0.0)
}

// points where three ways of one net meet
fn junctions(ctx: &Ctx, wires: &[Routed]) -> Vec<(f64, f64)> {
    // nets: wires sharing a terminal node (pins, labels) join
    let n = wires.len();
    let mut parent: Vec<usize> = (0..n).collect();
    fn find(p: &mut Vec<usize>, i: usize) -> usize {
        let mut i = i;
        while p[i] != i {
            p[i] = p[p[i]];
            i = p[i];
        }
        i
    }
    let ends: Vec<(usize, usize)> = wires.iter().map(|r| (ctx.links[r.li].from, ctx.links[r.li].to)).collect();
    for i in 0..n {
        for j in 0..i {
            let (a, b) = ends[i];
            let (c, d) = ends[j];
            if a == c || a == d || b == c || b == d {
                let (x, y) = (find(&mut parent, i), find(&mut parent, j));
                parent[x] = y;
            }
        }
    }
    let mut out: Vec<(f64, f64)> = Vec::new();
    for i in 0..n {
        let root = find(&mut parent, i);
        // candidate points: this wire's vertices
        for &p in &wires[i].pts {
            if out.iter().any(|q| same(q.0, p.0) && same(q.1, p.1)) {
                continue;
            }
            let mut dirs: Vec<Dir> = Vec::new();
            for j in 0..n {
                if find(&mut parent, j) != root {
                    continue;
                }
                let pts = &wires[j].pts;
                for k in 1..pts.len() {
                    let (s, e) = (pts[k - 1], pts[k]);
                    for (from, to) in [(s, e), (e, s)] {
                        // a segment leaving p
                        if on_seg(p, from, to) && !(same(p.0, to.0) && same(p.1, to.1)) {
                            let d = Dir::of_vec(to.0 - p.0, to.1 - p.1);
                            if !dirs.contains(&d) {
                                dirs.push(d);
                            }
                        }
                    }
                }
            }
            if dirs.len() >= 3 {
                out.push(p);
            }
        }
    }
    out
}

// p on the segment [a, b] (a included, b excluded unless a == b)
fn on_seg(p: (f64, f64), a: (f64, f64), b: (f64, f64)) -> bool {
    if same(a.1, b.1) && same(p.1, a.1) {
        let (lo, hi) = (a.0.min(b.0), a.0.max(b.0));
        return p.0 > lo - 1e-9 && p.0 < hi + 1e-9;
    }
    if same(a.0, b.0) && same(p.0, a.0) {
        let (lo, hi) = (a.1.min(b.1), a.1.max(b.1));
        return p.1 > lo - 1e-9 && p.1 < hi + 1e-9;
    }
    false
}

// The wires' SVG: each wire a `lini-link` group with its path and net name,
// the junction dots after them; and their stylesheet rules. A root
// schematic restyles the links themselves; a schematic nested in another
// layout marks its wires `lini-schematic-wire`.

use super::wire::WIRING;
use crate::compile::Ctx;
use crate::render::Out;
use crate::style::use_var;
use crate::util::{f4, xml_escape};

pub fn reset() {
    super::wire::reset();
}

fn label_width(ctx: &Ctx, text: &str) -> f64 {
    let fam = crate::font::Family::Sans;
    let w = if ctx.comp[0].layout == "schematic" { ctx.comp[0].font_weight } else { 400 };
    crate::font::text_width(fam, w, 11.0, text)
}

pub fn extend_bbox(ctx: &Ctx, b: &mut [f64; 4]) {
    WIRING.with(|w| {
        let w = w.borrow();
        for r in &w.wires {
            for &(x, y) in &r.pts {
                b[0] = b[0].min(x);
                b[1] = b[1].min(y);
                b[2] = b[2].max(x);
                b[3] = b[3].max(y);
            }
            if let Some((t, x, y, rot)) = &r.label {
                let tw = label_width(ctx, t);
                let (hw, hh) = if *rot != 0.0 { (5.5, tw / 2.0) } else { (tw / 2.0, 5.5) };
                b[0] = b[0].min(x - hw);
                b[1] = b[1].min(y - hh);
                b[2] = b[2].max(x + hw);
                b[3] = b[3].max(y + hh);
            }
        }
    });
}

// the schematic wires and junctions inside the links layer ("" when none)
pub fn render_links(ctx: &Ctx, out: &mut Out) -> Result<String, crate::diag::Diag> {
    super::sheet_vars(&mut out.vars);
    let mut s = String::new();
    WIRING.with(|w| {
        let w = w.borrow();
        if w.wires.is_empty() {
            return;
        }
        let root = ctx.comp[0].layout == "schematic";
        let mut any_label = false;
        for r in &w.wires {
            let l = &ctx.links[r.li];
            let cls = if root { "lini-link".to_string() } else { "lini-link lini-schematic-wire".to_string() };
            s.push_str(&format!(
                "    <g class=\"{}\" data-from=\"{}\" data-to=\"{}\">\n",
                cls,
                xml_escape(&crate::links::path_of(ctx, l.from)),
                xml_escape(&crate::links::path_of(ctx, l.to))
            ));
            let mut d = String::new();
            for (k, &(x, y)) in r.pts.iter().enumerate() {
                if k > 0 {
                    d.push(' ');
                }
                d.push_str(&format!("{} {} {}", if k == 0 { "M" } else { "L" }, f4(x), f4(y)));
            }
            s.push_str(&format!("      <path d=\"{}\"/>\n", d));
            if let Some((t, x, y, rot)) = &r.label {
                any_label = true;
                let style = if root { String::new() } else { " style=\"fill: var(--lini-label-ink); font-weight: var(--lini-font-weight)\"".to_string() };
                let turn = if *rot != 0.0 { format!(" transform=\"rotate({} {} {})\"", f4(*rot), f4(*x), f4(*y)) } else { String::new() };
                s.push_str(&format!(
                    "      <text class=\"lini-link-label\" x=\"{}\" y=\"{}\" dy=\"0.358em\"{}{}>{}</text>\n",
                    f4(*x),
                    f4(*y),
                    style,
                    turn,
                    xml_escape(t)
                ));
            }
            s.push_str("    </g>\n");
        }
        for &(x, y) in &w.junctions {
            s.push_str(&format!("    <g class=\"lini-node lini-junction lini-oval\" transform=\"translate({},{})\">\n", f4(x), f4(y)));
            s.push_str("      <ellipse cx=\"0\" cy=\"0\" rx=\"4\" ry=\"4\"/>\n");
            s.push_str("    </g>\n");
        }
        // the stylesheet
        if root {
            out.extra_rules.push(("link".into(), ".lini-link { fill: none; stroke: var(--lini-wire); stroke-width: 1.5; stroke-dasharray: none; }".to_string()));
            use_var(&mut out.vars, "wire");
            if any_label {
                out.extra_rules.push((
                    "link-label".into(),
                    ".lini-link-label { fill: var(--lini-label-ink); stroke: none; text-anchor: middle; font-size: 11px; font-weight: var(--lini-font-weight); }".to_string(),
                ));
                use_var(&mut out.vars, "label-ink");
            }
        } else {
            out.extra_rules.push(("link".into(), ".lini-link { fill: none; stroke: var(--lini-stroke); stroke-width: 2; stroke-dasharray: none; }".to_string()));
            use_var(&mut out.vars, "stroke");
            if any_label {
                out.extra_rules.push((
                    "link-label".into(),
                    ".lini-link-label { fill: currentColor; stroke: none; text-anchor: middle; font-size: 11px; font-weight: var(--lini-link-font-weight); }".to_string(),
                ));
                use_var(&mut out.vars, "link-font-weight");
                use_var(&mut out.vars, "label-ink");
            }
            out.extra_rules.push(("schematic-wire".into(), ".lini-links .lini-schematic-wire { stroke: var(--lini-wire); stroke-width: 1.5; }".to_string()));
            use_var(&mut out.vars, "wire");
        }
        if !w.junctions.is_empty() {
            out.extra_rules.push(("oval".into(), ".lini-oval { stroke-dasharray: none; }".to_string()));
            out.extra_rules.push(("junction".into(), ".lini-junction { fill: var(--lini-wire); stroke: none; }".to_string()));
            use_var(&mut out.vars, "wire");
        }
    });
    Ok(s)
}

