// An orthogonal search between two fixed ports. Every body is an obstacle:
// its lattice cells grown by the clearance. A wire leaves its port straight
// along the port's facing until it is out of its own body's cells (the
// landing), then searches a sparse grid of the obstacles' edges for the
// cheapest route — length plus two clearances per bend. Staircase steps then
// centre in their channel; detours keep hugging what they go around.

use super::net::Dir;
use std::collections::BinaryHeap;

const EPS: f64 = 1e-6;

#[derive(Clone, Copy, Debug)]
pub struct Rect {
    pub x0: f64,
    pub y0: f64,
    pub x1: f64,
    pub y1: f64,
}

impl Rect {
    pub fn new(x0: f64, y0: f64, x1: f64, y1: f64) -> Rect {
        Rect { x0, y0, x1, y1 }
    }
    pub fn grow(&self, k: f64) -> Rect {
        Rect::new(self.x0 - k, self.y0 - k, self.x1 + k, self.y1 + k)
    }
    fn contains_open(&self, p: (f64, f64)) -> bool {
        p.0 > self.x0 + EPS && p.0 < self.x1 - EPS && p.1 > self.y0 + EPS && p.1 < self.y1 - EPS
    }
}

#[derive(Clone, Copy, Debug)]
pub struct Port {
    pub p: (f64, f64),
    // the way the wire leaves the port
    pub d: Dir,
    // the port's own obstacle (left straight from the port)
    pub own: Option<usize>,
    // the wire may leave the landing any way but back
    pub free: bool,
}

fn idx(d: Dir) -> usize {
    match d {
        Dir::R => 0,
        Dir::D => 1,
        Dir::L => 2,
        Dir::U => 3,
    }
}

const DIRS: [Dir; 4] = [Dir::R, Dir::D, Dir::L, Dir::U];

// is the segment p-q clear of every obstacle's open interior?
pub fn seg_clear(obs: &[Rect], skip: &[usize], p: (f64, f64), q: (f64, f64)) -> bool {
    let (x0, x1) = (p.0.min(q.0), p.0.max(q.0));
    let (y0, y1) = (p.1.min(q.1), p.1.max(q.1));
    for (k, r) in obs.iter().enumerate() {
        if skip.contains(&k) {
            continue;
        }
        if (y1 - y0).abs() < EPS {
            if y0 > r.y0 + EPS && y0 < r.y1 - EPS && x0 < r.x1 - EPS && x1 > r.x0 + EPS {
                return false;
            }
        } else if x0 > r.x0 + EPS && x0 < r.x1 - EPS && y0 < r.y1 - EPS && y1 > r.y0 + EPS {
            return false;
        }
    }
    true
}

// out of a port along its facing, to its own obstacle's edge
pub fn landing(obs: &[Rect], port: &Port) -> (f64, f64) {
    let p = port.p;
    match port.own {
        Some(k) => {
            let r = obs[k];
            match port.d {
                Dir::R => (r.x1.max(p.0), p.1),
                Dir::L => (r.x0.min(p.0), p.1),
                Dir::D => (p.0, r.y1.max(p.1)),
                Dir::U => (p.0, r.y0.min(p.1)),
            }
        }
        None => p,
    }
}

fn uniq(mut v: Vec<f64>) -> Vec<f64> {
    v.sort_by(|a, b| a.partial_cmp(b).unwrap());
    let mut o: Vec<f64> = Vec::new();
    for x in v {
        if o.last().map_or(true, |l: &f64| (x - *l).abs() > 1e-7) {
            o.push(x);
        }
    }
    o
}

#[derive(PartialEq)]
struct Item {
    cost: f64,
    seq: u64,
    state: usize,
}
impl Eq for Item {}
impl PartialOrd for Item {
    fn partial_cmp(&self, o: &Self) -> Option<std::cmp::Ordering> {
        Some(self.cmp(o))
    }
}
impl Ord for Item {
    fn cmp(&self, o: &Self) -> std::cmp::Ordering {
        o.cost.partial_cmp(&self.cost).unwrap_or(std::cmp::Ordering::Equal).then(o.seq.cmp(&self.seq))
    }
}

pub fn simplify(pts: &[(f64, f64)]) -> Vec<(f64, f64)> {
    let mut o: Vec<(f64, f64)> = Vec::new();
    for &p in pts {
        if let Some(l) = o.last() {
            if (l.0 - p.0).abs() < EPS && (l.1 - p.1).abs() < EPS {
                continue;
            }
        }
        o.push(p);
    }
    let mut k = 1;
    while k + 1 < o.len() {
        let (a, b, c) = (o[k - 1], o[k], o[k + 1]);
        let col = ((a.0 - b.0).abs() < EPS && (b.0 - c.0).abs() < EPS) || ((a.1 - b.1).abs() < EPS && (b.1 - c.1).abs() < EPS);
        if col {
            o.remove(k);
        } else {
            k += 1;
        }
    }
    o
}

// the cheapest route between two ports: length plus `bend` per bend
pub fn search(obs: &[Rect], a: &Port, b: &Port, bend: f64) -> Option<Vec<(f64, f64)>> {
    let la = landing(obs, a);
    let lb = landing(obs, b);
    let skip_a: Vec<usize> = a.own.into_iter().collect();
    let skip_b: Vec<usize> = b.own.into_iter().collect();
    // the stubs themselves must be clear of everything else
    let mut xs = vec![la.0, lb.0];
    let mut ys = vec![la.1, lb.1];
    for r in obs {
        xs.push(r.x0);
        xs.push(r.x1);
        ys.push(r.y0);
        ys.push(r.y1);
    }
    let xs = uniq(xs);
    let ys = uniq(ys);
    let nx = xs.len();
    let ny = ys.len();
    let find = |v: &[f64], x: f64| v.iter().position(|t| (t - x).abs() < 1e-7);
    let (sx, sy) = (find(&xs, la.0)?, find(&ys, la.1)?);
    let (gx, gy) = (find(&xs, lb.0)?, find(&ys, lb.1)?);
    let state = |ix: usize, iy: usize, d: usize| (iy * nx + ix) * 4 + d;
    let n = nx * ny * 4;
    let mut dist = vec![f64::INFINITY; n];
    let mut prev = vec![usize::MAX; n];
    let mut heap = BinaryHeap::new();
    let mut seq = 0u64;
    let start = state(sx, sy, idx(a.d));
    dist[start] = 0.0;
    heap.push(Item { cost: 0.0, seq, state: start });
    let want = idx(b.d.opposite());
    let mut best: Option<(f64, usize)> = None;
    while let Some(Item { cost, state: st, .. }) = heap.pop() {
        if cost > dist[st] + EPS {
            continue;
        }
        if let Some((bc, _)) = best {
            if cost > bc + EPS {
                break;
            }
        }
        let d = st % 4;
        let cell = st / 4;
        let (ix, iy) = (cell % nx, cell / nx);
        if ix == gx && iy == gy {
            // into the far stub
            let extra = if d == want { 0.0 } else if (d + 2) % 4 == want { f64::INFINITY } else { bend };
            if b.free && d != (want + 2) % 4 {
                let c = cost;
                if best.map_or(true, |(bc, _)| c < bc - EPS) {
                    best = Some((c, st));
                }
            } else if extra.is_finite() {
                let c = cost + extra;
                if best.map_or(true, |(bc, _)| c < bc - EPS) {
                    best = Some((c, st));
                }
            }
        }
        for (k, nd) in DIRS.iter().enumerate() {
            if k == (d + 2) % 4 {
                continue;
            }
            // a free start may leave any way; a fixed one only straight on first
            if st == start && !a.free && k != d {
                // turning at the landing is a bend like any other
            }
            let (jx, jy) = match nd {
                Dir::R if ix + 1 < nx => (ix + 1, iy),
                Dir::L if ix > 0 => (ix - 1, iy),
                Dir::D if iy + 1 < ny => (ix, iy + 1),
                Dir::U if iy > 0 => (ix, iy - 1),
                _ => continue,
            };
            let p = (xs[ix], ys[iy]);
            let q = (xs[jx], ys[jy]);
            if !seg_clear(obs, &[], p, q) {
                // a stub's own body is only crossed straight out of the port
                let mut ok = false;
                if seg_clear(obs, &skip_a, p, q) && on_stub(a, la, p, q) {
                    ok = true;
                }
                if seg_clear(obs, &skip_b, p, q) && on_stub(b, lb, p, q) {
                    ok = true;
                }
                if !ok {
                    continue;
                }
            }
            let len = (q.0 - p.0).abs() + (q.1 - p.1).abs();
            let turn = if k == d { 0.0 } else if st == start && a.free { 0.0 } else { bend };
            let nc = cost + len + turn;
            let ns = state(jx, jy, k);
            if nc < dist[ns] - EPS {
                dist[ns] = nc;
                prev[ns] = st;
                seq += 1;
                heap.push(Item { cost: nc, seq, state: ns });
            }
        }
    }
    let (_, mut st) = best?;
    let mut cells: Vec<(f64, f64)> = Vec::new();
    loop {
        let cell = st / 4;
        cells.push((xs[cell % nx], ys[cell / nx]));
        if prev[st] == usize::MAX {
            break;
        }
        st = prev[st];
    }
    cells.reverse();
    let mut pts = vec![a.p];
    pts.extend(cells);
    pts.push(b.p);
    Some(simplify(&pts))
}

fn on_stub(port: &Port, land: (f64, f64), p: (f64, f64), q: (f64, f64)) -> bool {
    let within = |t: (f64, f64)| {
        let (x0, x1) = (port.p.0.min(land.0), port.p.0.max(land.0));
        let (y0, y1) = (port.p.1.min(land.1), port.p.1.max(land.1));
        t.0 >= x0 - EPS && t.0 <= x1 + EPS && t.1 >= y0 - EPS && t.1 <= y1 + EPS
    };
    within(p) && within(q)
}

// Staircase steps — a segment turning opposite ways at its two ends — move
// to the middle of the channel their neighbours and the obstacles leave.
pub fn centre(obs: &[Rect], pts: &mut Vec<(f64, f64)>, fixed_ends: (usize, usize)) {
    let n = pts.len();
    if n < 4 {
        return;
    }
    for k in 1..n - 2 {
        // segment k..k+1 between segments k-1..k and k+1..k+2
        if k < fixed_ends.0 || k + 1 > n - 1 - fixed_ends.1 {
            continue;
        }
        let (a, b, c, d) = (pts[k - 1], pts[k], pts[k + 1], pts[k + 2]);
        let vert = (b.0 - c.0).abs() < EPS;
        let (before, after) = if vert { (b.0 - a.0, d.0 - c.0) } else { (b.1 - a.1, d.1 - c.1) };
        if before * after <= 0.0 {
            continue; // a U, not a step
        }
        // the slide range: within both neighbours' spans
        let (lo, hi) = if vert { (a.0.min(d.0), a.0.max(d.0)) } else { (a.1.min(d.1), a.1.max(d.1)) };
        let (s0, s1) = if vert { (b.1.min(c.1), b.1.max(c.1)) } else { (b.0.min(c.0), b.0.max(c.0)) };
        let pos = if vert { b.0 } else { b.1 };
        let mut clo = lo;
        let mut chi = hi;
        for r in obs {
            let (a0, a1, b0, b1) = if vert { (r.y0, r.y1, r.x0, r.x1) } else { (r.x0, r.x1, r.y0, r.y1) };
            if a0 < s1 - EPS && a1 > s0 + EPS {
                if b1 <= pos + EPS && b1 > clo {
                    clo = b1;
                }
                if b0 >= pos - EPS && b0 < chi {
                    chi = b0;
                }
            }
        }
        let m = (clo + chi) / 2.0;
        if vert {
            pts[k].0 = m;
            pts[k + 1].0 = m;
        } else {
            pts[k].1 = m;
            pts[k + 1].1 = m;
        }
    }
}

