new='''// one wire: from port to port, a run travelled to its far end
fn route_one(ctx: &Ctx, obs: &[super::router::Rect], owner: &[usize], w: &super::net::Wire) -> Vec<(f64, f64)> {
    use super::router::{centre, search, Port};
    let port = |t: &Term| -> (Port, Option<(f64, f64)>) {
        let own = owner.iter().position(|&d| d == t.dev);
        if t.kind == Kind::Run {
            let o = origin_in(ctx, t.dev, 0);
            let far = (o.0 + t.off.0, o.1 + t.off.1);
            let near = t.through.map(|n| (o.0 + n.0, o.1 + n.1)).unwrap_or(far);
            return (Port { p: near, d: t.dir, own, free: true }, Some(far));
        }
        (Port { p: abs_point(ctx, t), d: t.dir, own, free: false }, None)
    };
    let (mut pa, fa) = port(&w.a);
    let (mut pb, fb) = port(&w.b);
    // a free port's own body never blocks it
    let mut obs2: Vec<super::router::Rect> = obs.to_vec();
    for p in [&mut pa, &mut pb] {
        if p.free {
            if let Some(k) = p.own {
                obs2[k] = super::router::Rect::new(f64::NAN, f64::NAN, f64::NAN, f64::NAN);
            }
            p.own = None;
        }
    }
    let mut pts = match search(&obs2, &pa, &pb, 2.0 * CLEAR) {
        Some(p) => p,
        None => direct(pa.p, pa.d, pb.p, pb.d).unwrap_or_else(|| vec![pa.p, pb.p]),
    };
    let fixed = (if pa.own.is_some() { 2 } else { 1 }, if pb.own.is_some() { 2 } else { 1 });
    centre(&obs2, &mut pts, fixed);
    if let Some(f) = fa {
        pts.insert(0, f);
    }
    if let Some(f) = fb {
        pts.push(f);
    }
    super::router::simplify(&pts)
}

