// to the middle of the channel their neighbours and the obstacles leave; a
// first or last wire keeps its straight run out of its port (to the
// landings `la`, `lb`).
pub fn centre(obs: &[Rect], pts: &mut Vec<(f64, f64)>, la: (f64, f64), lb: (f64, f64)) {
    let n = pts.len();
    if n < 4 {
        return;
    }
    for k in 1..n - 2 {
        // segment k..k+1 between segments k-1..k and k+1..k+2
        let (a, b, c, d) = (pts[k - 1], pts[k], pts[k + 1], pts[k + 2]);
        let vert = (b.0 - c.0).abs() < EPS;
        let (before, after) = if vert { (b.0 - a.0, d.0 - c.0) } else { (b.1 - a.1, d.1 - c.1) };
        if before * after <= 0.0 {
            continue; // a U, not a step
        }
        // the slide range: within both neighbours' spans
        let (mut lo, mut hi) = if vert { (a.0.min(d.0), a.0.max(d.0)) } else { (a.1.min(d.1), a.1.max(d.1)) };
        // the port runs keep their landings
        if k == 1 {
            let l = if vert { la.0 } else { la.1 };
            if before > 0.0 {
                lo = lo.max(l);
            } else {
                hi = hi.min(l);
            }
        }
        if k + 2 == n - 1 {
            let l = if vert { lb.0 } else { lb.1 };
            if after > 0.0 {
                hi = hi.min(l);
            } else {
                lo = lo.max(l);
            }
        }
        let (s0, s1) = if vert { (b.1.min(c.1), b.1.max(c.1)) } else { (b.0.min(c.0), b.0.max(c.0)) };
        let pos = if vert { b.0 } else { b.1 };
        let mut clo = lo;
        let mut chi = hi;
        for r in obs {
            let (a0, a1, b0, b1) = if vert { (r.y0, r.y1, r.x0, r.x1) } else { (r.x0, r.x1, r.y0, r.y1) };
            if a0 < s1 - EPS && a1 > s0 + EPS {
                if b1 <= pos + EPS && b1 > clo {
                    clo = b1;
                }
                if b0 >= pos - EPS && b0 < chi {
                    chi = b0;
                }
            }
        }
        let m = (clo + chi) / 2.0;
        if vert {
            pts[k].0 = m;
            pts[k + 1].0 = m;
        } else {
            pts[k].1 = m;
            pts[k + 1].1 = m;
        }
    }
}
