#!/usr/bin/env python3
# label placement of a straight satellite off different pins of a configurable component
import sys, re, os
sys.path.insert(0, '/tmp/sch/scripts')
from summ import run

comp = sys.argv[1]   # e.g. "L,L,L,R"
target = sys.argv[2]  # pin index
extra_wires = sys.argv[3] if len(sys.argv) > 3 else ''
pins = []
for k, s in enumerate(comp.split(',')):
    side = {'L': 'left', 'R': 'right', 'T': 'top', 'B': 'bottom', 'S': None}[s]
    if side is None:
        pins.append('|space|')
    else:
        pins.append('|pin#p%d| { side: %s; }' % (k, side))
src = '{ layout: schematic }\n|component#u1| "U" [ %s ]\n|R#r1| "1k"\nu1.p%s - r1\n%s\n' % ('; '.join(pins), target, extra_wires.replace('\\n', '\n'))
for exe in ['/workspace/executable', '/tmp/bin-sch/executable'] if os.environ.get('BOTH') else ['/workspace/executable']:
    o, e, c = run(src, exe=exe)
    if e: print(e.strip()[:200])
    cur = None
    for l in o.split('\n'):
        m = re.search(r'class="lini-node ([^"]*)"(?: data-id="([^"]+)")? transform="translate\(([-\d.]+),([-\d.]+)\)"', l)
        if not m:
            continue
        ind = len(l) - len(l.lstrip())
        if ind == 4:
            cur = m.group(2)
            if cur == 'r1':
                print('  r1 @ %s,%s [%s]' % (m.group(3), m.group(4), m.group(1)), end='')
        elif ind == 6 and cur == 'r1' and ('part-value' in m.group(1) or 'lini-ref' in m.group(1)):
            print(' %s %s,%s' % ('value' if 'part-value' in m.group(1) else 'ref', m.group(3), m.group(4)), end='')
    print('   (%s pin %s)' % (comp, target))

