#!/usr/bin/env python3
# J connector (rotated 180) with chains; print offsets relative to u1 (the J)
import sys, re, os
sys.path.insert(0, '/tmp/sch/scripts')
from summ import run

n = int(os.environ.get('PINS', '4'))
rot = os.environ.get('ROT', '180')
for body in sys.argv[1:]:
    src = '{ layout: schematic; |vcc::label| { symbol: power } [ "5V" ] }\n|J#u1| "CONN" { pins: %d; rotate: %s; }\n|BT#bt1| "4k7"\n|R#r1| "1k"\n|R#r2| "1k"\n%s\n' % (n, rot, body.replace('\\n', '\n'))
    exes = ['/workspace/executable', '/tmp/bin-sch/executable'] if os.environ.get('BOTH') else ['/workspace/executable']
    for exe in exes:
        o, e, c = run(src, exe=exe)
        pos = {i: (float(x), float(y)) for i, x, y in re.findall(r'data-id="([^"]+)" transform="translate\(([-\d.]+),([-\d.]+)\)', o)}
        u = pos.get('u1')
        out = []
        for i in ('bt1', 'r1', 'r2', 'lini-cap-1', 'lini-cap-2', 'lini-cap-3'):
            if i in pos:
                out.append('%s(%g,%g)' % (i, pos[i][0] - u[0], pos[i][1] - u[1]))
        ls = re.findall(r'<g class="lini-link"[^>]*>\n\s*<path d="([^"]*)"', o)
        print('%-40s %s | %s' % (body.replace('\\n', ' ; '), ' '.join(out), ' || '.join(ls)))

