#!/usr/bin/env python3
# categorize failures: which kinds of lines differ between original and mine
import sys, os, re, subprocess, collections
files = sys.argv[1:]
cats = collections.Counter()
per = {}
for f in files:
    d = os.path.dirname(f); b = os.path.basename(f)
    r1 = subprocess.run(['/workspace/executable', b], capture_output=True, cwd=d, text=True)
    r2 = subprocess.run(['/tmp/bin-sch/executable', b], capture_output=True, cwd=d, text=True)
    if r1.stdout == r2.stdout and r1.stderr == r2.stderr:
        continue
    o = r1.stdout.split('\n'); m = r2.stdout.split('\n')
    kinds = set()
    if r1.stderr != r2.stderr:
        kinds.add('stderr')
    if len(o) != len(m):
        kinds.add('linecount')
    for a, bb in zip(o, m):
        if a == bb:
            continue
        if 'viewBox' in a: kinds.add('viewbox')
        elif 'lini-scope' in a and ('{' in a): kinds.add('css')
        elif '<path' in a: kinds.add('path')
        elif 'lini-link-label' in a: kinds.add('linklabel')
        elif 'lini-junction' in a: kinds.add('junction')
        elif 'part-value' in a or 'lini-ref' in a: kinds.add('partlabel')
        elif 'data-id' in a: kinds.add('nodepos')
        elif 'lini-canvas' in a: pass
        else: kinds.add('other')
    key = ','.join(sorted(kinds))
    cats[key] += 1
    per.setdefault(key, []).append(b)
for k, v in cats.most_common():
    print('%4d %s   e.g. %s' % (v, k, ' '.join(per[k][:6])))

