90	// the station a part leaves by, entered at `t`
91	pub fn exit_of(ctx: &Ctx, t: &Term) -> Option<Term> {
92	    if t.kind != Kind::Station {
93	        return None;
94	    }
95	    for &c in &ctx.nodes[t.dev].children {
96	        if c != t.node && ctx.nodes[c].id.is_some() && ctx.comp[c].pin.as_deref() == Some("center") {
97	            let o = origin_in(ctx, c, t.dev);
98	            return Some(Term { node: c, dev: t.dev, kind: Kind::Station, off: o, dir: Dir::of_vec(o.0, o.1), through: None });
99	        }
100	    }
101	    None
102	}
103	
104	// the way a wire travels on entering `t`'s element
105	pub fn travel(ctx: &Ctx, t: &Term) -> Dir {
106	    match t.kind {
107	        Kind::Station => match exit_of(ctx, t) {
108	            Some(o) => Dir::of_vec(o.off.0 - t.off.0, o.off.1 - t.off.1),
109	            None => t.dir.opposite(),
110	        },
111	        _ => t.dir.opposite(),
112	    }
113	}
