115	// the point of an element that sits on the lattice: a part's or a tag's
116	// centre, a symbol's connection point
117	fn lattice_point(t: &Term) -> (f64, f64) {
118	    match t.kind {
119	        Kind::Symbol => t.off,
120	        _ => (0.0, 0.0),
121	    }
122	}
123	
124	fn overlaps(a: &[f64; 4], b: &[f64; 4]) -> bool {
125	    a[0] < b[2] - 1e-9 && b[0] < a[2] - 1e-9 && a[1] < b[3] - 1e-9 && b[1] < a[3] - 1e-9
126	}
