132	// one chain's planned elements
133	#[derive(Clone, Debug)]
134	struct Plan {
135	    pin: usize,
136	    f: Dir,
137	    d1: Dir,
138	    row: f64,
139	    // elements with the lane at 0 (turned) or final (straight)
140	    els: Vec<(usize, f64, f64, [f64; 4])>,
141	    // the first wire's run along the lane: (from, to) on the lane's axis
142	    run: (f64, f64),
143	    min_lane: f64,
144	    key: usize,
145	    parts: bool,
146	}
