148	// a turned chain's first hop: (pin node, pin term, entry term, the pin's
149	// facing, the travel, the pin's row, the first element's lattice coordinate)
150	pub type Turn = (usize, Term, Term, Dir, Dir, f64, f64);
151	
152	pub struct Seater<'a> {
153	    pub ctx: &'a Ctx,
154	    pub wires: &'a [Wire],
155	    pub gap: f64,
156	    // per device: its origin, anchor-local (NaN: seated by another anchor)
157	    pub placed: std::collections::HashMap<usize, (f64, f64)>,
158	    pub seats: Vec<Seat>,
159	    aext: [f64; 4],
160	    straight: Vec<[f64; 4]>,
161	}
162	
163	impl<'a> Seater<'a> {
164	    pub fn new(ctx: &'a Ctx, wires: &'a [Wire], gap: f64) -> Self {
165	        Seater { ctx, wires, gap, placed: Default::default(), seats: vec![], aext: [0.0; 4], straight: vec![] }
166	    }
167	
168	    pub fn gap_margin(&self) -> f64 {
169	        PITCH / 2.0 + PITCH * (self.gap / (2.0 * PITCH)).floor()
170	    }
171	
172	    // the lattice cells an element at (x, y) reserves; a part in a lane keeps
173	    // the gap margin across the lane (`lane`: the pin's facing)
174	    fn reserve(&self, dev: usize, x: f64, y: f64, lp: (f64, f64), lane: Option<Dir>) -> [f64; 4] {
175	        let b = body(self.ctx, dev);
176	        let (px, py) = (x + lp.0, y + lp.1);
177	        let (x0, x1) = (px - cell_half(px - (x + b[0])), px + cell_half(x + b[2] - px));
178	        let (y0, y1) = (py - cell_half(py - (y + b[1])), py + cell_half(y + b[3] - py));
179	        let mut r = [x0, y0, x1, y1];
180	        if let Some(f) = lane {
181	            if is_part(self.ctx, dev) {
182	                let m = self.gap_margin();
183	                if f.horizontal() {
184	                    r[0] = r[0].min(px - m);
185	                    r[2] = r[2].max(px + m);
186	                } else {
187	                    r[1] = r[1].min(py - m);
188	                    r[3] = r[3].max(py + m);
189	                }
190	            }
191	        }
192	        r
193	    }
194	
195	    // the lattice cells of an element in a pin's row: its body and its
196	    // value and reference as they will stand (stacked or split)
197	    fn reserve_row(&self, dev: usize, x: f64, y: f64, lp: (f64, f64), stack: i8) -> [f64; 4] {
198	        let ctx = self.ctx;
199	        let mut b = body(ctx, dev);
200	        let (rot, _) = super::net::pose_of(ctx, dev);
201	        if is_part(ctx, dev) && rot != 90 && rot != 270 {
202	            let h = ctx.nodes[dev].h;
203	            let mut val = None;
204	            let mut rf = None;
205	            for &k in &ctx.nodes[dev].children {
206	                if super::place::has(ctx, k, "part-value") {
207	                    val = Some(k);
208	                } else if super::place::has(ctx, k, "ref") {
209	                    rf = Some(k);
210	                }
211	            }
212	            let size = |k: usize| crate::layout::outer(ctx, k);
213	            let mut add = |k: usize, cy: f64| {
214	                let (w, lh) = size(k);
215	                b[0] = b[0].min(-w / 2.0);
216	                b[2] = b[2].max(w / 2.0);
217	                b[1] = b[1].min(cy - lh / 2.0);
218	                b[3] = b[3].max(cy + lh / 2.0);
219	            };
220	            match stack {
221	                -1 => {
222	                    let mut at = -h / 2.0;
223	                    for k in [val, rf].into_iter().flatten() {
224	                        let lh = size(k).1;
225	                        let cy = if at == -h / 2.0 { at - (20.0 - lh / 2.0) } else { at - 16.0 };
226	                        add(k, cy);
227	                        at = cy;
228	                    }
229	                }
230	                1 => {
231	                    let mut at = h / 2.0;
232	                    for k in [rf, val].into_iter().flatten() {
233	                        let lh = size(k).1;
234	                        let cy = if at == h / 2.0 { at + (20.0 - lh / 2.0) } else { at + 16.0 };
235	                        add(k, cy);
236	                        at = cy;
237	                    }
238	                }
239	                _ => {
240	                    if let Some(k) = rf {
241	                        let lh = size(k).1;
242	                        add(k, -h / 2.0 - (20.0 - lh / 2.0));
243	                    }
244	                    if let Some(k) = val {
245	                        let lh = size(k).1;
246	                        add(k, h / 2.0 + (20.0 - lh / 2.0));
247	                    }
248	                }
249	            }
250	        }
251	        let (px, py) = (x + lp.0, y + lp.1);
252	        let (x0, x1) = (px - cell_half(px - (x + b[0])), px + cell_half(x + b[2] - px));
253	        let (y0, y1) = (py - cell_half(py - (y + b[1])), py + cell_half(y + b[3] - py));
254	        [x0, y0, x1, y1]
255	    }
256	
257	    fn put(&mut self, dev: usize, x: f64, y: f64, res: [f64; 4], stack: i8, side: Option<Dir>) {
258	        self.placed.insert(dev, (x, y));
259	        self.seats.push(Seat { node: dev, x, y, res, stack, side });
260	    }
261	
262	    // the elements past the one at (sx, sy) entered at `q`, travelling `d`
263	    // (planned, not yet seated): appended to `els`
264	    fn walk(&self, q: &Term, sx: f64, sy: f64, d: Dir, lane: Option<Dir>, els: &mut Vec<(usize, f64, f64, [f64; 4])>, seen: &mut Vec<usize>) {
265	        let ctx = self.ctx;
266	        let exit = match q.kind {
267	            Kind::Station => match exit_of(ctx, q) {
268	                Some(e) => e,
269	                None => return,
270	            },
271	            _ => q.clone(),
272	        };
273	        let sb = body(ctx, q.dev);
274	        let sbox = [sx + sb[0], sy + sb[1], sx + sb[2], sy + sb[3]];
275	        let ep = (sx + exit.off.0, sy + exit.off.1);
276	        let nexts: Vec<Term> = self
277	            .wires
278	            .iter()
279	            .filter_map(|w| {
280	                if w.a.node == exit.node && w.b.dev != q.dev {
281	                    Some(w.b.clone())
282	                } else if w.b.node == exit.node && w.a.dev != q.dev {
283	                    Some(w.a.clone())
284	                } else {
285	                    None
286	                }
287	            })
288	            .collect();
289	        for t in nexts {
290	            if self.placed.contains_key(&t.dev) || seen.contains(&t.dev) || !is_satellite(ctx, t.dev) {
291	                continue;
292	            }
293	            let t = super::net::flag_end(&t, d.opposite());
294	            let d2 = if t.kind == Kind::Flag { d } else { travel(ctx, &t) };
295	            if d2 != d {
296	                continue;
297	            }
298	            let b = body(ctx, t.dev);
299	            let lp = lattice_point(&t);
300	            let far = match d {
301	                Dir::R => sbox[2],
302	                Dir::L => -sbox[0],
303	                Dir::D => sbox[3],
304	                Dir::U => -sbox[1],
305	            };
306	            let (behind, _) = reach(&b, lp, d);
307	            let a = snap_out(d, sgn(d) * (far + PITCH + behind));
308	            let (x, y) = if d.horizontal() { (a - lp.0, ep.1 - t.off.1) } else { (ep.0 - t.off.0, a - lp.1) };
309	            let res = self.reserve(t.dev, x, y, lp, lane);
310	            seen.push(t.dev);
311	            els.push((t.dev, x, y, res));
312	            self.walk(&t, x, y, d2, lane, els, seen);
313	        }
314	    }
315	
316	    // Seat the chains leaving an anchor: `aext` its drawn extent, `hops` the
317	    // first wires off its pins (pin node, pin term, far term), `wired` every
318	    // wired pin of it (term).
319	    pub fn seat_first(&mut self, aext: [f64; 4], hops: &[(usize, Term, Term)], wired: &[Term]) -> Vec<Turn> {
320	        let ctx = self.ctx;
321	        self.aext = aext;
322	        let mut straight_boxes: Vec<[f64; 4]> = Vec::new();
323	        let mut turned: Vec<Turn> = Vec::new();
324	        for (pin, p, q0) in hops {
325	            if self.placed.contains_key(&q0.dev) || turned.iter().any(|t| t.2.dev == q0.dev) {
326	                continue;
327	            }
328	            let f = p.dir;
329	            let ext = match f {
330	                Dir::R => aext[2],
331	                Dir::L => -aext[0],
332	                Dir::D => aext[3],
333	                Dir::U => -aext[1],
334	            };
335	            let q = super::net::flag_end(q0, f.opposite());
336	            let d1 = if q.kind == Kind::Flag { f } else { travel(ctx, &q) };
337	            let b = body(ctx, q.dev);
338	            let lp = lattice_point(&q);
339	            if d1 == f {
340	                // straight: in the pin's row, labels away from the side's other pins
341	                let (behind, _) = reach(&b, lp, f);
342	                let a = snap_out(f, sgn(f) * (ext + PITCH + behind));
343	                let (x, y) = if f.horizontal() { (a - lp.0, p.off.1 - q.off.1) } else { (p.off.0 - q.off.0, a - lp.1) };
344	                let stack = stack_mode(ctx, p, wired, *pin);
345	                let res = self.reserve_row(q.dev, x, y, lp, stack);
346	                let mut els = vec![(q.dev, x, y, res)];
347	                let mut seen = vec![q.dev];
348	                self.walk(&q, x, y, d1, None, &mut els, &mut seen);
349	                for (dev, x, y, res) in els {
350	                    straight_boxes.push(res);
351	                    self.put(dev, x, y, res, stack, None);
352	                }
353	                continue;
354	            }
355	            if d1 == f.opposite() {
356	                continue;
357	            }
358	            // turned: the chain stands in a lane, clear of the wired rows it
359	            // passes on this side
360	            let row = coord(d1, p.off);
361	            let mut clear = row;
362	            for w in wired {
363	                if w.dir != f {
364	                    continue;
365	                }
366	                let r = coord(d1, w.off);
367	                if sgn(d1) * (r - clear) > 0.0 {
368	                    clear = r;
369	                }
370	            }
371	            let (behind, _) = reach(&b, lp, d1);
372	            let a = snap_out(d1, clear + sgn(d1) * (PITCH + behind));
373	            turned.push((*pin, p.clone(), q.clone(), f, d1, row, a));
374	        }
375	        self.straight = straight_boxes;
376	        turned
377	    }
378	
379	    // the turned chains, their first elements already aligned: lanes
380	    pub fn seat_lanes(&mut self, turned: Vec<Turn>) {
381	        let ctx = self.ctx;
382	        let aext = self.aext;
383	        let straight_boxes = self.straight.clone();
384	        let mut plans: Vec<Plan> = Vec::new();
385	        for (pin, _p, q, f, d1, row, a) in turned {
386	            let b = body(ctx, q.dev);
387	            let lp = lattice_point(&q);
388	            let ext = match f {
389	                Dir::R => aext[2],
390	                Dir::L => -aext[0],
391	                Dir::D => aext[3],
392	                Dir::U => -aext[1],
393	            };
394	            // the entry point on lane 0
395	            let (x, y) = if f.horizontal() { (-q.off.0, a - lp.1) } else { (a - lp.0, -q.off.1) };
396	            let res = self.reserve(q.dev, x, y, lp, Some(f));
397	            let mut els = vec![(q.dev, x, y, res)];
398	            let mut seen = vec![q.dev];
399	            self.walk(&q, x, y, d1, Some(f), &mut els, &mut seen);
400	            // the lane clears the anchor by a pitch past what it reserves
401	            let mut near: f64 = 0.0;
402	            for e in &els {
403	                let n = match f {
404	                    Dir::R => -e.3[0],
405	                    Dir::L => e.3[2],
406	                    Dir::D => -e.3[1],
407	                    Dir::U => e.3[3],
408	                };
409	                near = near.max(n);
410	            }
411	            let _ = b;
412	            let min_lane = snap_out(f, sgn(f) * (ext + PITCH + near));
413	            let entry = coord(d1, (x + q.off.0, y + q.off.1));
414	            let parts = is_part(ctx, q.dev) || els.iter().any(|e| is_part(ctx, e.0));
415	            plans.push(Plan { pin, f, d1, row, els, run: (row.min(entry), row.max(entry)), min_lane, key: q.dev, parts });
416	        }
417	        // the lanes, side by side
418	        for f in [Dir::L, Dir::R, Dir::U, Dir::D] {
419	            let mine: Vec<usize> = (0..plans.len()).filter(|&k| plans[k].f == f).collect();
420	            if mine.is_empty() {
421	                continue;
422	            }
423	            let base = mine.iter().map(|&k| plans[k].min_lane).fold(if sgn(f) > 0.0 { f64::NEG_INFINITY } else { f64::INFINITY }, |a, b| if sgn(f) > 0.0 { a.max(b) } else { a.min(b) });
424	            // pins whose chains run toward the lower coordinate first, nearest
425	            // that end first; then the others, from the far end
426	            let mut pins: Vec<(usize, Dir, f64)> = Vec::new();
427	            for &k in &mine {
428	                let pl = &plans[k];
429	                if !pins.iter().any(|p| p.0 == pl.pin) {
430	                    pins.push((pl.pin, pl.d1, pl.row));
431	                }
432	            }
433	            pins.sort_by(|a, b| {
434	                let ka = if sgn(a.1) < 0.0 { (0, a.2) } else { (1, -a.2) };
435	                let kb = if sgn(b.1) < 0.0 { (0, b.2) } else { (1, -b.2) };
436	                ka.partial_cmp(&kb).unwrap_or(std::cmp::Ordering::Equal)
437	            });
438	            let mut boxes: Vec<[f64; 4]> = straight_boxes.clone();
439	            let mut runs: Vec<(f64, (f64, f64))> = Vec::new();
440	            for (pin, _, _) in pins {
441	                let mut chains: Vec<usize> = mine.iter().cloned().filter(|&k| plans[k].pin == pin).collect();
442	                chains.sort_by_key(|&k| (!plans[k].parts, plans[k].key));
443	                let mut outer: Option<f64> = None;
444	                for k in chains {
445	                    let pl = plans[k].clone();
446	                    let start = if pl.parts { base } else { outer.unwrap_or(base) };
447	                    let mut lane = start;
448	                    for _ in 0..200 {
449	                        let shifted: Vec<[f64; 4]> = pl.els.iter().map(|e| shift_box(&e.3, f, lane)).collect();
450	                        let hit_box = shifted.iter().any(|r| boxes.iter().any(|o| overlaps(r, o)));
451	                        let hit_run = runs.iter().any(|(l, (a, b))| (*l - lane).abs() < 1e-9 && pl.run.0 < *b - 1e-9 && *a < pl.run.1 - 1e-9);
452	                        // the lane's own wire passes no seated element
453	                        let hit_wire = boxes.iter().any(|o| {
454	                            let (c0, c1, a0, a1) = if f.horizontal() { (o[0], o[2], o[1], o[3]) } else { (o[1], o[3], o[0], o[2]) };
455	                            lane > c0 + 1e-9 && lane < c1 - 1e-9 && a0 < pl.run.1 - 1e-9 && pl.run.0 < a1 - 1e-9
456	                        });
457	                        if !hit_box && !hit_run && !hit_wire {
458	                            break;
459	                        }
460	                        lane += sgn(f) * PITCH;
461	                    }
462	                    for e in &pl.els {
463	                        let r = shift_box(&e.3, f, lane);
464	                        boxes.push(r);
465	                        let (x, y) = if f.horizontal() { (e.1 + lane, e.2) } else { (e.1, e.2 + lane) };
466	                        self.put(e.0, x, y, r, 0, Some(f));
467	                    }
468	                    runs.push((lane, pl.run));
469	                    outer = Some(match outer {
470	                        Some(o) if sgn(f) * (o - lane) > 0.0 => o,
471	                        _ => lane,
472	                    });
473	                }
474	            }
475	        }
476	    }
477	}
478	
479	// the first elements of chains turning one way stand in one row
480	pub fn align(turns: &mut [&mut Turn], dirs: &[Dir]) {
481	    for &d in dirs {
482	        let mut deepest: Option<f64> = None;
483	        for t in turns.iter() {
484	            if t.4 == d {
485	                deepest = Some(match deepest {
486	                    Some(v) if sgn(d) * (v - t.6) >= 0.0 => v,
487	                    _ => t.6,
488	                });
489	            }
490	        }
491	        if let Some(v) = deepest {
492	            for t in turns.iter_mut() {
493	                if t.4 == d {
494	                    t.6 = v;
495	                }
496	            }
497	        }
498	    }
499	}
500	
501	fn shift_box(r: &[f64; 4], f: Dir, lane: f64) -> [f64; 4] {
502	    if f.horizontal() {
503	        [r[0] + lane, r[1], r[2] + lane, r[3]]
504	    } else {
505	        [r[0], r[1] + lane, r[2], r[3] + lane]
506	    }
507	}
508	
509	// a part in a pin's row reads its labels away from the side's other pins:
510	// above at the top pin, below at the bottom pin, split between
511	fn stack_mode(ctx: &Ctx, p: &Term, _wired: &[Term], _pin: usize) -> i8 {
512	    if !p.dir.horizontal() {
513	        return 0;
514	    }
515	    // the anchor's pins on this side
516	    let mut ys: Vec<f64> = Vec::new();
517	    for k in super::place::pins_of(ctx, p.dev) {
518	        if let Some(t) = super::net::term(ctx, ctx.nodes[p.dev].parent.unwrap_or(0), k) {
519	            if t.dir == p.dir {
520	                ys.push(t.off.1);
521	            }
522	        }
523	    }
524	    if ys.len() < 2 {
525	        return 0;
526	    }
527	    let lo = ys.iter().cloned().fold(f64::INFINITY, f64::min);
528	    let hi = ys.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
529	    if (p.off.1 - lo).abs() < 1e-9 {
530	        -1
531	    } else if (p.off.1 - hi).abs() < 1e-9 {
532	        1
533	    } else {
534	        0
535	    }
536	}
