444	pub fn measure(ctx: &mut Ctx, i: usize, _avail: Option<f64>) {
445	    let c = ctx.comp[i].clone();
446	    let pad = c.padding;
447	    let children = ctx.nodes[i].children.clone();
448	    let mut flow = Vec::new();
449	    let mut pinned = Vec::new();
450	    for &ch in &children {
451	        if ctx.comp[ch].pin.is_some() {
452	            pinned.push(ch);
453	        } else {
454	            flow.push(ch);
455	        }
456	    }
457	    for &ch in &children {
458	        crate::layout::measure(ctx, ch, None);
459	    }
460	    for &ch in &flow {
461	        seat_all(ctx, ch);
462	    }
463	    let (row_gap, col_gap) = c.gap;
464	    // roles
465	    let mut anchors = Vec::new();
466	    let mut sats = Vec::new();
467	    for &ch in &flow {
468	        match role(ctx, ch) {
469	            Role::Anchor => anchors.push(ch),
470	            Role::Satellite => sats.push(ch),
471	        }
472	    }
473	    // satellites seated off the anchors' pins, anchor by anchor
474	    let wires = super::net::wires(ctx, i);
475	    let mut clusters: Vec<(usize, Vec<super::seat::Seat>)> = Vec::new();
476	    let mut seated: std::collections::HashSet<usize> = Default::default();
477	    // the anchors' grid rows (an uncelled anchor rides the first)
478	    let row_of = |ctx: &Ctx, a: usize| -> usize {
479	        ctx.nodes[a]
480	            .props
481	            .get("cell")
482	            .map(|v| crate::style::value_nums(&ctx.sheet.env, v))
483	            .filter(|v| v.len() >= 2)
484	            .map(|v| v[1].max(1.0) as usize)
485	            .unwrap_or(1)
486	    };
487	    let mut seaters: Vec<super::seat::Seater> = Vec::new();
488	    let mut turns: Vec<Vec<super::seat::Turn>> = Vec::new();
489	    for &a in &anchors {
490	        let mut st = super::seat::Seater::new(ctx, &wires, col_gap);
491	        for &k in &seated {
492	            st.placed.insert(k, (f64::NAN, f64::NAN));
493	        }
494	        let aext = extent(ctx, a);
495	        // first hops off this anchor's pins: (pin node, pin term, far term)
496	        let mut hops: Vec<(usize, super::net::Term, super::net::Term)> = Vec::new();
497	        for w in &wires {
498	            for (p, q) in [(&w.a, &w.b), (&w.b, &w.a)] {
499	                if p.dev == a
500	                    && q.dev != a
501	                    && matches!(p.kind, super::net::Kind::Pin | super::net::Kind::Station)
502	                    && role(ctx, q.dev) == Role::Satellite
503	                {
504	                    hops.push((p.node, p.clone(), q.clone()));
505	                }
506	            }
507	        }
508	        // every wired pin of the anchor
509	        let mut wired: Vec<super::net::Term> = Vec::new();
510	        for w in &wires {
511	            for t in [&w.a, &w.b] {
512	                if t.dev == a && matches!(t.kind, super::net::Kind::Pin | super::net::Kind::Station) && !wired.iter().any(|x| x.node == t.node) {
513	                    wired.push(t.clone());
514	                }
515	            }
516	        }
517	        let tv = st.seat_first(aext, &hops, &wired);
518	        for s in &st.seats {
519	            seated.insert(s.node);
520	        }
521	        for t in &tv {
522	            seated.insert(t.2.dev);
523	        }
524	        seaters.push(st);
525	        turns.push(tv);
526	    }
527	    // up and down chains align across the anchors of a grid row; left and
528	    // right ones per anchor
529	    let rows: Vec<usize> = anchors.iter().map(|&a| row_of(ctx, a)).collect();
530	    let mut row_ids: Vec<usize> = rows.clone();
531	    row_ids.sort();
532	    row_ids.dedup();
533	    for r in row_ids {
534	        let mut refs: Vec<&mut super::seat::Turn> = Vec::new();
535	        for (k, tv) in turns.iter_mut().enumerate() {
536	            if rows[k] == r {
537	                for t in tv.iter_mut() {
538	                    refs.push(t);
539	                }
540	            }
541	        }
542	        super::seat::align(&mut refs, &[super::net::Dir::U, super::net::Dir::D]);
543	    }
544	    for tv in turns.iter_mut() {
545	        let mut refs: Vec<&mut super::seat::Turn> = tv.iter_mut().collect();
546	        super::seat::align(&mut refs, &[super::net::Dir::L, super::net::Dir::R]);
547	    }
548	    for (k, mut st) in seaters.into_iter().enumerate() {
549	        let tv = std::mem::take(&mut turns[k]);
550	        st.seat_lanes(tv);
551	        let seats: Vec<super::seat::Seat> = st.seats.clone();
552	        for s in &seats {
553	            seated.insert(s.node);
554	        }
555	        clusters.push((anchors[k], seats));
556	    }
557	    let mut loose = Vec::new();
558	    for &s in &sats {
559	        if !seated.contains(&s) {
560	            let name = display_name(ctx, s);
561	            let span = ctx.nodes[s].span;
562	            ctx.warnings.push(Diag::warning(
563	                "schematic-seat",
564	                &format!("'{}' has no placed end — its chain falls back to the flow", name),
565	                span,
566	            ));
567	            loose.push(s);
568	        }
569	    }
570	    // each anchor's reach: its own drawn extent and its satellites' cells
571	    let mut reach: Vec<[f64; 4]> = Vec::new();
572	    for (a, seats) in &clusters {
573	        let mut e = extent(ctx, *a);
574	        for s in seats {
575	            e[0] = e[0].min(s.res[0]);
576	            e[1] = e[1].min(s.res[1]);
577	            e[2] = e[2].max(s.res[2]);
578	            e[3] = e[3].max(s.res[3]);
579	        }
580	        reach.push(e);
581	    }
582	    // positions in lattice coordinates (origin: the first track's line)
583	    let mut pos: Vec<(usize, f64, f64)> = Vec::new();
584	    let mut ext = [f64::INFINITY, f64::INFINITY, f64::NEG_INFINITY, f64::NEG_INFINITY];
585	    if !anchors.is_empty() {
586	        grid(ctx, i, &anchors, &reach, row_gap, col_gap, &mut pos);
587	        for (k, &(_, x, y)) in pos.iter().enumerate() {
588	            let e = reach[k];
589	            ext[0] = ext[0].min(x + e[0]);
590	            ext[1] = ext[1].min(y + e[1]);
591	            ext[2] = ext[2].max(x + e[2]);
592	            ext[3] = ext[3].max(y + e[3]);
593	        }
594	    }
595	    // the fallback row under the grid, centred on the lattice origin
596	    let mut row: Vec<(usize, f64, f64)> = Vec::new();
597	    let mut rbox = [f64::INFINITY, f64::INFINITY, f64::NEG_INFINITY, f64::NEG_INFINITY];
598	    if !loose.is_empty() {
599	        let sizes: Vec<(f64, f64)> = loose.iter().map(|&k| crate::layout::outer(ctx, k)).collect();
600	        let total: f64 = sizes.iter().map(|s| s.0).sum::<f64>() + col_gap * (loose.len() as f64 - 1.0);
601	        let hmax = sizes.iter().map(|s| s.1).fold(0.0, f64::max);
602	        let top = if anchors.is_empty() { -hmax / 2.0 } else { ext[3] + ceil_lattice(row_gap) };
603	        let cy = top + hmax / 2.0;
604	        let mut x = -total / 2.0;
605	        for (k, &ch) in loose.iter().enumerate() {
606	            let (w, _) = sizes[k];
607	            row.push((ch, x + w / 2.0, cy));
608	            x += w + col_gap;
609	        }
610	        rbox = [-total / 2.0, top, total / 2.0, top + hmax];
611	    }
612	    // centre the whole on the lattice
613	    let mut all = ext;
614	    all[0] = all[0].min(rbox[0]);
615	    all[1] = all[1].min(rbox[1]);
616	    all[2] = all[2].max(rbox[2]);
617	    all[3] = all[3].max(rbox[3]);
618	    let (ox, oy) = if anchors.is_empty() {
619	        (-(all[0] + all[2]) / 2.0, -(all[1] + all[3]) / 2.0)
620	    } else {
621	        (round_lattice(-(all[0] + all[2]) / 2.0), round_lattice(-(all[1] + all[3]) / 2.0))
622	    };
623	    // every body's lattice cells, scope-local: what the wires go around
624	    let mut bodies: Vec<(usize, [f64; 4])> = Vec::new();
625	    for (k, &(a, x, y)) in pos.iter().enumerate() {
626	        place_node(ctx, a, x + ox, y + oy);
627	        for b in drawn_boxes(ctx, a) {
628	            bodies.push((a, b));
629	        }
630	        for s in &clusters[k].1 {
631	            place_node(ctx, s.node, x + ox + s.x, y + oy + s.y);
632	            raise_run(ctx, s.node);
633	            stack_labels(ctx, s.node, s.stack);
634	            if s.side == Some(super::net::Dir::L) {
635	                flip_side_labels(ctx, s.node);
636	            }
637	            for b in drawn_boxes(ctx, s.node) {
638	                bodies.push((s.node, b));
639	            }
640	        }
641	    }
642	    for &(k, x, y) in &row {
643	        ctx.nodes[k].x = x + ox;
644	        ctx.nodes[k].y = y + oy;
645	        for b in drawn_boxes(ctx, k) {
646	            bodies.push((k, b));
647	        }
648	    }
649	    BODIES.with(|b| b.borrow_mut().push((i, bodies)));
650	    // the symmetric hull
651	    let mut hw: f64 = 0.0;
652	    let mut hh: f64 = 0.0;
653	    if !anchors.is_empty() {
654	        hw = hw.max((ext[0] + ox).abs()).max((ext[2] + ox).abs());
655	        hh = hh.max((ext[1] + oy).abs()).max((ext[3] + oy).abs());
656	    }
657	    if !loose.is_empty() {
658	        hw = hw.max((rbox[0] + ox).abs()).max((rbox[2] + ox).abs());
659	        hh = hh.max((rbox[1] + oy).abs()).max((rbox[3] + oy).abs());
660	    }
661	    let mut w = 2.0 * hw + pad[1] + pad[3];
662	    let mut h = 2.0 * hh + pad[0] + pad[2];
663	    if let Some(fw) = c.width {
664	        w = w.max(fw);
665	    }
666	    if let Some(fh) = c.height {
667	        h = h.max(fh);
668	    }
669	    ctx.nodes[i].w = w;
670	    ctx.nodes[i].h = h;
671	    for &p in &pinned {
672	        crate::layout::place_pinned(ctx, i, p);
673	    }
674	}
675	
676	// a node's origin to (x, y): its box centre sits off it by its seat
677	pub fn place_node(ctx: &mut Ctx, k: usize, x: f64, y: f64) {
678	    let off = ctx.nodes[k].geo_off;
679	    ctx.nodes[k].x = x - off.0;
680	    ctx.nodes[k].y = y - off.1;
681	}
682	
683	// anchors on the track grid: `cell: c r` (ordinal, empty tracks collapsing),
684	// the rest along the first row; each track pitch clears the extents of its
685	// neighbours by a pin pitch, at least the scope's gap, on the lattice
686	fn grid(ctx: &Ctx, _scope: usize, anchors: &[usize], reach: &[[f64; 4]], row_gap: f64, col_gap: f64, pos: &mut Vec<(usize, f64, f64)>) {
687	    let env = &ctx.sheet.env;
688	    let mut cells: Vec<(usize, usize, usize)> = Vec::new(); // (node, col, row)
689	    let mut taken: Vec<(usize, usize)> = Vec::new();
690	    for &k in anchors {
691	        if let Some(v) = ctx.nodes[k].props.get("cell") {
692	            let xs = crate::style::value_nums(env, v);
693	            if xs.len() >= 2 {
694	                let cc = (xs[0].max(1.0)) as usize;
695	                let rr = (xs[1].max(1.0)) as usize;
696	                cells.push((k, cc, rr));
697	                taken.push((cc, rr));
698	                continue;
699	            }
700	        }
701	        cells.push((k, 0, 0));
702	    }
703	    // the rest fill the first row's free tracks in order
704	    let mut next = 1usize;
705	    for c in cells.iter_mut() {
706	        if c.1 == 0 {
707	            while taken.contains(&(next, 1)) {
708	                next += 1;
709	            }
710	            c.1 = next;
711	            c.2 = 1;
712	            taken.push((next, 1));
713	            next += 1;
714	        }
715	    }
716	    // collapse empty tracks
717	    let mut cols: Vec<usize> = cells.iter().map(|c| c.1).collect();
718	    cols.sort();
719	    cols.dedup();
720	    let mut rows: Vec<usize> = cells.iter().map(|c| c.2).collect();
721	    rows.sort();
722	    rows.dedup();
723	    let exts: Vec<[f64; 4]> = reach.to_vec();
724	    let col_of = |c: usize| cols.iter().position(|&x| x == c).unwrap();
725	    let row_of = |r: usize| rows.iter().position(|&x| x == r).unwrap();
726	    let mut left = vec![0.0f64; cols.len()];
727	    let mut right = vec![0.0f64; cols.len()];
728	    let mut top = vec![0.0f64; rows.len()];
729	    let mut bottom = vec![0.0f64; rows.len()];
730	    for (k, c) in cells.iter().enumerate() {
731	        let (ci, ri) = (col_of(c.1), row_of(c.2));
732	        left[ci] = left[ci].max(-exts[k][0]);
733	        right[ci] = right[ci].max(exts[k][2]);
734	        top[ri] = top[ri].max(-exts[k][1]);
735	        bottom[ri] = bottom[ri].max(exts[k][3]);
736	    }
737	    let mut colx = vec![0.0; cols.len()];
738	    for k in 1..cols.len() {
739	        let need = ceil_lattice(right[k - 1] + left[k] + PITCH);
740	        colx[k] = colx[k - 1] + need.max(ceil_lattice(col_gap));
741	    }
742	    let mut rowy = vec![0.0; rows.len()];
743	    for k in 1..rows.len() {
744	        let need = ceil_lattice(bottom[k - 1] + top[k] + PITCH);
745	        rowy[k] = rowy[k - 1] + need.max(ceil_lattice(row_gap));
746	    }
747	    for c in &cells {
748	        pos.push((c.0, colx[col_of(c.1)], rowy[row_of(c.2)]));
749	    }

