    // fixed part the wire no longer turns toward its end (`turn`)
    #[allow(clippy::too_many_arguments)]
    fn arrive(&mut self, t: &Term, via: usize, d: Dir, d0: Dir, from: &Term, turn: bool, depth: usize) {
        if depth > 256 {
            return;
        }
        match t {
