349	// a part in a pin's row stacks its reference and value on one side, away
350	// from the side's other pins (-1 above, +1 below)
351	fn stack_labels(ctx: &mut Ctx, i: usize, stack: i8) {
352	    if stack == 0 || !is_part(ctx, i) {
353	        return;
354	    }
355	    let (rot, _) = super::net::pose_of(ctx, i);
356	    if rot == 90 || rot == 270 {
357	        return;
358	    }
359	    let h = ctx.nodes[i].h;
360	    let mut val = None;
361	    let mut rf = None;
362	    for k in ctx.nodes[i].children.clone() {
363	        if has(ctx, k, "part-value") {
364	            val = Some(k);
365	        } else if has(ctx, k, "ref") {
366	            rf = Some(k);
367	        }
368	    }
369	    let edge = if stack < 0 { -h / 2.0 } else { h / 2.0 };
370	    let s = stack as f64;
371	    // the nearer label sits where a pinned label would (20 off the body),
372	    // the other one stacked 16 further out
373	    let (near, far) = if stack < 0 { (val, rf) } else { (rf, val) };
374	    let mut next = None;
375	    // (a label's own `translate` rides on top of its place)
376	    if let Some(n) = near {
377	        let nh = crate::layout::outer(ctx, n).1;
378	        let at = edge + s * (20.0 - nh / 2.0);
379	        ctx.nodes[n].y = at - ctx.comp[n].translate.1;
380	        next = Some(at + s * 16.0);
381	    }
382	    if let Some(fk) = far {
383	        let fh = crate::layout::outer(ctx, fk).1;
384	        let at = next.unwrap_or(edge + s * (20.0 - fh / 2.0));
385	        ctx.nodes[fk].y = at - ctx.comp[fk].translate.1;
386	    }
387	}
