50	// a direct route: straight, or one corner
51	fn direct(a: (f64, f64), da: Dir, b: (f64, f64), db: Dir) -> Option<Vec<(f64, f64)>> {
52	    let ahead = |p: (f64, f64), d: Dir, q: (f64, f64)| -> bool {
53	        match d {
54	            Dir::R => q.0 > p.0 - 1e-9,
55	            Dir::L => q.0 < p.0 + 1e-9,
56	            Dir::D => q.1 > p.1 - 1e-9,
57	            Dir::U => q.1 < p.1 + 1e-9,
58	        }
59	    };
60	    if da == db.opposite() {
61	        let aligned = if da.horizontal() { same(a.1, b.1) } else { same(a.0, b.0) };
62	        if aligned && ahead(a, da, b) {
63	            return Some(vec![a, b]);
64	        }
65	        if ahead(a, da, b) {
66	            // a staircase: the jog halfway
67	            if da.horizontal() {
68	                let m = (a.0 + b.0) / 2.0;
69	                return Some(vec![a, (m, a.1), (m, b.1), b]);
70	            } else {
71	                let m = (a.1 + b.1) / 2.0;
72	                return Some(vec![a, (a.0, m), (b.0, m), b]);
73	            }
74	        }
75	        return None;
76	    }
77	    if da.horizontal() != db.horizontal() {
78	        let c = if da.horizontal() { (b.0, a.1) } else { (a.0, b.1) };
79	        if ahead(a, da, c) && ahead(b, db, c) {
80	            return Some(vec![a, c, b]);
81	        }
82	    }
83	    None
84	}
