86	// one wire: from port to port, a run travelled to its far end
87	fn route_one(ctx: &Ctx, obs: &[super::router::Rect], owner: &[usize], w: &super::net::Wire, lattice: (f64, f64)) -> Vec<(f64, f64)> {
88	    use super::router::Port;
89	    let port = |t: &Term| -> (Port, Option<(f64, f64)>) {
90	        let own = owner.iter().position(|&d| d == t.dev);
91	        if t.kind == Kind::Run {
92	            let o = origin_in(ctx, t.dev, 0);
93	            let far = (o.0 + t.off.0, o.1 + t.off.1);
94	            let near = t.through.map(|n| (o.0 + n.0, o.1 + n.1)).unwrap_or(far);
95	            return (Port { p: near, d: t.dir, own, free: true }, Some(far));
96	        }
97	        (Port { p: abs_point(ctx, t), d: t.dir, own, free: false }, None)
98	    };
99	    let (mut pa, fa) = port(&w.a);
100	    let (mut pb, fb) = port(&w.b);
101	    // a free port's own body never blocks it
102	    let drop: Vec<usize> = [&pa, &pb].iter().filter(|p| p.free).filter_map(|p| p.own).map(|k| owner[k]).collect();
103	    let mut obs2: Vec<super::router::Rect> = Vec::new();
104	    let mut own2: Vec<usize> = Vec::new();
105	    let mut remap: Vec<Option<usize>> = Vec::new();
106	    for (k, r) in obs.iter().enumerate() {
107	        if drop.contains(&owner[k]) {
108	            remap.push(None);
109	        } else {
110	            remap.push(Some(obs2.len()));
111	            obs2.push(*r);
112	            own2.push(owner[k]);
113	        }
114	    }
115	    for p in [&mut pa, &mut pb] {
116	        p.own = if p.free { None } else { p.own.and_then(|k| remap[k]) };
117	    }
118	    if std::env::var("LINI_SCH_DBG").is_ok() {
119	        eprintln!("route {:?} -> {:?}", pa, pb);
120	        for (k, r) in obs2.iter().enumerate() {
121	            eprintln!("  ob {} {:?}", k, r);
122	        }
123	    }
124	    let world = super::router::World { obs: obs2, owner: own2, lattice };
125	    let mut pts = match world.search(&pa, &pb, 2.0 * CLEAR) {
126	        Some(p) => p,
127	        None => direct(pa.p, pa.d, pb.p, pb.d).unwrap_or_else(|| vec![pa.p, pb.p]),
128	    };
129	    if let Some(f) = fa {
130	        pts.insert(0, f);
131	    }
132	    if let Some(f) = fb {
133	        pts.push(f);
134	    }
135	    super::router::simplify(&pts)
136	}
