138	pub fn route(ctx: &mut Ctx) {
139	    reset();
140	    if !super::active() {
141	        return;
142	    }
143	    let mut all = Wiring::default();
144	    let root_sch = ctx.comp[0].layout == "schematic";
145	    for s in 0..ctx.nodes.len() {
146	        if ctx.comp[s].layout != "schematic" {
147	            continue;
148	        }
149	        if s != 0 || !root_sch {
150	            // nested scopes draw wires with the schematic class
151	        }
152	        let wires = super::net::wires(ctx, s);
153	        if !wires.is_empty() && s != 0 {
154	            all.nested = true;
155	        }
156	        // the bodies wires go around, grown by the clearance
157	        let so = origin_in(ctx, s, 0);
158	        let mut obs: Vec<super::router::Rect> = Vec::new();
159	        let mut owner: Vec<usize> = Vec::new();
160	        super::place::BODIES.with(|b| {
161	            for (sc, list) in b.borrow().iter() {
162	                if *sc != s {
163	                    continue;
164	                }
165	                for (dev, r) in list {
166	                    obs.push(super::router::Rect::new(so.0 + r[0], so.1 + r[1], so.0 + r[2], so.1 + r[3]).grow(CLEAR + WIRE));
167	                    owner.push(*dev);
168	                }
169	            }
170	        });
171	        for w in &wires {
172	            let mut w = w.clone();
173	            // a tag attaches by the end facing the other end of its wire
174	            if w.a.kind == Kind::Flag {
175	                let o = origin_in(ctx, w.a.dev, 0);
176	                let p = abs_point(ctx, &w.b);
177	                w.a = super::net::flag_end(&w.a, if p.0 > o.0 { Dir::R } else { Dir::L });
178	            }
179	            if w.b.kind == Kind::Flag {
180	                let o = origin_in(ctx, w.b.dev, 0);
181	                let p = abs_point(ctx, &w.a);
182	                w.b = super::net::flag_end(&w.b, if p.0 > o.0 { Dir::R } else { Dir::L });
183	            }
184	            let pts = route_one(ctx, &obs, &owner, &w, so);
185	            all.wires.push(Routed { li: w.li, pts, label: None, scope: s });
186	        }
187	    }
188	    // net names along the trace
189	    let routes: Vec<Vec<(f64, f64)>> = all.wires.iter().map(|r| r.pts.clone()).collect();
190	    for (wi, r) in all.wires.iter_mut().enumerate() {
191	        let others: Vec<Vec<(f64, f64)>> = routes.iter().enumerate().filter(|(j, _)| *j != wi).map(|(_, p)| p.clone()).collect();
192	        let l = &ctx.links[r.li];
193	        if let Some(t) = link_text(ctx, r.li) {
194	            let along = ctx.links[r.li]
195	                .style
196	                .iter()
197	                .rev()
198	                .find(|d| d.name == "along")
199	                .and_then(|d| crate::style::value_num(&ctx.sheet.env, &d.value))
200	                .unwrap_or(0.5);
201	            r.label = Some(place_label(ctx, &r.pts, along, t, &others));
202	        }
203	        let _ = l;
204	    }
205	    all.junctions = junctions(ctx, &all.wires);
206	    WIRING.with(|w| *w.borrow_mut() = all);
207	}
