222	// a net name rides beside the trace at `along` of its length: above a level
223	// run, to the left of an upright one (turned to read up it)
224	fn place_label(ctx: &Ctx, pts: &[(f64, f64)], along: f64, text: String, others: &[Vec<(f64, f64)>]) -> (String, f64, f64, f64) {
225	    let mut total = 0.0;
226	    for k in 1..pts.len() {
227	        total += (pts[k].0 - pts[k - 1].0).abs() + (pts[k].1 - pts[k - 1].1).abs();
228	    }
229	    let tw = {
230	        let w = if ctx.comp[0].layout == "schematic" { ctx.comp[0].font_weight } else { 400 };
231	        crate::font::text_width(crate::font::Family::Sans, w, 11.0, &text)
232	    };
233	    let mut s = total * along;
234	    for k in 1..pts.len() {
235	        let (p, q) = (pts[k - 1], pts[k]);
236	        let len = (q.0 - p.0).abs() + (q.1 - p.1).abs();
237	        if s <= len + 1e-9 || k == pts.len() - 1 {
238	            let f = if len > 0.0 { s / len } else { 0.0 };
239	            let x = p.0 + (q.0 - p.0) * f;
240	            let y = p.1 + (q.1 - p.1) * f;
241	            if same(p.1, q.1) {
242	                return (text, x, y - 9.5, 0.0);
243	            }
244	            // upright: right of the trace unless a wire crowds it there
245	            // (within 5 of the name) and the left is clear
246	            let crowded = |lx: f64| -> bool {
247	                let m = 6.0;
248	                // the name's side of the trace only
249	                let b = if lx > x {
250	                    [x, y - tw / 2.0 - m, lx + 5.5 + m, y + tw / 2.0 + m]
251	                } else {
252	                    [lx - 5.5 - m, y - tw / 2.0 - m, x, y + tw / 2.0 + m]
253	                };
254	                let hit = |a: (f64, f64), c: (f64, f64)| -> bool {
255	                    let (x0, x1) = (a.0.min(c.0), a.0.max(c.0));
256	                    let (y0, y1) = (a.1.min(c.1), a.1.max(c.1));
257	                    x0 < b[2] - 1e-9 && x1 > b[0] + 1e-9 && y0 < b[3] - 1e-9 && y1 > b[1] + 1e-9
258	                        || (same(x0, x1) && x0 > b[0] + 1e-9 && x0 < b[2] - 1e-9 && y0 < b[3] - 1e-9 && y1 > b[1] + 1e-9)
259	                        || (same(y0, y1) && y0 > b[1] + 1e-9 && y0 < b[3] - 1e-9 && x0 < b[2] - 1e-9 && x1 > b[0] + 1e-9)
260	                };
261	                let own = (1..pts.len()).any(|j| j != k && hit(pts[j - 1], pts[j]));
262	                own || others.iter().any(|o| (1..o.len()).any(|j| hit(o[j - 1], o[j])))
263	            };
264	            if crowded(x + 9.5) && !crowded(x - 9.5) {
265	                return (text, x - 9.5, y, 270.0);
266	            }
267	            return (text, x + 9.5, y, 270.0);
268	        }
269	        s -= len;
270	    }
271	    (text, pts[0].0, pts[0].1 - 9.5, 0.0)
272	}
