274	// points where three ways of one net meet
275	fn junctions(ctx: &Ctx, wires: &[Routed]) -> Vec<(f64, f64)> {
276	    // nets: wires sharing a terminal node (pins, labels) join
277	    let n = wires.len();
278	    let mut parent: Vec<usize> = (0..n).collect();
279	    fn find(p: &mut Vec<usize>, i: usize) -> usize {
280	        let mut i = i;
281	        while p[i] != i {
282	            p[i] = p[p[i]];
283	            i = p[i];
284	        }
285	        i
286	    }
287	    let ends: Vec<(usize, usize)> = wires.iter().map(|r| (ctx.links[r.li].from, ctx.links[r.li].to)).collect();
288	    for i in 0..n {
289	        for j in 0..i {
290	            let (a, b) = ends[i];
291	            let (c, d) = ends[j];
292	            if a == c || a == d || b == c || b == d {
293	                let (x, y) = (find(&mut parent, i), find(&mut parent, j));
294	                parent[x] = y;
295	            }
296	        }
297	    }
298	    let mut out: Vec<(f64, f64)> = Vec::new();
299	    for i in 0..n {
300	        let root = find(&mut parent, i);
301	        // candidate points: this wire's vertices
302	        for &p in &wires[i].pts {
303	            if out.iter().any(|q| same(q.0, p.0) && same(q.1, p.1)) {
304	                continue;
305	            }
306	            let mut dirs: Vec<Dir> = Vec::new();
307	            for j in 0..n {
308	                if find(&mut parent, j) != root {
309	                    continue;
310	                }
311	                let pts = &wires[j].pts;
312	                for k in 1..pts.len() {
313	                    let (s, e) = (pts[k - 1], pts[k]);
314	                    for (from, to) in [(s, e), (e, s)] {
315	                        // a segment leaving p
316	                        if on_seg(p, from, to) && !(same(p.0, to.0) && same(p.1, to.1)) {
317	                            let d = Dir::of_vec(to.0 - p.0, to.1 - p.1);
318	                            if !dirs.contains(&d) {
319	                                dirs.push(d);
320	                            }
321	                        }
322	                    }
323	                }
324	            }
325	            if dirs.len() >= 3 {
326	                out.push(p);
327	            }
328	        }
329	    }
330	    out
331	}
