333	// p on the segment [a, b] (a included, b excluded unless a == b)
334	fn on_seg(p: (f64, f64), a: (f64, f64), b: (f64, f64)) -> bool {
335	    if same(a.1, b.1) && same(p.1, a.1) {
336	        let (lo, hi) = (a.0.min(b.0), a.0.max(b.0));
337	        return p.0 > lo - 1e-9 && p.0 < hi + 1e-9;
338	    }
339	    if same(a.0, b.0) && same(p.0, a.0) {
340	        let (lo, hi) = (a.1.min(b.1), a.1.max(b.1));
341	        return p.1 > lo - 1e-9 && p.1 < hi + 1e-9;
342	    }
343	    false
344	}
