63	// is the segment p-q clear of every obstacle's open interior (but `skip`)?
64	pub fn seg_clear(obs: &[Rect], skip: &[usize], p: (f64, f64), q: (f64, f64)) -> bool {
65	    let (x0, x1) = (p.0.min(q.0), p.0.max(q.0));
66	    let (y0, y1) = (p.1.min(q.1), p.1.max(q.1));
67	    for (k, r) in obs.iter().enumerate() {
68	        if skip.contains(&k) {
69	            continue;
70	        }
71	        if (y1 - y0).abs() < EPS {
72	            if y0 > r.y0 + EPS && y0 < r.y1 - EPS && x0 < r.x1 - EPS && x1 > r.x0 + EPS {
73	                return false;
74	            }
75	        } else if x0 > r.x0 + EPS && x0 < r.x1 - EPS && y0 < r.y1 - EPS && y1 > r.y0 + EPS {
76	            return false;
77	        }
78	    }
79	    true
80	}
