82	impl World {
83	    fn own_set(&self, p: &Port) -> Vec<usize> {
84	        match p.own {
85	            Some(k) => (0..self.obs.len()).filter(|&j| self.owner[j] == self.owner[k]).collect(),
86	            None => vec![],
87	        }
88	    }
