90	    // out of a port along its facing, past every own obstacle it meets
91	    pub fn landing(&self, port: &Port) -> (f64, f64) {
92	        let mut p = port.p;
93	        let own = self.own_set(port);
94	        loop {
95	            let mut moved = false;
96	            for &k in &own {
97	                let r = self.obs[k];
98	                let on = match port.d {
99	                    Dir::R | Dir::L => p.1 > r.y0 + EPS && p.1 < r.y1 - EPS && p.0 > r.x0 - EPS && p.0 < r.x1 - EPS,
100	                    Dir::U | Dir::D => p.0 > r.x0 + EPS && p.0 < r.x1 - EPS && p.1 > r.y0 - EPS && p.1 < r.y1 - EPS,
101	                };
102	                if !on {
103	                    continue;
104	                }
105	                let q = match port.d {
106	                    Dir::R => (r.x1, p.1),
107	                    Dir::L => (r.x0, p.1),
108	                    Dir::D => (p.0, r.y1),
109	                    Dir::U => (p.0, r.y0),
110	                };
111	                if (q.0 - p.0).abs() > EPS || (q.1 - p.1).abs() > EPS {
112	                    p = q;
113	                    moved = true;
114	                }
115	            }
116	            if !moved {
117	                break;
118	            }
119	        }
120	        p
121	    }
122	
123	    fn lattice_lines(&self, lo: f64, hi: f64, o: f64) -> Vec<f64> {
124	        let mut v = Vec::new();
125	        let mut k = ((lo - o) / PITCH).ceil();
126	        while k * PITCH + o <= hi + EPS {
127	            v.push(k * PITCH + o);
128	            k += 1.0;
129	        }
130	        v
131	    }
132	
133	    // the cheapest route between two ports: length plus `bend` per bend
134	    pub fn search(&self, a: &Port, b: &Port, bend: f64) -> Option<Vec<(f64, f64)>> {
135	        let la = self.landing(a);
136	        let lb = self.landing(b);
137	        let skip_a = self.own_set(a);
138	        let skip_b = self.own_set(b);
139	        let mut xs = vec![la.0, lb.0];
140	        let mut ys = vec![la.1, lb.1];
141	        let (mut x0, mut y0, mut x1, mut y1) = (la.0.min(lb.0), la.1.min(lb.1), la.0.max(lb.0), la.1.max(lb.1));
142	        for r in &self.obs {
143	            xs.push(r.x0);
144	            xs.push(r.x1);
145	            ys.push(r.y0);
146	            ys.push(r.y1);
147	            x0 = x0.min(r.x0);
148	            y0 = y0.min(r.y0);
149	            x1 = x1.max(r.x1);
150	            y1 = y1.max(r.y1);
151	        }
152	        xs.extend(self.lattice_lines(x0 - 2.0 * PITCH, x1 + 2.0 * PITCH, self.lattice.0));
153	        ys.extend(self.lattice_lines(y0 - 2.0 * PITCH, y1 + 2.0 * PITCH, self.lattice.1));
154	        let xs = uniq(xs);
155	        let ys = uniq(ys);
156	        let nx = xs.len();
157	        let ny = ys.len();
158	        let find = |v: &[f64], x: f64| v.iter().position(|t| (t - x).abs() < 1e-7);
159	        let (sx, sy) = (find(&xs, la.0)?, find(&ys, la.1)?);
160	        let (gx, gy) = (find(&xs, lb.0)?, find(&ys, lb.1)?);
161	        let state = |ix: usize, iy: usize, d: usize| (iy * nx + ix) * 4 + d;
162	        let n = nx * ny * 4;
163	        let mut dist = vec![f64::INFINITY; n];
164	        let mut prev = vec![usize::MAX; n];
165	        let mut heap = BinaryHeap::new();
166	        let mut seq = 0u64;
167	        let start = state(sx, sy, idx(a.d));
168	        dist[start] = 0.0;
169	        heap.push(Item { cost: 0.0, seq, state: start });
170	        let want = idx(b.d.opposite());
171	        let mut best: Option<(f64, usize)> = None;
172	        while let Some(Item { cost, state: st, .. }) = heap.pop() {
173	            if cost > dist[st] + EPS {
174	                continue;
175	            }
176	            if let Some((bc, _)) = best {
177	                if cost > bc + EPS {
178	                    break;
179	                }
180	            }
181	            let d = st % 4;
182	            let cell = st / 4;
183	            let (ix, iy) = (cell % nx, cell / nx);
184	            if ix == gx && iy == gy {
185	                let extra = if b.free {
186	                    if d == (want + 2) % 4 {
187	                        f64::INFINITY
188	                    } else {
189	                        0.0
190	                    }
191	                } else if d == want {
192	                    0.0
193	                } else if (d + 2) % 4 == want {
194	                    f64::INFINITY
195	                } else {
196	                    bend
197	                };
198	                if extra.is_finite() {
199	                    let c = cost + extra;
200	                    if best.map_or(true, |(bc, _)| c < bc - EPS) {
201	                        best = Some((c, st));
202	                    }
203	                }
204	            }
205	            for (k, nd) in DIRS.iter().enumerate() {
206	                if k == (d + 2) % 4 {
207	                    continue;
208	                }
209	                let (jx, jy) = match nd {
210	                    Dir::R if ix + 1 < nx => (ix + 1, iy),
211	                    Dir::L if ix > 0 => (ix - 1, iy),
212	                    Dir::D if iy + 1 < ny => (ix, iy + 1),
213	                    Dir::U if iy > 0 => (ix, iy - 1),
214	                    _ => continue,
215	                };
216	                let p = (xs[ix], ys[iy]);
217	                let q = (xs[jx], ys[jy]);
218	                if !seg_clear(&self.obs, &[], p, q) {
219	                    let mut ok = false;
220	                    if seg_clear(&self.obs, &skip_a, p, q) && on_stub(a, la, p, q) {
221	                        ok = true;
222	                    }
223	                    if seg_clear(&self.obs, &skip_b, p, q) && on_stub(b, lb, p, q) {
224	                        ok = true;
225	                    }
226	                    if !ok {
227	                        continue;
228	                    }
229	                }
230	                let len = (q.0 - p.0).abs() + (q.1 - p.1).abs();
231	                let turn = if k == d || (st == start && a.free) { 0.0 } else { bend };
232	                let nc = cost + len + turn;
233	                let ns = state(jx, jy, k);
234	                if nc < dist[ns] - EPS {
235	                    dist[ns] = nc;
236	                    prev[ns] = st;
237	                    seq += 1;
238	                    heap.push(Item { cost: nc, seq, state: ns });
239	                }
240	            }
241	        }
242	        let (_, mut st) = best?;
243	        let mut cells: Vec<(f64, f64)> = Vec::new();
244	        loop {
245	            let cell = st / 4;
246	            cells.push((xs[cell % nx], ys[cell / nx]));
247	            if prev[st] == usize::MAX {
248	                break;
249	            }
250	            st = prev[st];
251	        }
252	        cells.reverse();
253	        let mut pts = vec![a.p];
254	        pts.extend(cells);
255	        pts.push(b.p);
256	        let mut pts = simplify(&pts);
257	        self.place(&mut pts, la, lb);
258	        Some(simplify(&pts))
259	    }
260	
261	    // the lattice line nearest `m` within [lo, hi] (halves toward the lower),
262	    // else `m`
263	    fn snap_within(&self, m: f64, lo: f64, hi: f64, o: f64) -> f64 {
264	        let k = (((m - o) / PITCH) - 0.5 + 1e-9).ceil();
265	        let near = k * PITCH + o;
266	        let mut cands: Vec<f64> = vec![near, near - PITCH, near + PITCH];
267	        cands.retain(|c| *c >= lo - EPS && *c <= hi + EPS);
268	        cands.sort_by(|a, b| {
269	            let da = (a - m).abs();
270	            let db = (b - m).abs();
271	            da.partial_cmp(&db).unwrap().then(a.partial_cmp(b).unwrap())
272	        });
273	        cands.first().cloned().unwrap_or(m)
274	    }
275	
276	    // segment placement: steps centre in their channel; detours hug, or
277	    // centre between what they go around and what lies beyond
278	    fn place(&self, pts: &mut Vec<(f64, f64)>, la: (f64, f64), lb: (f64, f64)) {
279	        let n = pts.len();
280	        if n < 4 {
281	            return;
282	        }
283	        for k in 1..n - 2 {
284	            let (a, b, c, d) = (pts[k - 1], pts[k], pts[k + 1], pts[k + 2]);
285	            let vert = (b.0 - c.0).abs() < EPS;
286	            let (before, after) = if vert { (b.0 - a.0, d.0 - c.0) } else { (b.1 - a.1, d.1 - c.1) };
287	            let step = before * after > 0.0;
288	            let (s0, s1) = if vert { (b.1.min(c.1), b.1.max(c.1)) } else { (b.0.min(c.0), b.0.max(c.0)) };
289	            let pos = if vert { b.0 } else { b.1 };
290	            let o = if vert { self.lattice.0 } else { self.lattice.1 };
291	            // the free channel across the segment
292	            let mut clo = f64::NEG_INFINITY;
293	            let mut chi = f64::INFINITY;
294	            for r in &self.obs {
295	                let (a0, a1, b0, b1) = if vert { (r.y0, r.y1, r.x0, r.x1) } else { (r.x0, r.x1, r.y0, r.y1) };
296	                if a0 < s1 - EPS && a1 > s0 + EPS {
297	                    if b1 <= pos + EPS && b1 > clo {
298	                        clo = b1;
299	                    }
300	                    if b0 >= pos - EPS && b0 < chi {
301	                        chi = b0;
302	                    }
303	                }
304	            }
305	            // the ports' runs keep their landings
306	            let mut lo = f64::NEG_INFINITY;
307	            let mut hi = f64::INFINITY;
308	            if k == 1 {
309	                let l = if vert { la.0 } else { la.1 };
310	                if before > 0.0 {
311	                    lo = lo.max(l);
312	                } else {
313	                    hi = hi.min(l);
314	                }
315	            }
316	            if k + 2 == n - 1 {
317	                let l = if vert { lb.0 } else { lb.1 };
318	                if after > 0.0 {
319	                    hi = hi.min(l);
320	                } else {
321	                    lo = lo.max(l);
322	                }
323	            }
324	            let m = if step {
325	                // within both neighbours' spans
326	                let (sl, sh) = if vert { (a.0.min(d.0), a.0.max(d.0)) } else { (a.1.min(d.1), a.1.max(d.1)) };
327	                let lo = lo.max(sl).max(clo);
328	                let hi = hi.min(sh).min(chi);
329	                if !lo.is_finite() || !hi.is_finite() || hi < lo - EPS {
330	                    continue;
331	                }
332	                self.snap_within((lo + hi) / 2.0, lo, hi, o)
333	            } else {
334	                // a detour: its neighbours come from the side it goes around
335	                let toward_low = before > 0.0;
336	                let (hug, beyond) = if toward_low { (clo, chi) } else { (chi, clo) };
337	                if !hug.is_finite() {
338	                    continue;
339	                }
340	                // the first lattice line clear of what it goes around
341	                let first = if toward_low {
342	                    (((hug - o) / PITCH) - 1e-9).ceil() * PITCH + o
343	                } else {
344	                    (((hug - o) / PITCH) + 1e-9).floor() * PITCH + o
345	                };
346	                if beyond.is_finite() {
347	                    let (l2, h2) = if toward_low { (hug, beyond) } else { (beyond, hug) };
348	                    if h2 < l2 - EPS {
349	                        continue;
350	                    }
351	                    self.snap_within((l2 + h2) / 2.0, l2.max(lo), h2.min(hi), o)
352	                } else {
353	                    if first < lo - EPS || first > hi + EPS {
354	                        continue;
355	                    }
356	                    first
357	                }
358	            };
359	            if vert {
360	                pts[k].0 = m;
361	                pts[k + 1].0 = m;
362	            } else {
363	                pts[k].1 = m;
364	                pts[k + 1].1 = m;
365	            }
366	        }
367	    }
368	}
369	
370	fn uniq(mut v: Vec<f64>) -> Vec<f64> {
371	    v.retain(|x| x.is_finite());
372	    v.sort_by(|a, b| a.partial_cmp(b).unwrap());
373	    let mut o: Vec<f64> = Vec::new();
374	    for x in v {
375	        if o.last().map_or(true, |l: &f64| (x - *l).abs() > 1e-7) {
376	            o.push(x);
377	        }
378	    }
379	    o
380	}
381	
382	#[derive(PartialEq)]
383	struct Item {
384	    cost: f64,
385	    seq: u64,
386	    state: usize,
387	}
388	impl Eq for Item {}
389	impl PartialOrd for Item {
390	    fn partial_cmp(&self, o: &Self) -> Option<std::cmp::Ordering> {
391	        Some(self.cmp(o))
392	    }
393	}
394	impl Ord for Item {
395	    fn cmp(&self, o: &Self) -> std::cmp::Ordering {
396	        o.cost.partial_cmp(&self.cost).unwrap_or(std::cmp::Ordering::Equal).then(o.seq.cmp(&self.seq))
397	    }
398	}
399	
400	pub fn simplify(pts: &[(f64, f64)]) -> Vec<(f64, f64)> {
401	    let mut o: Vec<(f64, f64)> = Vec::new();
402	    for &p in pts {
403	        if let Some(l) = o.last() {
404	            if (l.0 - p.0).abs() < EPS && (l.1 - p.1).abs() < EPS {
405	                continue;
406	            }
407	        }
408	        o.push(p);
409	    }
410	    let mut k = 1;
411	    while k + 1 < o.len() {
412	        let (a, b, c) = (o[k - 1], o[k], o[k + 1]);
413	        let col = ((a.0 - b.0).abs() < EPS && (b.0 - c.0).abs() < EPS) || ((a.1 - b.1).abs() < EPS && (b.1 - c.1).abs() < EPS);
414	        if col {
415	            o.remove(k);
416	        } else {
417	            k += 1;
418	        }
419	    }
420	    o
421	}
422	
423	fn on_stub(port: &Port, land: (f64, f64), p: (f64, f64), q: (f64, f64)) -> bool {
424	    let within = |t: (f64, f64)| {
425	        let (x0, x1) = (port.p.0.min(land.0), port.p.0.max(land.0));
426	        let (y0, y1) = (port.p.1.min(land.1), port.p.1.max(land.1));
427	        t.0 >= x0 - EPS && t.0 <= x1 + EPS && t.1 >= y0 - EPS && t.1 <= y1 + EPS
428	    };
429	    within(p) && within(q)
430	}
