#!/usr/bin/env python3
# regions.py FILE : per region (schematic group with data-id under the page), are nodes and
# wires (relative to the region's origin) the same between original and mine?
import re, sys, subprocess, os
f = sys.argv[1]
verbose = len(sys.argv) > 2
d = os.path.dirname(os.path.abspath(f)); b = os.path.basename(f)
so = subprocess.run(['/workspace/executable', b], cwd=d, capture_output=True, text=True).stdout
sm = subprocess.run(['/tmp/bin-sch/executable', b], cwd=d, capture_output=True, text=True).stdout

def parse(s):
    regs = {}
    for m in re.finditer(r'<g class="lini-node lini-region[^"]*" data-id="([^"]+)" transform="translate\(([-\d.]+),([-\d.]+)\)">', s):
        regs[m.group(1)] = (float(m.group(2)), float(m.group(3)), m.start())
    # region bodies: text between successive region starts (approx)
    starts = sorted((v[2], k) for k, v in regs.items())
    bodies = {}
    for i, (st, k) in enumerate(starts):
        en = starts[i + 1][0] if i + 1 < len(starts) else s.find('<g class="lini-links"')
        bodies[k] = s[st:en]
    wires = {}
    for m in re.finditer(r'<g class="lini-link lini-schematic-wire" data-from="([^"]+)" data-to="([^"]+)">\s*<path d="([^"]+)"/>(\s*<text[^>]*>[^<]*</text>)?', s):
        r = m.group(1).split('.')[0]
        if r not in regs:
            continue
        ox, oy = regs[r][0], regs[r][1]
        nums = [float(v) for v in re.findall(r'-?[\d.]+', m.group(3))]
        rel = ['%.4f,%.4f' % (nums[i] - ox, nums[i + 1] - oy) for i in range(0, len(nums), 2)]
        wires.setdefault(r, []).append((m.group(1), m.group(2), ' '.join(rel)))
    juncs = {}
    return regs, bodies, wires

ro, bo, wo = parse(so)
rm, bm, wm = parse(sm)
for k in ro:
    nodes_same = bo.get(k) == bm.get(k)
    ws_o = wo.get(k, []); ws_m = wm.get(k, [])
    nsame = sum(1 for a, c in zip(ws_o, ws_m) if a == c)
    print('%-8s nodes %s  wires %d/%d' % (k, 'same' if nodes_same else 'DIFF', nsame, len(ws_o)))
    if verbose:
        for a, c in zip(ws_o, ws_m):
            if a != c:
                print('   O', a)
                print('   M', c)

