178	// parent's frame (geometry alone: strokes aside)
179	pub fn drawn_boxes(ctx: &Ctx, i: usize) -> Vec<([f64; 4], f64)> {
180	    let mut out = Vec::new();
181	    fn go(ctx: &Ctx, i: usize, parent: &[f64; 6], out: &mut Vec<([f64; 4], f64)>, top: bool) {
182	        let n = &ctx.nodes[i];
183	        let m = mul(parent, &crate::render::group_matrix(ctx, i));
184	        let (ow, oh) = (n.w, n.h);
185	        if obstacle(ctx, i, top) && (ow > 0.0 || oh > 0.0) {
186	            let (cx, cy) = (-n.geo_off.0, -n.geo_off.1);
187	            let mut b = [f64::INFINITY, f64::INFINITY, f64::NEG_INFINITY, f64::NEG_INFINITY];
188	            for (px, py) in [(-ow / 2.0, -oh / 2.0), (ow / 2.0, -oh / 2.0), (ow / 2.0, oh / 2.0), (-ow / 2.0, oh / 2.0)] {
189	                let (px, py) = (px + cx, py + cy);
190	                let x = m[0] * px + m[2] * py + m[4];
191	                let y = m[1] * px + m[3] * py + m[5];
192	                b[0] = b[0].min(x);
193	                b[1] = b[1].min(y);
194	                b[2] = b[2].max(x);
