#!/usr/bin/env python3
# lane order on a side with two pins A (top) and B (bottom), each with up/down chains
import subprocess, os, re, sys
d = '/tmp/sch/t5'
os.makedirs(d, exist_ok=True)
cases = {
    't1': ('UD', 'UD'), 't2': ('U', 'U'), 't3': ('D', 'D'), 't4': ('UD', 'U'), 't5': ('UD', 'D'),
    't6': ('U', 'UD'), 't7': ('D', 'UD'), 't8': ('U', 'D'), 't9': ('D', 'U'),
    't10': ('DU', 'DU'), 't11': ('DU', 'UD'), 't12': ('UD', 'DU'),
}
exe = sys.argv[1] if len(sys.argv) > 1 else '/workspace/executable'
for name, (a, b) in cases.items():
    lines = []
    k = 0
    for pin, spec in (('A', a), ('B', b)):
        for ch in spec:
            k += 1
            if ch == 'U':
                lines.append('U1.%s - R%d - |vcc|' % (pin, k))
            else:
                lines.append('U1.%s - R%d - |gnd|' % (pin, k))
    parts = '\n'.join('  |R#R%d| "1k"' % i for i in range(1, k + 1))
    src = '''{
  |s::group| { layout: schematic; }
  |vcc::label| { symbol: power; } [ "VCC" ]
}
|s| [
  |component#U1| [ |pin#A| { side: left; }; |pin#B| { side: left; }; |pin#Z| { side: right; } ]
%s
%s
]
''' % (parts, '\n'.join('  ' + l for l in lines))
    p = os.path.join(d, name + '.lini')
    open(p, 'w').write(src)
    o = subprocess.run([exe, name + '.lini'], cwd=d, capture_output=True, text=True).stdout
    res = []
    for i in range(1, k + 1):
        m = re.search(r'data-id="R%d" transform="translate\(([-\d.]+),([-\d.]+)\)' % i, o)
        res.append('R%d@%s,%s' % (i, m.group(1), m.group(2)))
    print(name, a, b, ' '.join(lines).replace('U1.', ''), '|', ' '.join(res))

