    b: usize,
    pa: super::net::Term,
    pb: super::net::Term,
    // the parts relative to the first one's place on its anchor's side:
    // (x, y off the pin's row, reserved box)
    rel: Vec<(f64, f64, [f64; 4])>,
    // the first part's reach toward its anchor, the last one's away
