#!/usr/bin/env python3
# probe the zero-jog artifact: a part in a lane wired up to a power flag, the
# lane moved around by a spacer anchor of varying width; prints lane x, flag
# text, and whether the original drew a zero jog
import subprocess, os, re, sys
d = '/tmp/sch/t7'
os.makedirs(d, exist_ok=True)
texts = sys.argv[1].split(',') if len(sys.argv) > 1 else ['5V']
res = {}
for text in texts:
    for nsp in range(0, 14):
        for side in ['left', 'right']:
            spacer = '|component#U9| { cell: %d 1; } [ |pin#%s| { side: left; }; |pin#Y| { side: left; }; |pin#Z| { side: right; } ]' % (2 if side == 'right' else 0, 'Q' * (nsp + 1))
            src = '''{
  |s::group| { layout: schematic; }
  |vcc::label| { symbol: power; } [ "%s" ]
}
|s| [
  |component#U1| { cell: 1 1; } [ |pin#A| { side: left; }; |pin#P| { side: right; }; |pin#B| { side: right; } ]
  %s
  |C#C1| "1u"
  U1.P - C1 - |vcc|
]
''' % (text, spacer)
            p = os.path.join(d, 'z.lini')
            open(p, 'w').write(src)
            o = subprocess.run(['/workspace/executable', 'z.lini'], cwd=d, capture_output=True, text=True).stdout
            m = re.search(r'data-from="C1\.p\d" data-to="lini-cap-1">\s*<path d="([^"]+)"', o)
            if not m:
                continue
            pts = re.findall(r'-?[\d.]+', m.group(1))
            x = float(pts[0])
            z = len(pts) == 8
            res.setdefault((text, x), set()).add(z)
for k in sorted(res):
    print(k, res[k])

