#!/usr/bin/env python3
# search float computation orders that reproduce the zero-jog pattern
import re, itertools
data = []
for line in open('/tmp/sch/zdata.txt'):
    m = re.match(r"5V (\S+) (True|False) rect \('([^']+)', '([^']+)', '([^']+)', '([^']+)'\)", line)
    L = float(m.group(1)); z = m.group(2) == 'True'
    rx = float(m.group(3)); W = float(m.group(5))
    data.append((L, z, rx, W))

lw_vals = {'w': 34.986, 'w+': 34.986000000000004}
pad = 20.0
cw = 33.5   # the cap's box (stroke incl)

def candidates():
    for lwn, lw in lw_vals.items():
        h = lw / 2
        # label centre offsets from the lane (local)
        o1s = {
            'h-8.75': h - 8.75,
            'h-0.75-8': (h - 0.75) - 8,
            '-(-h+0.75+8)': -((-h + 0.75) + 8),
            '8.743': 8.743,
        }
        for o1n, o1 in o1s.items():
            # frames: the scope's left edge in svg coords and the content origin
            for fr in ['none', 'rx', 'rx+pad', 'W/2', 'W/2-pad']:
                def to_frame(v, rx, W):
                    if fr == 'none': return v
                    if fr == 'rx': return v - rx
                    if fr == 'rx+pad': return v - (rx + pad)
                    if fr == 'W/2': return v + W / 2
                    if fr == 'W/2-pad': return v + (W / 2 - pad)
                def from_frame(v, rx, W):
                    if fr == 'none': return v
                    if fr == 'rx': return v + rx
                    if fr == 'rx+pad': return v + (rx + pad)
                    if fr == 'W/2': return v - W / 2
                    if fr == 'W/2-pad': return v - (W / 2 - pad)
                # how a label's attach is derived from its stored position
                for att in ['centre', 'left', 'left2']:
                    def attach(Lf, rx, W):
                        c = Lf + o1  # label centre in frame
                        if att == 'centre':
                            return c + ((-h + 0.75) + 8)
                        if att == 'left':
                            left = c - h
                            return (left + 0.75) + 8
                        if att == 'left2':
                            left = c - h
                            return left + 8.75
                    for st in ['centre', 'left']:
                        def station(Lf):
                            if st == 'centre':
                                return Lf
                            return (Lf - cw / 2) + cw / 2
                        yield (lwn, o1n, fr, att, st), (to_frame, from_frame, attach, station)

ok_list = []
for name, (to_frame, from_frame, attach, station) in candidates():
    good = 0
    for (L, z, rx, W) in data:
        Lf = to_frame(L, rx, W)
        a = from_frame(attach(Lf, rx, W), rx, W)
        s = from_frame(station(Lf), rx, W)
        if (a != s) == z:
            good += 1
    ok_list.append((good, name))
ok_list.sort(reverse=True)
for g, n in ok_list[:15]:
    print(g, len(data), n)

