#!/usr/bin/env python3
# in each failing case's output (ours and the original's), count collinear overlapping segments
# between different wires (any net)
import sys, os, subprocess, re
def segs(svg):
    out = []
    for k, m in enumerate(re.finditer(r'<g class="lini-link[^"]*" data-from="([^"]+)" data-to="([^"]+)">\s*<path d="([^"]+)"', svg)):
        nums = [float(v) for v in re.findall(r'-?[\d.]+', m.group(3))]
        pts = list(zip(nums[0::2], nums[1::2]))
        for i in range(1, len(pts)):
            out.append((k, m.group(1), m.group(2), pts[i - 1], pts[i]))
    return out
def overl(S):
    n = 0
    for i in range(len(S)):
        for j in range(i + 1, len(S)):
            a, b = S[i], S[j]
            if a[0] == b[0]:
                continue
            # shared endpoints (same pin) — skip pairs sharing a terminal
            if {a[1], a[2]} & {b[1], b[2]}:
                continue
            (p, q), (r, s) = (a[3], a[4]), (b[3], b[4])
            if abs(p[1] - q[1]) < 1e-6 and abs(r[1] - s[1]) < 1e-6 and abs(p[1] - r[1]) < 1e-6:
                lo, hi = max(min(p[0], q[0]), min(r[0], s[0])), min(max(p[0], q[0]), max(r[0], s[0]))
                if hi - lo > 1e-6: n += 1
            if abs(p[0] - q[0]) < 1e-6 and abs(r[0] - s[0]) < 1e-6 and abs(p[0] - r[0]) < 1e-6:
                lo, hi = max(min(p[1], q[1]), min(r[1], s[1])), min(max(p[1], q[1]), max(r[1], s[1]))
                if hi - lo > 1e-6: n += 1
    return n
tot_o = tot_m = 0
for f in sys.argv[1:]:
    d = os.path.dirname(os.path.abspath(f)); b = os.path.basename(f)
    o = subprocess.run(['/workspace/executable', b], cwd=d, capture_output=True, text=True).stdout
    m = subprocess.run(['/tmp/bin-sch/executable', b], cwd=d, capture_output=True, text=True).stdout
    if o == m:
        continue
    no, nm = overl(segs(o)), overl(segs(m))
    if no or nm:
        print(b, 'orig', no, 'mine', nm)
    tot_o += no; tot_m += nm
print('total orig', tot_o, 'mine', tot_m)

