fn place_label(ctx: &Ctx, pts: &[(f64, f64)], along: f64, text: String, others: &[Vec<(f64, f64)>]) -> (String, f64, f64, f64) {
    let mut total = 0.0;
    for k in 1..pts.len() {
        total += (pts[k].0 - pts[k - 1].0).abs() + (pts[k].1 - pts[k - 1].1).abs();
    }
    let tw = {
