                changed = true;
            }
        }
    }
    let mut out = Vec::new();
    for (i, w) in wires.iter().enumerate() {
        if !inn[i] {
            continue;
        }
        for t in [&w.a, &w.b] {
            if t.kind == Kind::Run && !out.contains(&t.dev) {
                out.push(t.dev);
            }
        }
    }
    out
}

