#!/usr/bin/env python3
# collect stray (impossible) wires from original outputs: the link, the stray path, the warning
import re, os, subprocess, glob, sys
files = sys.argv[1:]
for f in files:
    d = os.path.dirname(os.path.abspath(f)); b = os.path.basename(f)
    r = subprocess.run(['/workspace/executable', b], cwd=d, capture_output=True, text=True)
    o = r.stdout
    if 'lini-stray' not in o:
        continue
    print('==', b)
    for line in r.stderr.splitlines():
        if 'impossible' in line:
            print('  W', line.split('warning: ')[1])
    for m in re.finditer(r'<g class="lini-link[^"]*" data-from="([^"]+)" data-to="([^"]+)">\s*((?:<path[^>]*>\s*)+)', o):
        paths = re.findall(r'<path d="([^"]+)"([^>]*)>', m.group(3))
        if any('lini-stray' in p[1] for p in paths):
            print('  L', m.group(1), '->', m.group(2))
            for dd, attrs in paths:
                print('     ', dd, '|', 'stray' if 'stray' in attrs else '')

