87	fn route_one(ctx: &Ctx, raw_all: &[(super::router::Rect, f64)], owner_all: &[usize], w: &super::net::Wire, lattice: (f64, f64), pass: &[usize]) -> Vec<(f64, f64)> {
88	    // the runs of the wire's own net never block it
89	    let keep: Vec<usize> = (0..owner_all.len()).filter(|&k| !pass.contains(&owner_all[k]) || owner_all[k] == w.a.dev || owner_all[k] == w.b.dev).collect();
90	    let raw: Vec<(super::router::Rect, f64)> = keep.iter().map(|&k| raw_all[k]).collect();
91	    let owner: Vec<usize> = keep.iter().map(|&k| owner_all[k]).collect();
92	    let (raw, owner) = (&raw[..], &owner[..]);
93	    use super::router::Port;
94	    // two pins of one side tied: the U hugging the part, a clearance out
95	    if w.a.kind == Kind::Pin && w.b.kind == Kind::Pin && w.a.dev == w.b.dev && w.a.dir == w.b.dir {
96	        let (pa, pb) = (abs_point(ctx, &w.a), abs_point(ctx, &w.b));
97	        let (vx, vy) = w.a.dir.vec();
98	        let reach = |p: (f64, f64)| p.0 * vx + p.1 * vy;
99	        let out = reach(pa).max(reach(pb)) + CLEAR;
100	        let at = |p: (f64, f64)| -> (f64, f64) {
101	            if w.a.dir.horizontal() {
102	                (out * vx, p.1)
103	            } else {
104	                (p.0, out * vy)
105	            }
106	        };
107	        return vec![pa, at(pa), at(pb), pb];
108	    }
109	    // every box keeps the clearance past its own stroke; a part's own
110	    // drawing keeps the bare clearance from the wires of its stations
111	    let stations: Vec<usize> = [&w.a, &w.b].iter().filter(|t| t.kind == Kind::Station && t.dir.horizontal()).map(|t| t.dev).collect();
112	    let obs: Vec<super::router::Rect> = raw
113	        .iter()
114	        .zip(owner)
115	        .map(|((r, sw), d)| if stations.contains(d) { r.grow(CLEAR) } else { r.grow(CLEAR + sw) })
116	        .collect();
117	    let place_obs: Vec<super::router::Rect> = raw.iter().map(|(r, sw)| r.grow(CLEAR + sw)).collect();
118	    let obs = &obs[..];
119	    let port = |t: &Term| -> (Port, Option<(f64, f64)>) {
120	        let own = owner.iter().position(|&d| d == t.dev);
121	        if t.kind == Kind::Run {
122	            let o = origin_in(ctx, t.dev, 0);
123	            let far = (o.0 + t.off.0, o.1 + t.off.1);
124	            let near = t.through.map(|n| (o.0 + n.0, o.1 + n.1)).unwrap_or(far);
125	            // the wire joins the run at its first lattice line in from the
126	            // near end
127	            let join = |n: f64, f: f64, o: f64| -> f64 {
128	                let k = (n - o) / 20.0;
129	                let j = if f < n { (k + 1e-9).floor() } else { (k - 1e-9).ceil() } * 20.0 + o;
130	                if (j - n).abs() <= (f - n).abs() + 1e-9 {
131	                    j
132	                } else {
133	                    n
134	                }
135	            };
136	            let p = if (near.0 - far.0).abs() < 1e-9 {
137	                (near.0, join(near.1, far.1, lattice.1))
138	            } else {
139	                (join(near.0, far.0, lattice.0), near.1)
140	            };
141	            return (Port { p, d: t.dir, own, free: true, station: false }, Some(far));
142	        }
143	        (Port { p: abs_point(ctx, t), d: t.dir, own, free: false, station: t.kind == Kind::Station && t.dir.horizontal() }, None)
144	    };
145	    let (mut pa, fa) = port(&w.a);
146	    let (mut pb, fb) = port(&w.b);
147	    let drop: Vec<usize> = Vec::new();
148	    let mut obs2: Vec<super::router::Rect> = Vec::new();
149	    let mut own2: Vec<usize> = Vec::new();
150	    let mut remap: Vec<Option<usize>> = Vec::new();
151	    for (k, r) in obs.iter().enumerate() {
152	        if drop.contains(&owner[k]) {
153	            remap.push(None);
154	        } else {
155	            remap.push(Some(obs2.len()));
156	            obs2.push(*r);
157	            own2.push(owner[k]);
158	        }
159	    }
160	    for p in [&mut pa, &mut pb] {
161	        p.own = p.own.and_then(|k| remap[k]);
162	    }
163	    if std::env::var("LINI_SCH_DBG").is_ok() {
164	        eprintln!("route {:?} -> {:?}", pa, pb);
165	        for (k, r) in obs2.iter().enumerate() {
166	            eprintln!("  ob {} {:?}", k, r);
167	        }
168	    }
169	    let world = super::router::World { obs: obs2, place_obs, owner: own2, lattice };
170	    let (la, lb) = (world.landing(&pa), world.landing(&pb));
171	    let mut pts = match world.search(&pa, &pb, 2.0 * CLEAR) {
172	        Some(p) => p,
173	        None => direct(pa.p, pa.d, pb.p, pb.d).unwrap_or_else(|| vec![pa.p, pb.p]),
