68	// is the segment p-q clear of every obstacle's open interior (but `skip`)?
69	pub fn seg_clear(obs: &[Rect], skip: &[usize], p: (f64, f64), q: (f64, f64)) -> bool {
70	    let (x0, x1) = (p.0.min(q.0), p.0.max(q.0));
71	    let (y0, y1) = (p.1.min(q.1), p.1.max(q.1));
72	    for (k, r) in obs.iter().enumerate() {
73	        if skip.contains(&k) {
74	            continue;
75	        }
76	        if (y1 - y0).abs() < EPS {
77	            if y0 > r.y0 + EPS && y0 < r.y1 - EPS && x0 < r.x1 - EPS && x1 > r.x0 + EPS {
78	                return false;
79	            }
80	        } else if x0 > r.x0 + EPS && x0 < r.x1 - EPS && y0 < r.y1 - EPS && y1 > r.y0 + EPS {
81	            return false;
82	        }
83	    }
84	    true
85	}
