87	impl World {
88	    fn own_set(&self, p: &Port) -> Vec<usize> {
89	        match p.own {
90	            Some(k) => (0..self.obs.len()).filter(|&j| self.owner[j] == self.owner[k]).collect(),
91	            None => vec![],
92	        }
93	    }
