95	    // out of a port along its facing, past every own obstacle it meets (a
96	    // free port is entered where it lies)
97	    pub fn landing(&self, port: &Port) -> (f64, f64) {
98	        let mut p = port.p;
99	        if port.free {
100	            return p;
101	        }
102	        let own = self.own_set(port);
103	        loop {
104	            let mut moved = false;
105	            for &k in &own {
106	                let r = self.obs[k];
107	                let on = match port.d {
108	                    Dir::R | Dir::L => p.1 > r.y0 + EPS && p.1 < r.y1 - EPS && p.0 > r.x0 - EPS && p.0 < r.x1 - EPS,
109	                    Dir::U | Dir::D => p.0 > r.x0 + EPS && p.0 < r.x1 - EPS && p.1 > r.y0 - EPS && p.1 < r.y1 - EPS,
110	                };
111	                if !on {
112	                    continue;
113	                }
114	                let q = match port.d {
115	                    Dir::R => (r.x1, p.1),
116	                    Dir::L => (r.x0, p.1),
117	                    Dir::D => (p.0, r.y1),
118	                    Dir::U => (p.0, r.y0),
119	                };
120	                if (q.0 - p.0).abs() > EPS || (q.1 - p.1).abs() > EPS {
121	                    p = q;
122	                    moved = true;
123	                }
124	            }
125	            if !moved {
126	                break;
127	            }
128	        }
129	        p
130	    }
