132	    fn lattice_lines(&self, lo: f64, hi: f64, o: f64) -> Vec<f64> {
133	        let mut v = Vec::new();
134	        let mut k = ((lo - o) / PITCH).ceil();
135	        while k * PITCH + o <= hi + EPS {
136	            v.push(k * PITCH + o);
137	            k += 1.0;
138	        }
139	        v
140	    }
