142	    // the cheapest route between two ports: length plus `bend` per bend
143	    pub fn search(&self, a: &Port, b: &Port, bend: f64) -> Option<Vec<(f64, f64)>> {
144	        let la = self.landing(a);
145	        let lb = self.landing(b);
146	        let skip_a = self.own_set(a);
147	        let skip_b = self.own_set(b);
148	        let mut xs = vec![la.0, lb.0];
149	        let mut ys = vec![la.1, lb.1];
150	        let (mut x0, mut y0, mut x1, mut y1) = (la.0.min(lb.0), la.1.min(lb.1), la.0.max(lb.0), la.1.max(lb.1));
151	        for r in &self.obs {
152	            xs.push(r.x0);
153	            xs.push(r.x1);
154	            ys.push(r.y0);
155	            ys.push(r.y1);
156	            x0 = x0.min(r.x0);
157	            y0 = y0.min(r.y0);
158	            x1 = x1.max(r.x1);
159	            y1 = y1.max(r.y1);
160	        }
161	        xs.extend(self.lattice_lines(x0 - 2.0 * PITCH, x1 + 2.0 * PITCH, self.lattice.0));
162	        ys.extend(self.lattice_lines(y0 - 2.0 * PITCH, y1 + 2.0 * PITCH, self.lattice.1));
163	        let xs = uniq(xs);
164	        let ys = uniq(ys);
165	        let nx = xs.len();
166	        let ny = ys.len();
167	        let find = |v: &[f64], x: f64| v.iter().position(|t| (t - x).abs() < 1e-7);
168	        let (sx, sy) = (find(&xs, la.0)?, find(&ys, la.1)?);
169	        let (gx, gy) = (find(&xs, lb.0)?, find(&ys, lb.1)?);
170	        let state = |ix: usize, iy: usize, d: usize| (iy * nx + ix) * 4 + d;
171	        let n = nx * ny * 4;
172	        let mut dist = vec![f64::INFINITY; n];
173	        let mut prev = vec![usize::MAX; n];
174	        let mut heap = BinaryHeap::new();
175	        let mut seq = 0u64;
176	        let start = state(sx, sy, idx(a.d));
177	        dist[start] = 0.0;
178	        heap.push(Item { cost: 0.0, seq, state: start });
179	        let want = idx(b.d.opposite());
180	        let order: Vec<Dir> = match std::env::var("LINI_SCH_DIRS") {
181	            Ok(v) => v
182	                .chars()
183	                .filter_map(|c| match c {
184	                    'L' => Some(Dir::L),
185	                    'R' => Some(Dir::R),
186	                    'U' => Some(Dir::U),
187	                    'D' => Some(Dir::D),
188	                    _ => None,
189	                })
190	                .collect(),
191	            Err(_) => DIRS.to_vec(),
192	        };
193	        let mut best: Option<(f64, usize)> = None;
194	        while let Some(Item { cost, state: st, .. }) = heap.pop() {
195	            if cost > dist[st] + EPS {
196	                continue;
197	            }
198	            if let Some((bc, _)) = best {
199	                if cost > bc + EPS {
200	                    break;
201	                }
202	            }
203	            let d = st % 4;
204	            let cell = st / 4;
205	            let (ix, iy) = (cell % nx, cell / nx);
206	            if ix == gx && iy == gy {
207	                let extra = if b.free {
208	                    if d == (want + 2) % 4 {
209	                        f64::INFINITY
210	                    } else {
211	                        0.0
212	                    }
213	                } else if d == want {
214	                    0.0
215	                } else if (d + 2) % 4 == want {
216	                    f64::INFINITY
217	                } else {
218	                    bend
219	                };
220	                if extra.is_finite() {
221	                    let c = cost + extra;
222	                    if best.map_or(true, |(bc, _)| c < bc - EPS) {
223	                        best = Some((c, st));
224	                    }
225	                }
226	            }
227	            for nd in order.iter() {
228	                let k = idx(*nd);
229	                if k == (d + 2) % 4 {
230	                    continue;
231	                }
232	                let (jx, jy) = match nd {
233	                    Dir::R if ix + 1 < nx => (ix + 1, iy),
234	                    Dir::L if ix > 0 => (ix - 1, iy),
235	                    Dir::D if iy + 1 < ny => (ix, iy + 1),
236	                    Dir::U if iy > 0 => (ix, iy - 1),
237	                    _ => continue,
238	                };
239	                let p = (xs[ix], ys[iy]);
240	                let q = (xs[jx], ys[jy]);
241	                if !seg_clear(&self.obs, &[], p, q) {
242	                    let mut ok = false;
243	                    if seg_clear(&self.obs, &skip_a, p, q) && on_stub(a, la, p, q) {
244	                        ok = true;
245	                    }
246	                    if seg_clear(&self.obs, &skip_b, p, q) && on_stub(b, lb, p, q) {
247	                        ok = true;
248	                    }
249	                    // a free port is reached along its own lines through
250	                    // what it owns
251	                    for (port, skip) in [(a, &skip_a), (b, &skip_b)] {
252	                        if port.free && seg_clear(&self.obs, skip, p, q) {
253	                            let along = if (p.1 - q.1).abs() < EPS { (p.1 - port.p.1).abs() < EPS } else { (p.0 - port.p.0).abs() < EPS };
