270	                    seq += 1;
271	                    heap.push(Item { cost: nc, seq, state: ns });
272	                }
273	            }
274	        }
275	        let (_, mut st) = best?;
276	        let mut cells: Vec<(f64, f64)> = Vec::new();
277	        loop {
278	            let cell = st / 4;
279	            cells.push((xs[cell % nx], ys[cell / nx]));
280	            if prev[st] == usize::MAX {
281	                break;
282	            }
283	            st = prev[st];
284	        }
285	        cells.reverse();
286	        let mut pts = vec![a.p];
287	        pts.extend(cells);
288	        pts.push(b.p);
289	        let mut pts = simplify(&pts);
290	        if std::env::var("LINI_SCH_DBG").is_ok() {
291	            eprintln!("  raw path {:?} cost {:?}", pts, best.map(|b| b.0));
292	        }
293	        self.place(&mut pts, la, lb, a.station, b.station);
294	        Some(simplify(&pts))
295	    }
