297	    // the lattice line nearest `m` within [lo, hi] (halves toward the lower),
298	    // else `m`
299	    fn snap_within(&self, m: f64, lo: f64, hi: f64, o: f64) -> f64 {
300	        let k = (((m - o) / PITCH) - 0.5 + 1e-9).ceil();
301	        let near = k * PITCH + o;
302	        let mut cands: Vec<f64> = vec![near, near - PITCH, near + PITCH];
303	        cands.retain(|c| *c >= lo - EPS && *c <= hi + EPS);
304	        cands.sort_by(|a, b| {
305	            let da = (a - m).abs();
306	            let db = (b - m).abs();
307	            da.partial_cmp(&db).unwrap().then(a.partial_cmp(b).unwrap())
308	        });
309	        cands.first().cloned().unwrap_or(m)
310	    }
