312	    // segment placement: steps centre in their channel; detours hug, or
313	    // centre between what they go around and what lies beyond
314	    fn place(&self, pts: &mut Vec<(f64, f64)>, la: (f64, f64), lb: (f64, f64), sa: bool, sb: bool) {
315	        let n = pts.len();
316	        if n < 4 {
317	            return;
318	        }
319	        for k in 1..n - 2 {
320	            let (a, b, c, d) = (pts[k - 1], pts[k], pts[k + 1], pts[k + 2]);
321	            let vert = (b.0 - c.0).abs() < EPS;
322	            let (before, after) = if vert { (b.0 - a.0, d.0 - c.0) } else { (b.1 - a.1, d.1 - c.1) };
323	            let step = before * after > 0.0;
324	            let (s0, s1) = if vert { (b.1.min(c.1), b.1.max(c.1)) } else { (b.0.min(c.0), b.0.max(c.0)) };
325	            let pos = if vert { b.0 } else { b.1 };
326	            let o = if vert { self.lattice.0 } else { self.lattice.1 };
327	            // the free channel across the segment
328	            let mut clo = f64::NEG_INFINITY;
329	            let mut chi = f64::INFINITY;
330	            for r in &self.place_obs {
331	                let (a0, a1, b0, b1) = if vert { (r.y0, r.y1, r.x0, r.x1) } else { (r.x0, r.x1, r.y0, r.y1) };
