419	fn uniq(mut v: Vec<f64>) -> Vec<f64> {
420	    v.retain(|x| x.is_finite());
421	    v.sort_by(|a, b| a.partial_cmp(b).unwrap());
422	    let mut o: Vec<f64> = Vec::new();
423	    for x in v {
424	        if o.last().map_or(true, |l: &f64| (x - *l).abs() > 1e-7) {
425	            o.push(x);
426	        }
427	    }
428	    o
429	}
430	
431	#[derive(PartialEq)]
432	struct Item {
433	    cost: f64,
434	    seq: u64,
435	    state: usize,
436	}
437	impl Eq for Item {}
438	impl PartialOrd for Item {
439	    fn partial_cmp(&self, o: &Self) -> Option<std::cmp::Ordering> {
440	        Some(self.cmp(o))
441	    }
442	}
443	impl Ord for Item {
444	    fn cmp(&self, o: &Self) -> std::cmp::Ordering {
445	        // costs equal to a millionth tie, the earlier found first
446	        let q = |c: f64| (c * 1e6).round() as i64;
447	        q(o.cost).cmp(&q(self.cost)).then(o.seq.cmp(&self.seq))
448	    }
449	}
