451	pub fn simplify(pts: &[(f64, f64)]) -> Vec<(f64, f64)> {
452	    let mut o: Vec<(f64, f64)> = Vec::new();
453	    for &p in pts {
454	        if let Some(l) = o.last() {
455	            if (l.0 - p.0).abs() < EPS && (l.1 - p.1).abs() < EPS {
456	                continue;
457	            }
458	        }
459	        o.push(p);
460	    }
461	    let mut k = 1;
462	    while k + 1 < o.len() {
463	        let (a, b, c) = (o[k - 1], o[k], o[k + 1]);
464	        let col = ((a.0 - b.0).abs() < EPS && (b.0 - c.0).abs() < EPS) || ((a.1 - b.1).abs() < EPS && (b.1 - c.1).abs() < EPS);
465	        if col {
466	            o.remove(k);
467	        } else {
468	            k += 1;
469	        }
470	    }
471	    o
472	}
473	
474	fn on_stub(port: &Port, land: (f64, f64), p: (f64, f64), q: (f64, f64)) -> bool {
475	    let within = |t: (f64, f64)| {
476	        let (x0, x1) = (port.p.0.min(land.0), port.p.0.max(land.0));
477	        let (y0, y1) = (port.p.1.min(land.1), port.p.1.max(land.1));
478	        t.0 >= x0 - EPS && t.0 <= x1 + EPS && t.1 >= y0 - EPS && t.1 <= y1 + EPS
479	    };
480	    within(p) && within(q)
481	}
