843	    use super::net::{Dir, Kind};
844	    let cells: Vec<(usize, usize, usize)> = anchor_cells(ctx, anchors).into_iter().zip(anchors).map(|((c, r), &k)| (k, c, r)).collect();
845	    // collapse empty tracks
846	    let mut cols: Vec<usize> = cells.iter().map(|c| c.1).collect();
847	    cols.sort();
848	    cols.dedup();
849	    let mut rows: Vec<usize> = cells.iter().map(|c| c.2).collect();
850	    rows.sort();
851	    rows.dedup();
852	    let exts: Vec<[f64; 4]> = reach.to_vec();
853	    let col_of = |c: usize| cols.iter().position(|&x| x == c).unwrap();
854	    let row_of = |r: usize| rows.iter().position(|&x| x == r).unwrap();
855	    // wires straight across a gap: the pitch keeps a pitch per wire, and the
856	    // first wire between two anchors lines their pins up (the anchor whose
857	    // pin sits nearer the low end steps toward the other's)
858	    let mut shift = vec![(0.0f64, 0.0f64); anchors.len()];
859	    let mut col_wires = vec![0usize; cols.len()];
860	    let mut row_wires = vec![0usize; rows.len()];
861	    let mut paired: Vec<(usize, usize)> = Vec::new();
862	    for w in wires {
863	        let at = |dev: usize| anchors.iter().position(|&a| a == dev);
864	        let (ia, ib) = match (at(w.a.dev), at(w.b.dev)) {
865	            (Some(a), Some(b)) if a != b => (a, b),
866	            _ => continue,
867	        };
868	        if !matches!(w.a.kind, Kind::Pin | Kind::Station) || !matches!(w.b.kind, Kind::Pin | Kind::Station) {
869	            continue;
870	        }
871	        let (ca, ra) = (col_of(cells[ia].1), row_of(cells[ia].2));
872	        let (cb, rb) = (col_of(cells[ib].1), row_of(cells[ib].2));
873	        if ra == rb && ca.abs_diff(cb) == 1 {
874	            let (l, r, tl, tr) = if ca < cb { (ia, ib, &w.a, &w.b) } else { (ib, ia, &w.b, &w.a) };
875	            col_wires[ca.max(cb)] += 1;
876	            if tl.dir == Dir::R && tr.dir == Dir::L {
877	                if !paired.contains(&(l, r)) {
878	                    paired.push((l, r));
879	                    let (yl, yr) = (shift[l].1 + tl.off.1, shift[r].1 + tr.off.1);
880	                    if yl < yr {
881	                        shift[l].1 += yr - yl;
882	                    } else {
883	                        shift[r].1 += yl - yr;
884	                    }
885	                }
886	            }
887	        } else if ca == cb && ra.abs_diff(rb) == 1 {
