920	                shift[b.a].1 += yb - ya;
921	            } else {
922	                shift[b.b].1 += ya - yb;
923	            }
924	        }
925	    }
926	    let mut left = vec![0.0f64; cols.len()];
927	    let mut right = vec![0.0f64; cols.len()];
928	    let mut top = vec![0.0f64; rows.len()];
929	    let mut bottom = vec![0.0f64; rows.len()];
930	    for (k, c) in cells.iter().enumerate() {
