997	    a: usize,
998	    b: usize,
999	    pa: super::net::Term,
1000	    pb: super::net::Term,
1001	    // the parts relative to the first one's place on its anchor's side:
1002	    // (x, y off the pin's row, reserved box)
1003	    rel: Vec<(f64, f64, [f64; 4])>,
1004	    // the first part's reach toward its anchor, the last one's away
1005	    h_first: f64,
1006	    h_last: f64,
1007	    // the last part's centre from the first's
1008	    span: f64,
1009	    // the first part's centre from its anchor (set by the grid)
1010	    first: f64,
1011	    used: bool,
1012	    seats: Vec<(f64, f64, [f64; 4])>,
1013	}
