1015	fn bridge_spans(ctx: &Ctx, anchors: &[usize], b: &Bridge) -> bool {
1016	    let cells = anchor_cells(ctx, anchors);
1017	    let (ca, ra) = cells[b.a];
1018	    let (cb, rb) = cells[b.b];
1019	    let mut cols: Vec<usize> = cells.iter().map(|c| c.0).collect();
1020	    cols.sort();
1021	    cols.dedup();
1022	    let ia = cols.iter().position(|&c| c == ca).unwrap_or(0);
1023	    let ib = cols.iter().position(|&c| c == cb).unwrap_or(0);
1024	    if ra != rb || ia.abs_diff(ib) != 1 {
1025	        return false;
1026	    }
1027	    use super::net::Dir;
1028	    if ia < ib {
1029	        b.pa.dir == Dir::R && b.pb.dir == Dir::L
1030	    } else {
1031	        b.pa.dir == Dir::L && b.pb.dir == Dir::R
1032	    }
1033	}
1034	
1035	// chains of two-pin parts from one anchor's pin to another anchor's, in
1036	// statement order
1037	pub fn find_bridges(ctx: &Ctx, anchors: &[usize], wires: &[super::net::Wire]) -> Vec<Bridge> {
1038	    use super::net::Kind;
1039	    let mut out: Vec<Bridge> = Vec::new();
1040	    let at = |dev: usize| anchors.iter().position(|&a| a == dev);
1041	    let pinlike = |t: &super::net::Term| matches!(t.kind, Kind::Pin | Kind::Station);
1042	    for w in wires {
1043	        for (p, q) in [(&w.a, &w.b), (&w.b, &w.a)] {
1044	            let ia = match at(p.dev) {
1045	                Some(k) if pinlike(p) => k,
1046	                _ => continue,
1047	            };
1048	            if at(q.dev).is_some() || q.kind != Kind::Station || pin_count(ctx, q.dev) != 2 {
1049	                continue;
1050	            }
1051	            if out.iter().any(|b| b.parts.iter().any(|x| x.0 == q.dev)) {
1052	                continue;
1053	            }
1054	            // walk the chain
1055	            let mut parts: Vec<(usize, super::net::Term)> = vec![(q.dev, q.clone())];
1056	            let mut cur = q.clone();
1057	            let mut end: Option<(usize, super::net::Term)> = None;
1058	            for _ in 0..32 {
1059	                let exit = match super::seat::exit_of(ctx, &cur) {
1060	                    Some(e) => e,
1061	                    None => break,
1062	                };
1063	                let mut next: Option<super::net::Term> = None;
1064	                for w2 in wires {
1065	                    for (u, v) in [(&w2.a, &w2.b), (&w2.b, &w2.a)] {
1066	                        if u.node == exit.node && v.dev != cur.dev && next.is_none() {
1067	                            next = Some(v.clone());
1068	                        }
1069	                    }
1070	                }
1071	                let n = match next {
1072	                    Some(n) => n,
1073	                    None => break,
1074	                };
1075	                if let Some(ib) = at(n.dev) {
1076	                    if pinlike(&n) && ib != ia {
1077	                        end = Some((ib, n));
1078	                    }
1079	                    break;
1080	                }
1081	                if n.kind != Kind::Station || pin_count(ctx, n.dev) != 2 || parts.iter().any(|x| x.0 == n.dev) {
1082	                    break;
1083	                }
1084	                parts.push((n.dev, n.clone()));
1085	                cur = n;
1086	            }
1087	            if let Some((ib, pb)) = end {
1088	                out.push(Bridge { a: ia, b: ib, pa: p.clone(), pb, parts });
1089	            }
1090	        }
1091	    }
1092	    out
1093	}
1094	
1095	// a bridge's parts laid along its first pin's facing, each clear of the one
1096	// before by a pitch; toward the anchors a part keeps the gap margin
1097	fn plan_bridge(ctx: &Ctx, b: &Bridge, margin: f64) -> BridgePlan {
1098	    let d = b.pa.dir;
1099	    let sg = if d == super::net::Dir::R || d == super::net::Dir::D { 1.0 } else { -1.0 };
1100	    let mut rel: Vec<(f64, f64, [f64; 4])> = Vec::new();
1101	    let mut h_first = 0.0;
1102	    let mut h_last = 0.0;
1103	    let mut prev_far: Option<f64> = None;
1104	    let mut first_x = 0.0;
1105	    let mut last_x = 0.0;
1106	    for (k, (dev, entry)) in b.parts.iter().enumerate() {
1107	        let body = super::seat::body(ctx, *dev);
1108	        // the reach behind and ahead of the centre along the facing
1109	        let (behind, ahead) = if sg > 0.0 { (-body[0], body[2]) } else { (body[2], -body[0]) };
1110	        let x = match prev_far {
1111	            None => 0.0,
1112	            Some(f) => sg * crate::schematic::place::ceil_lattice(sg * f + PITCH + behind),
1113	        };
1114	        let x = if k == 0 { 0.0 } else { x };
1115	        let hb = margin;
1116	        let ha = margin;
1117	        if k == 0 {
1118	            h_first = hb;
1119	            first_x = x;
1120	        }
1121	        h_last = ha;
1122	        last_x = x;
1123	        let y = -entry.off.1;
1124	        let (cy0, cy1) = (y - super::seat::cell_half(-body[1]), y + super::seat::cell_half(body[3]));
1125	        let res = [x - if sg > 0.0 { hb } else { ha }, cy0, x + if sg > 0.0 { ha } else { hb }, cy1];
1126	        rel.push((x, y, res));
1127	        prev_far = Some(x + sg * ahead);
1128	    }
1129	    BridgePlan {
1130	        a: b.a,
1131	        b: b.b,
1132	        pa: b.pa.clone(),
1133	        pb: b.pb.clone(),
1134	        rel,
1135	        h_first,
1136	        h_last,
1137	        span: (last_x - first_x).abs(),
1138	        first: 0.0,
1139	        used: false,
1140	        seats: Vec::new(),
1141	    }
1142	}

