1	// The wires' SVG: each wire a `lini-link` group with its path and net name,
2	// the junction dots after them; and their stylesheet rules. A root
3	// schematic restyles the links themselves; a schematic nested in another
4	// layout marks its wires `lini-schematic-wire`.
5	
6	use super::wire::WIRING;
7	use crate::compile::Ctx;
8	use crate::render::Out;
9	use crate::style::use_var;
10	use crate::util::{f4, xml_escape};
11	
12	pub fn reset() {
13	    super::wire::reset();
14	    super::place::reset();
15	}
16	
17	fn label_width(ctx: &Ctx, text: &str) -> f64 {
18	    let fam = crate::font::Family::Sans;
19	    let w = if ctx.comp[0].layout == "schematic" { ctx.comp[0].font_weight } else { 400 };
20	    crate::font::text_width(fam, w, 11.0, text)
21	}
22	
23	pub fn extend_bbox(ctx: &Ctx, b: &mut [f64; 4]) {
24	    WIRING.with(|w| {
25	        let w = w.borrow();
26	        for r in &w.wires {
27	            for &(x, y) in &r.pts {
28	                b[0] = b[0].min(x);
29	                b[1] = b[1].min(y);
30	                b[2] = b[2].max(x);
31	                b[3] = b[3].max(y);
32	            }
33	            for (t, x, y, rot) in &r.labels {
34	                let tw = label_width(ctx, t);
35	                let (hw, hh) = if *rot != 0.0 { (5.5, tw / 2.0) } else { (tw / 2.0, 5.5) };
36	                b[0] = b[0].min(x - hw);
37	                b[1] = b[1].min(y - hh);
38	                b[2] = b[2].max(x + hw);
39	                b[3] = b[3].max(y + hh);
40	            }
41	        }
42	    });
43	}
44	
45	// the schematic wires and junctions inside the links layer ("" when none)
46	pub fn render_links(ctx: &Ctx, out: &mut Out) -> Result<String, crate::diag::Diag> {
47	    super::sheet_vars(&mut out.vars);
48	    let mut s = String::new();
49	    WIRING.with(|w| {
50	        let w = w.borrow();
51	        if w.wires.is_empty() {
52	            return;
53	        }
54	        let root = ctx.comp[0].layout == "schematic";
55	        let mut any_label = false;
56	        for r in &w.wires {
57	            let l = &ctx.links[r.li];
58	            let cls = if root { "lini-link".to_string() } else { "lini-link lini-schematic-wire".to_string() };
59	            s.push_str(&format!(
60	                "    <g class=\"{}\" data-from=\"{}\" data-to=\"{}\">\n",
61	                cls,
62	                xml_escape(&crate::links::path_of(ctx, l.from)),
63	                xml_escape(&crate::links::path_of(ctx, l.to))
64	            ));
65	            let mut d = String::new();
66	            for (k, &(x, y)) in r.pts.iter().enumerate() {
67	                if k > 0 {
68	                    d.push(' ');
69	                }
70	                d.push_str(&format!("{} {} {}", if k == 0 { "M" } else { "L" }, f4(x), f4(y)));
71	            }
72	            s.push_str(&format!("      <path d=\"{}\"/>\n", d));
73	            for (t, x, y, rot) in &r.labels {
74	                any_label = true;
75	                let style = if root {
76	                    String::new()
77	                } else {
78	                    " style=\"fill: var(--lini-label-ink); font-weight: var(--lini-font-weight)\"".to_string()
79	                };
80	                let turn = if *rot != 0.0 { format!(" transform=\"rotate({} {} {})\"", f4(*rot), f4(*x), f4(*y)) } else { String::new() };
81	                s.push_str(&format!(
82	                    "      <text class=\"lini-link-label\" x=\"{}\" y=\"{}\" dy=\"0.358em\"{}{}>{}</text>\n",
83	                    f4(*x),
84	                    f4(*y),
85	                    style,
86	                    turn,
87	                    xml_escape(t)
88	                ));
89	            }
90	            s.push_str("    </g>\n");
91	        }
92	        for &(x, y) in &w.junctions {
93	            s.push_str(&format!("    <g class=\"lini-node lini-junction lini-oval\" transform=\"translate({},{})\">\n", f4(x), f4(y)));
94	            s.push_str("      <ellipse cx=\"0\" cy=\"0\" rx=\"4\" ry=\"4\"/>\n");
95	            s.push_str("    </g>\n");
96	        }
97	        // the stylesheet
98	        if root {
99	            out.extra_rules.push((
100	                "link".into(),
101	                ".lini-link { fill: none; stroke: var(--lini-wire); stroke-width: 1.5; stroke-dasharray: none; }".to_string(),
102	            ));
103	            // the root's link rule names the net-name ink whether or not a name is drawn
104	            use_var(&mut out.vars, "wire");
105	            use_var(&mut out.vars, "label-ink");
106	            if any_label {
107	                out.extra_rules.push((
108	                    "link-label".into(),
109	                    ".lini-link-label { fill: var(--lini-label-ink); stroke: none; text-anchor: middle; font-size: 11px; font-weight: var(--lini-font-weight); }"
110	                        .to_string(),
111	                ));
112	                use_var(&mut out.vars, "label-ink");
113	            }
114	        } else {
115	            out.extra_rules.push((
116	                "link".into(),
117	                ".lini-link { fill: none; stroke: var(--lini-stroke); stroke-width: 2; stroke-dasharray: none; }".to_string(),
118	            ));
119	            use_var(&mut out.vars, "stroke");
120	            use_var(&mut out.vars, "label-ink");
121	            if any_label {
122	                out.extra_rules.push((
123	                    "link-label".into(),
124	                    ".lini-link-label { fill: currentColor; stroke: none; text-anchor: middle; font-size: 11px; font-weight: var(--lini-link-font-weight); }"
125	                        .to_string(),
126	                ));
127	                use_var(&mut out.vars, "link-font-weight");
128	                use_var(&mut out.vars, "label-ink");
129	            }
130	            out.extra_rules.push((
131	                "schematic-wire".into(),
132	                ".lini-links .lini-schematic-wire { stroke: var(--lini-wire); stroke-width: 1.5; }".to_string(),
133	            ));
134	            use_var(&mut out.vars, "wire");
135	        }
136	        if !w.junctions.is_empty() {
137	            out.extra_rules.push(("oval".into(), ".lini-oval { stroke-dasharray: none; }".to_string()));
138	            out.extra_rules.push(("junction".into(), ".lini-junction { fill: var(--lini-wire); stroke: none; }".to_string()));
139	            use_var(&mut out.vars, "wire");
140	        }
141	    });
142	    Ok(s)
143	}
