129	pub fn pose_of(ctx: &Ctx, i: usize) -> (u32, Option<char>) {
130	    let mut rot = 0;
131	    let mut mirror = None;
132	    for c in &ctx.nodes[i].chain {
133	        if let Some(r) = c.strip_prefix("pose-") {
134	            rot = r.parse().unwrap_or(0);
135	        }
136	        if let Some(m) = c.strip_prefix("mirror-") {
137	            mirror = m.chars().next();
138	        }
139	    }
140	    (rot, mirror)
141	}
