192	// a label's connection point (label-local) and the way its wire leaves
193	fn label_term(ctx: &Ctx, l: usize) -> Option<(Kind, (f64, f64), Dir, Option<(f64, f64)>)> {
194	    let (rot, mirror) = pose_of(ctx, l);
195	    let n = &ctx.nodes[l];
196	    let w = n.w;
197	    if has(ctx, l, "net-run") || has(ctx, l, "net-run-turned") {
198	        // pose 0: the wire comes in from the right and runs to the left end
199	        let (fx, fy) = map_vec(-1.0, 0.0, rot, mirror);
200	        let len = if has(ctx, l, "net-run-turned") { n.h } else { w };
201	        let far = (fx * len / 2.0, fy * len / 2.0);
202	        let near = (-far.0, -far.1);
203	        let dir = Dir::of_vec(-fx, -fy);
204	        return Some((Kind::Run, far, dir, Some(near)));
205	    }
206	    // a tag attaches by whichever end faces its wire (resolved when seated
207	    // and routed): its two ends here
208	    if has(ctx, l, "tag-flag-right") || has(ctx, l, "tag-flag-left") || has(ctx, l, "tag-flag-both") || has(ctx, l, "tag-outline") {
209	        let hw = tag_half(ctx, l).0;
210	        return Some((Kind::Flag, (-hw, 0.0), Dir::L, Some((hw, 0.0))));
211	    }
212	    let sym = prop_ident(ctx, l, "symbol")?;
213	    let (fw, fh, ax, ay) = symbol_attach(&sym)?;
214	    // the drawing node
215	    let path = n.children.iter().cloned().find(|&c| has(ctx, c, "sch-tag-line"))?;
216	    let (pw, ph) = if rot == 90 || rot == 270 { (fh, fw) } else { (fw, fh) };
217	    let (px, py) = map_pt(ax, ay, fw, fh, rot, mirror);
218	    let o = origin_in(ctx, path, l);
219	    // the drawing's frame sits at its group origin
220	    let _ = (pw, ph);
221	    let pt = (o.0 + px, o.1 + py);
222	    if std::env::var("LINI_SCH_DBG").is_ok() {
223	        eprintln!("label {} w {:?} path.x {:?} geo {:?} o {:?} pt {:?}", l, w, ctx.nodes[path].x, ctx.nodes[path].geo_off, o, pt);
224	    }
225	    // the wire leaves away from the drawing
226	    let (cx, cy) = (o.0 + pw / 2.0, o.1 + ph / 2.0);
227	    let dir = Dir::of_vec(pt.0 - cx, pt.1 - cy);
228	    Some((Kind::Symbol, pt, dir, None))
229	}
