246	        match toward {
247	            Dir::R => t.off = r,
248	            Dir::L => t.off = l,
249	            Dir::U => t.off = (0.0, -tag_half(ctx, t.dev).1),
250	            Dir::D => t.off = (0.0, tag_half(ctx, t.dev).1),
251	        }
