258	// a link end as a term
259	pub fn term(ctx: &Ctx, scope: usize, node: usize) -> Option<Term> {
260	    let dev = device_of(ctx, scope, node)?;
261	    if has(ctx, node, "pin") {
262	        // the stub's far end
263	        let stub = ctx.nodes[node].children.iter().cloned().find(|&c| has(ctx, c, "pin-stub"))?;
264	        let side = ctx.comp[stub].pin.clone().unwrap_or_default();
265	        let dir = Dir::of_side(side.split_whitespace().next().unwrap_or("left")).unwrap_or(Dir::L);
266	        let o = origin_in(ctx, stub, dev);
267	        let pts = match &ctx.nodes[stub].geo {
268	            Some(crate::scene::Geo::Points(p)) => p.clone(),
269	            _ => vec![(0.0, 0.0), (20.0, 0.0)],
270	        };
271	        let mut best = (o.0 + pts[0].0, o.1 + pts[0].1);
272	        let score = |p: (f64, f64)| -> f64 {
273	            let v = dir.vec();
274	            p.0 * v.0 + p.1 * v.1
275	        };
276	        for p in &pts {
277	            let q = (o.0 + p.0, o.1 + p.1);
278	            if score(q) > score(best) {
279	                best = q;
280	            }
281	        }
282	        return Some(Term { node, dev, kind: Kind::Pin, off: best, dir, through: None });
283	    }
284	    if node != dev && is_part(ctx, dev) && ctx.nodes[node].id.is_some() {
285	        let o = origin_in(ctx, node, dev);
286	        let dir = Dir::of_vec(o.0, o.1);
287	        return Some(Term { node, dev, kind: Kind::Station, off: o, dir, through: None });
288	    }
289	    if node == dev && is_label(ctx, node) {
290	        let (kind, off, dir, through) = label_term(ctx, node)?;
291	        return Some(Term { node, dev, kind, off, dir, through });
292	    }
293	    let _ = is_component;
294	    Some(Term { node, dev, kind: Kind::Other, off: (0.0, 0.0), dir: Dir::R, through: None })
295	}
