298	pub fn wires(ctx: &Ctx, scope: usize) -> Vec<Wire> {
299	    let mut out = Vec::new();
300	    for (li, l) in ctx.links.iter().enumerate() {
301	        if l.container != scope {
302	            continue;
303	        }
304	        let (a, b) = match (term(ctx, scope, l.from), term(ctx, scope, l.to)) {
305	            (Some(a), Some(b)) => (a, b),
306	            _ => continue,
