    match std::env::var("LINI_SCH_ROUND").as_deref() {
        Ok("up") => (v / PITCH + 0.5).floor() * PITCH,
        Ok("even") => {
            let k = v / PITCH;
            let f = k.floor();
            let r = if (k - f - 0.5).abs() < 1e-9 {
                if f % 2.0 == 0.0 {
                    f
                } else {
                    f + 1.0
                }
            } else {
                k.round()
            };
            r * PITCH
        }
        Ok("down") => (v / PITCH - 0.5).ceil() * PITCH,
        _ => (v / PITCH).round() * PITCH,
    }
}

