# for failing cases: differing node lines (any depth), first few, with the enclosing data-id
import sys, os, subprocess, re
for f in sys.argv[1:]:
    d = os.path.dirname(os.path.abspath(f)); b = os.path.basename(f)
    o = subprocess.run(['/workspace/executable', b], cwd=d, capture_output=True, text=True).stdout
    m = subprocess.run(['/tmp/bin-sch/executable', b], cwd=d, capture_output=True, text=True).stdout
    if o == m:
        continue
    ol = o.split('\n'); ml = m.split('\n')
    if len(ol) != len(ml):
        print('==', b, 'line count differs', len(ol), len(ml))
        continue
    diffs = []
    cur = ''
    for a, c in zip(ol, ml):
        mm = re.search(r'data-id="([^"]+)"', a)
        if mm and '<g class="lini-node' in a:
            cur = mm.group(1)
        if a != c and 'lini-scope' not in a and 'lini-links' not in a:
            if '<path d=' in a and 'lini-link' not in a and 'sch-' not in a:
                pass
            diffs.append((cur, a.strip()[:110], c.strip()[:110]))
    print('==', b, len(diffs))
    for x in diffs[:3]:
        print('   @', x[0]); print('     O', x[1]); print('     M', x[2])

